window.REBO_CONTENT={"meta":{"title":"التربية الفنية — المرحلة المتوسطة","subtitle":"دليل المعلم والخطط الأسبوعية","source":"دليل معلم التربية الفنية للمرحلة المتوسطة","version":"1.0.0"},"index":[{"n":1,"title":"المقدمة","grade":"عام","pages":"3–3"},{"n":2,"title":"أهداف مادة التربية الفنية في المرحلة المتوسطة","grade":"عام","pages":"5–5"},{"n":3,"title":"التوجيهات العامة","grade":"عام","pages":"6–7"},{"n":4,"title":"الأهداف التدريسية في التربية الفنية (أهميتها، أنواعها، أسس صياغتها)","grade":"عام","pages":"8–8"},{"n":5,"title":"عناصر العملية التعليمية","grade":"عام","pages":"9–10"},{"n":6,"title":"طرائق التدريس والتدريب","grade":"عام","pages":"10–13"},{"n":7,"title":"أسس وعناصر التكوين في العمل الفني","grade":"عام","pages":"14–15"},{"n":8,"title":"الصف الأول المتوسط - الوحدة الأولى: التعبير الفني","grade":"الأول المتوسط","pages":"17–29"},{"n":9,"title":"الصف الأول المتوسط - الوحدة الثانية: التصميم والزخرفة","grade":"الأول المتوسط","pages":"30–45"},{"n":10,"title":"الصف الأول المتوسط - الوحدة الثالثة: التشكيل الفني والهندسي","grade":"الأول المتوسط","pages":"46–72"},{"n":11,"title":"الصف الأول المتوسط - الوحدة الرابعة: التذوق وتاريخ الفن","grade":"الأول المتوسط","pages":"73–78"},{"n":12,"title":"الصف الثاني المتوسط - الوحدة الأولى: التعبير الفني والهندسي","grade":"الثاني المتوسط","pages":"80–96"},{"n":13,"title":"الصف الثاني المتوسط - الوحدة الثانية: التصميم والزخرفة","grade":"الثاني المتوسط","pages":"97–106"},{"n":14,"title":"الصف الثاني المتوسط - الوحدة الثالثة: التشكيل المجسم","grade":"الثاني المتوسط","pages":"107–138"},{"n":15,"title":"الصف الثاني المتوسط - الوحدة الرابعة: التذوق الفني وتاريخ الفن","grade":"الثاني المتوسط","pages":"139–142"},{"n":16,"title":"الصف الثالث المتوسط - الوحدة الأولى: التعبير الفني والهندسي","grade":"الثالث المتوسط","pages":"144–156"},{"n":17,"title":"الصف الثالث المتوسط - الوحدة الثانية: التصميم والزخرفة","grade":"الثالث المتوسط","pages":"157–163"},{"n":18,"title":"الصف الثالث المتوسط - الوحدة الثالثة: التشكيل المجسم","grade":"الثالث المتوسط","pages":"164–184"},{"n":19,"title":"الصف الثالث المتوسط - الوحدة الرابعة: التذوق وتاريخ الفن","grade":"الثالث المتوسط","pages":"185–189"},{"n":20,"title":"مفردات الأنشطة المسرحية للمرحلة المتوسطة","grade":"عام","pages":"190–190"}],"intro":{"title":"التربية الفنية — المقدمة","sections":[{"title":"المقدمة","paras":["تحظى التربية الفنية بإهتمام التربية والتعليم لإسهامها الكبير في إعداد الطلبة فكراً وذوقاً ومهارة ، فضلاً عن الجوانب النفسية والاجتماعية والانسانية والثقافية المتعددة . وتسهم في تطوير مهارات الفرد وإضفاء الثقافة الفنية والقيم الجمالية فترتقي بالذوق الفني بشكل خاص . فضلاً عن دورها الفاعل في تنمية حواس الفرد ومداركه والقدرة على الخيال والابداع والابتكار . لذا تُعّد التربية الفنية ضرورة ثقافية ترتقي بأفكار الطلبة وتعرفهم طبيعة الفنون في العالم ومميزاتها وخصائصها وتطورها عبر العصور ."]},{"title":"انواع طرائق التدريس","paras":["أ - الطرائق التي يكون مركزها المدرس هي","طريقة المحاضرة : وهي عرض شفهي مستمر باسلوب اخباري لبيانات ووقائع واحداث ، ويظل المدرس هو الملقن او المتكلم والطلبة مستمعون . ويفضل المدرسون استخدامها لان باستطاعتهم ضخ أكبر قدر ممكن من المعلومات في أقصر وقت .","طريقة العرض : وهي تشبه المحاضرة ولكنها تقترن بإجراء تجربة عملية او عرض مهارات يدوية بالرسم او النحت ... او عرض مسرحي او أي تمرين عملي يقدمه المدرس ، ويتدرج في اداء اجراء معين وبشكل مضبوط عن طريق اتقان خطوات اكتساب مهارة معينة .","ب - الطرائق التي يكون مركزها الطلبة","طريقة المناقشة : يكون المدرس مسؤولاً عن ادارة دفة الحوار والمناقشة ، وهذه الطريقة تثير انتباه الطلبة ، و تزيد من ثقة الطالب بنفسه ، والاطلاع على مختلف وجهات النظر للموضوع المطروح . ويجري بعد المناقشة التنفيذ العملي.","طريقة النمذجة التعليم عن طريق المحاكاة والتشبيه","طريقة المشروع : وهي نوعان فردية وجماعية وهذه الطريقة تشجع الطالب على البحث واكتساب المهارات واساليب التفكير والاعتماد على النفس وتنمي في العمل الجماعي روح المحبة والتعاون","التعلم التعاوني : هو اسلوب - تعليمي - تعلّمي ، يقسم فيه الطلبة على مجموعات صغيرة متكونة من ٣ أعضاء غير متكافئة في القُدرات والتحصيل","التعليم الانفرادي: وهي طريقة مبتكرة في التعليم تعنى بالفروق","طريقة التعبير الحر : وهي التصريح لرغبات الفرد بالانطلاق","طريقة التتلمذ"]},{"title":"الأهداف العامة لمادة التربية الفنية في المرحلة المتوسطة","paras":["تطوير قدرات الطلبة في اختيار المجالات الفنية المناسبة لميولهم .","تشجيع الطلبة على التعبير الفني الحر لتنمية الشخصية الفنية وتأكيد الثقة بالنفس .","تنمية القيم الانسانية والاجتماعية والثقافية .","تنمية القدرات الابداعية الفنية في ممارسة العمل الفني .","تنمية روح الابتكار وحل المشكلات .","تنمية الوعي الادراكي للطلبة باستثمار ميولهم الفطرية لمختلف الاتجاهات الفنية والتعبير عن ذاتهم .","تنمية مواهب الطلبة في توليف وتطويع الخامات لانتاج اعمال فنية جديدة ومبتكرة .","التدريب على التفسير وتحليل الاعمال الفنية ونقدها .","تأكيد السلامة المهنية والصحية في استخدام المستلزمات والادوات الفنية في اثناء العمل .","تنمية روح التعاون والنظام وتحمل المسؤولية بانجاز الاعمال الفنية المختلفة .","تنمية قدرة الطلبة على الاحساس الجمالي."]}],"maps":[{"grade":"الأول","units":[{"name":"الأولى / التعبير الفني","items":[]},{"name":"الثانية / التصميم والزخرفة","items":[]},{"name":"الثالثة / التشكيل الفني والهندسي","items":["أشغال الورق المقوى","النحت والفخار","أشغال الخشب","أشغال المعادن","خامات بيئة واشغال حرة"]},{"name":"الرابعة / التذوق وتاريخ الفن","items":[]}]},{"grade":"الثاني","units":[{"name":"الاولى / التعبير الفني والهندسي","items":[]},{"name":"الثانية / التصميم والزخرفة","items":[]},{"name":"الثالثة / التشكيل المجسم","items":["النحت والفخار","أشغال القصب","أشكال الورق المقوى والجلود","أعمال الجلود","أشغال الخشب","أشغال المعادن","الطباعة","النسيج والحياكة"]},{"name":"الرابعة / التذوق الفني وتأريخ الفن","items":[]}]}]},"units":[{"id":"08","grade":"الصف الأول المتوسط","unitName":"الوحدة الأولى","title":"الصف الأول المتوسط - الوحدة الأولى: التعبير الفني","pages":"17–29","objectives":"تنمية معرفة الطالب بموضوع «الصف الأول المتوسط - الوحدة الأولى: التعبير الفني» وفهم محاوره وممارساته الفنية كما عرضها دليل المعلم.","specific":["أن يتعرف الطالب إلى محور «اعطاء نبذة عن التخطيط والمواد والأدوات المستعملة فيه ) القلم الرصاص ،».","أن يتعرف الطالب إلى محور «اعطاء فكرة عن الالوان الاساسية ومشتقاتها وخواصها».","أن يتعرف الطالب إلى محور «اعطاء فكرة مبسطة عن المنظور ) الخطوط وانواعها ، السطوح ، خط الافق»."],"tools":"الخامات والأدوات الواردة في الدليل: القلم الرصاص، الحبر الصيني، الفحم، الأصباغ، الماجك، الفرشاة.","intro":"تهيئة مقترحة: يعرض المعلم مثالاً من موضوع «الصف الأول المتوسط - الوحدة الأولى: التعبير الفني»، ثم يطلب من الطلبة وصف ما يلاحظونه وتحديد الفكرة الفنية التي يعالجها الدرس.","summary":["اعطاء نبذة عن التخطيط والمواد والأدوات المستعملة فيه ) القلم الرصاص ،؛ الحبر الصيني ، الفحم ، اقلام الأصباغ ، الماجك ، وغير ذلك ( . وتنفيذ موضوعات على أصول الرسم المبسط مما ينمي عند الطلبة ادراك أن الخط هو…","اعطاء فكرة عن الالوان الاساسية ومشتقاتها وخواصها؛ الالوان الاساسية : أصل الالوان جميعها ثلاثة هي : الاصفر ، الازرق ، الاحمر - أ وسميت بالاساسية لانه لا يمكن استنباطها من الالوان الاخرى ، وبمزجها »ضوئياً…","اعطاء فكرة مبسطة عن المنظور ) الخطوط وانواعها ، السطوح ، خط الافق؛ المجسمات .. الخ ( مع تطبيق عملي من الواقع . إن المنظور هو مجموعة من القواعد أو الحلول التي توصل اليها الفنان بالممارسة الفعلية للفنون…","خط الأرض : وهو الخط الذي تستند اليه الأعمدة الكهربائية أو الاشجار او الابنية؛ أو الاشخاص ... الخ . خط الافق : أو ) مستوى النظر ( هو الخط الذي يكون بارتفاع بصر المشاهد عن: المستوى الذي يقف فيه ويكون غير ثابت…","خطوط التلاشي : وهي الخطوط التي تُرسم من نهاية الشكل وأعلاه ) الشكل؛ المرسوم( وتنتهي الى نقطة التلاشي ، وهي التي تحدد ارتفاع الشكل مقارنة بالشكل الآخر في اللوحة . ) ينظر الشكل ( مجموعة اشخاص في اماكن مختلفة…"],"mcq":[{"n":1,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 1 في ترتيب الدرس؟","options":["اعطاء نبذة عن التخطيط والمواد والأدوات المستعملة فيه ) القلم الرصاص","اعطاء فكرة عن الالوان الاساسية ومشتقاتها وخواصها","اعطاء فكرة مبسطة عن المنظور ) الخطوط وانواعها ، السطوح ، خط الافق"],"answer":"أ"},{"n":2,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 2 في ترتيب الدرس؟","options":["اعطاء نبذة عن التخطيط والمواد والأدوات المستعملة فيه ) القلم الرصاص","اعطاء فكرة مبسطة عن المنظور ) الخطوط وانواعها ، السطوح ، خط الافق","اعطاء فكرة عن الالوان الاساسية ومشتقاتها وخواصها"],"answer":"ج"},{"n":3,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 3 في ترتيب الدرس؟","options":["اعطاء فكرة عن الالوان الاساسية ومشتقاتها وخواصها","اعطاء فكرة مبسطة عن المنظور ) الخطوط وانواعها ، السطوح ، خط الافق","اعطاء نبذة عن التخطيط والمواد والأدوات المستعملة فيه ) القلم الرصاص"],"answer":"ب"}],"truefalse":[{"n":1,"q":"يتناول الدرس موضوع «اعطاء نبذة عن التخطيط والمواد والأدوات المستعملة فيه ) القلم الرصاص ،» ضمن محاوره. ( )","answer":"صح"},{"n":2,"q":"المحور الأول في ترتيب الدليل هو «اعطاء فكرة عن الالوان الاساسية ومشتقاتها وخواصها». ( )","answer":"خطأ"},{"n":3,"q":"يَرِد موضوع «التعبير عن موضوعات مستمدة من القصص الهادفة» ضمن محتوى هذا الدرس. ( )","answer":"صح"}],"answerKey":" الاختيار من متعدد: 1 ـ أ، 2 ـ ج، 3 ـ ب | الصح والخطأ: 1 ـ صح، 2 ـ خطأ، 3 ـ صح","topics":["اعطاء نبذة عن التخطيط والمواد والأدوات المستعملة فيه ) القلم الرصاص ،","اعطاء فكرة عن الالوان الاساسية ومشتقاتها وخواصها","اعطاء فكرة مبسطة عن المنظور ) الخطوط وانواعها ، السطوح ، خط الافق","خط الأرض : وهو الخط الذي تستند اليه الأعمدة الكهربائية أو الاشجار او الابنية","خطوط التلاشي : وهي الخطوط التي تُرسم من نهاية الشكل وأعلاه ) الشكل"],"sections":[{"title":"اعطاء نبذة عن التخطيط والمواد والأدوات المستعملة فيه ) القلم الرصاص ،","paras":["الحبر الصيني ، الفحم ، اقلام الأصباغ ، الماجك ، وغير ذلك ( . وتنفيذ موضوعات على أصول الرسم المبسط مما ينمي عند الطلبة ادراك أن الخط هو الأساس في تكوين الأشكال . لا يمكن انجاز اي عمل فني بدون أن يضع الفنان أو الطالب فكرة مبسطة عنه بحيث تتحول هذه الفكرة او الأفكار الى تخطيطات بسيطة أيضاً لتبيان طبيعة العمل سواء أ لوحة مرسومة كانت ام شكلاً مجسماً او تصميماً لاي عمل تجاري او معدني او غير ذلك .","ان الفكرة او الأفكار التي يراد تنفيذها ووضحت على الورق صممت لتكوين القاعدة الأساسية لأي عمل فني ليبرز من خلال استخدام مواد وأدوات وهذه المواد المستعملة هي التي تبين الخطوط العريضة لأبعاد العمل واعماقه أو ارتفاعه وما يتطلب من توضيحات أخرى .","ونود أن نعطي أيضاحاً لهذه المواد التي منها : القلم الرصاص : وهذه الاداة المعروفة في استعمالاتها وكيفية استخدامها في الكتابة والتخطيط : تكون على درجات متفاوته من مادة الرصاص التي تحتويها فهناك انواع ( B ) ( ، وهناك اقلام يقترن اسمها بH ) تسمى قلم رصاص يقترن باسم والنوعان الأول والثاني تتكون منها درجات من الرفع والسمك .","( في الرسم الهندسي لانها تعّد من الأقلام الجافة وهي H ) وتستخدم الأقلام ( فتستخدم في B ) ( أما أقلامH1 , H2 , H3 ، ..... ) بدرجات مختلفة مثل الرسم والتخطيط والتظليل لانها تعد من الأقلام الطرية وهي بدرجات أيضاً مثل (HB ) ( وتزداد طراوة تصاعدياً . وهناك أقلام نوعB2 , B4 , B6 ، ....... ) . تستخدم للكتابة الاعتيادية الحبر الصيني : وهذا النوع من الحبر يكون لونه اسود او الوان مختلفة .","ويستخدم في الرسم او التخطيط ، وتنفيذ التصاميم سواء أفي الادوات الهندسية أم تحديد خطوط الاشكال المرسومة ، إذ يقوم بعض الرسامين باستخدام هذا الاسلوب من الرسم ، او استخدام الفرشاة في رسوماتهم . وهناك نوع من الاقلام تدعى ب ) روترنك ( وتكون مختلفة الاحجام مملوءة بالحبر الصيني . تستخدم في التحبير وفي كثيرمن الاستخدامات . ويمكن استخدام الحبر الصيني بوساطة اقلام تدعى ب ) السلاية ( عند الرسم او التخطيط .","الفحم : ويوجد منه قلم الفحم ، او اعواد الفحم وتكون باحجام مختلفة . تستخدم هذه الاقلام في التضليل عند الرسم او في تخطيط الرسومات لتعطي درجات الظل والنور او التدرج الضوئي في الاشياء المرسومة . الماجك : وتدعى ايضاً بالاقلام ) السحرية ( وتكون الوانها براقة ومتعددة في اغراضها واستخداماتها .","مواد أخرى : وقد يستعين الطالب في تنفيذ رسوماته او لوحاته بمواد اخرى كالأصباغ الزيتية او الالوان المائية )البوستر ( وبالفرش الخاصة باستخدام هاتين المادتين ، وما يرافقهما من…"]},{"title":"اعطاء فكرة عن الالوان الاساسية ومشتقاتها وخواصها","paras":["الالوان الاساسية : أصل الالوان جميعها ثلاثة هي : الاصفر ، الازرق ، الاحمر - أ وسميت بالاساسية لانه لا يمكن استنباطها من الالوان الاخرى ، وبمزجها »ضوئياً ينتج اللون الابيض . غير اننا نعلم ان كل صبغة تمتص مركبات الضوء الابيض ما عدا لونها وعلى ذلك اذا مزجت الالوان الاساسية الثلاثة » صباغياً « ، امتصت مركبات الضوء جميعاً ، واعطت اللون الرمادي ، وقد يصل الى اللون الاسود حسب تركيز الالوان المستعملة .","وتسمى الالوان ) الابيض ، الرمادي ، الاسود( [ . Neutrals ] بالالوان الحيادية المطلقة الالوان الثانوية : اذا مزجنا لونين اساسين بنسب متساوية ، ينتج لون ثالث وهو - ب ما نطلق عليه اسم لون ثنائي ) ثانوي ( . وبهذا نحصل على ثلاثة ألوان ثنائية هي : ) الاخضر ، البرتقالي ، البنفسجي ( .","الالوان الثلاثية : ينتج اللون الثلاثي عند مزج لون ثنائي مع اللون الاساسي ينتج - ج لون ثلاثي مثلاً : بنفسجي = بنفسجي محمَر + أحمر بنفسجي = بنفسجي مزرَق + ازرق برتقالي = برتقالي محمَر+ أحمر برتقالي = برتقالي مصفر + اصفر اخضر = أخضر مصفر + أصفر أخضر = أخضر مزرق + أزرق أحد اللونين الأساسين اللذين + مع ملاحظة ان دمج الالوان يكون اللون الثانوي نتج عنهما مثلاً ) ان اللون الاخضر ناتج عن مزج الاصفر والازرق ( وهكذا ...","ثم بإمكاننا مزج لونين ثانويين مثلاً : ر + ) أصفر+ ( أزرق+ البرتقالي وهذا ناتج من ) أصفر+ اذا مزجنا : الاخضر أحمر( ، نجد هنا الالوان الاساسية الثلاثة التي تكون البني ) القهوائي ( . خواص اللون : واللون تحدده ثلاث خواص هي : ( وهي الصفة التي نسميه باسمها لنعرف ونميز اي لون من Hue ) كنه اللون- أ الآخر مثل : الأحمر ، الأصفر ، البرتقالي ، ....... الخ .","( ونقصد بها ان اللون فاتح او غامق ، فاذا زدنا عليه Value ) القيمة أو الدرجة- ب في حالة الالوان المائية يزاد الماء لفتح اللون ، واذا زيد اليه الاسود، - الابيض ازداد لونه غمقاً ، فأننا بذلك نغير في قيمة اللون وليس في كنهه . ( Intensity ) الشدة- ج هذه الخاصية تصف او تميز قوة اللون ، اي مقدار زهائه ونقائه ، فبعض الالوان قوية نقية زاهية ، و بعضها الآخر ضعيف غير زاه .","ان الشدة هي الصفة التي تدلنا على قرب اللون او ابتعاده من درجة النقاء ."]},{"title":"اعطاء فكرة مبسطة عن المنظور ) الخطوط وانواعها ، السطوح ، خط الافق","paras":["المجسمات .. الخ ( مع تطبيق عملي من الواقع . إن المنظور هو مجموعة من القواعد أو الحلول التي توصل اليها الفنان بالممارسة الفعلية للفنون التشكيلية ، والتي بوساطتها نتمكن من تحقيق البعد الثالث او العمق الذي نشاهده ونحسه ، على سطح مستوي ذي بعدين فقط والذي نسميه اللوحة ، وبمعنى آخر أننا نتمكن باستعمالنا لتلك القواعد من التعبير عن الاشكال والمواضيع التي نشاهدها حسب موقعها وبعدها عنا ، وعلاقة تلك الأشكال بعضها ببعضها الآخر .","ولقد كان المنظور وما يزال عبارة عن مجموعة من القواعد والاسس التي تكون احد العناصر الاساسية في علوم الفنون ، اذ يؤدي دوراً كبيراً واساسياً في تطوير الفنون التشكيلية ويسهم في تطوير الفنان واحساسه ، فضلاً عن كونه عاملاً مساعداً في تطوير الحياة الاجتماعية والاقتصادية والصناعية ، لعلاقته الوثيقة بالعلوم الهندسية والرياضية ، فضلاً عن ميزاته الجمالية البحتة ، وبدون المنظور لا يتمكن المهندس والمصمم والمعماري من ممارسة نشاطه وابداعه ، فضلاً عن الفنان التشكيلي الذي يمارس شتى انواع الفنون التشكيلية .","والهدف من دراسة المنظور هو معرفة البعد الثالث للشكل ويقصد به العمق الذي نحسه في الشكل على سطح مستوى ذي بُعدين وهو اللوحة أو الورقة . ان قواعد المنظور واسسه هي :"]},{"title":"خط الأرض : وهو الخط الذي تستند اليه الأعمدة الكهربائية أو الاشجار او الابنية","paras":["أو الاشخاص ... الخ . خط الافق : أو ) مستوى النظر ( هو الخط الذي يكون بارتفاع بصر المشاهد عن: المستوى الذي يقف فيه ويكون غير ثابت اذ يتغير بارتفاع المشاهد وانخفاضه . نقطة التلاشي : وهي النقطة التي يتلاشى بها الشكل المنظور اليه . ويمكن أن تكون: نقطتين او ثلاثة بحسب الشكل ."]},{"title":"خطوط التلاشي : وهي الخطوط التي تُرسم من نهاية الشكل وأعلاه ) الشكل","paras":["المرسوم( وتنتهي الى نقطة التلاشي ، وهي التي تحدد ارتفاع الشكل مقارنة بالشكل الآخر في اللوحة . ) ينظر الشكل ( مجموعة اشخاص في اماكن مختلفة من اللوحة وقواعد المنظور خلاصتها مبنية على أن الشكل كلما أبتعد عنا صغر حجمه كما موضح أعلاه .","ن نقطة التلاشي خط الأرض الخطوط : عندما نريد دراسة الأشكال الهندسية نهدف من ذلك الى دراسة بعض الظواهر الطبيعية التي تطرأ على تلك الاشكال نتيجة لموقع المشاهد واتجاه رؤياه منها، لأن الاشكال والمواضيع المرئية كلها تتغير وتفقد خواصها وصفاتها الاصلية و تصبح اشكالاً جديدة نتيجة لخضوعها لقواعد المنظور .","فالخطوط والسطوح والاجسام أذن تكون الوسيلة الاساسية للتعبير عما نشاهده في الطبيعة من اشكال ومواضيع وبوساطتها تتحول تلك الطبيعة الى لوحة مسطحة او نحت بارز وغيرها ، ولو القينا نظرة على ما يحيط بنا من اشكال كالصفوف والقاعات، وما تضمنته من اثاث وشبابيك ، واذا نظرنا الى البنايات والشوارع والاشخاص ... الخ نجد في الواقع انها عبارة عن اشكال هندسية .","اذن تكون الخطوط بانواعها والسطوح والاجسام المختلفة الوسيلة التي نعبر بها عن تلك الطبيعة فدراسة الاشكال الهندسية ضرورية قبل دراسة المبادىء الاساسية للمنظور ليتسنى لنا بوساطة تلك الاشكال الهندسية تطبيق تلك المبادىء والاسس على الطبيعة مباشرة . وتكون الخطوط بانواع مختلفة منها : الخطوط المجردة : وتكون هذه اما افقية او شاقولية، او مائلة وغيرها وكما موضحة في الأشكال الآتية .","الخطوط النسبية : وتكون أما متعامدة ، او خطوطاً مائلة متعامدة ، او خطوطاً متوازية وتسير باتجاه واحد . كما في الأشكال الآتية : خط افقي خط منقط متعرج متكسر قوس عمودي مائل ، الزوايا : اذ التقى خطان تتكون نتيجة التقائهما زاوية ، فهناك الزاوية القائمة والزاوية الحادة والزاوية المنفرجة ولا يؤثر طول الخط في نوع الزاوية .","لاحظ اشكال الزوايا السطوح : لابد من ثلاثة خطوط لتكوين سطح محدد ، ويسمى السطح في هذه الحالة مثلثاً ، والسطح يحتوي على بعدين فقط هما الطول والعرض من دون العمق، كسطح الورقة مثلاً . وهناك انواع عديدة من السطوح كالمربع ، والمستطيل ، والمنحرف ، وشبه المنحرف، والمخمس ، والشكل السداسي ، والمنحني ، والدائرة ... الخ . الاجسام أو الاحجام : أي شكل له ثلاثة ابعاد ، طول وعرض وعمق يسمى جسماً أو حجماً .","من الاجسام المهمة في هذه الفقرة ) فقرة المنظور ( هو المكعب ، وتأتي أهمية بعد المربع مباشرة لاحتوائه على ستة مربعات متساوية ، وأضلاعه متعامدة كلها ، والاسطوانة ، ومتوازي المستطيلات والهرم والمخروط والكرة وغيرها .","تنفيذ موضوعات مستمدة من بيئة الطالب من البيت والمدرسة يؤكد المربون تنفيذ موضوعات ترسم من بيئة الطالب سواء أكان مما يمارس في البيت من فعاليات ام نشاطات عائلية ،وعندما يطلب منه رسمها يفرغ ما كان مكوناً في جوارحه ويظهره بشكل لوحة تعبر عن مشاعره وادراكه وتفاصيل موضوعاته لأنه يعيشها يومياً .","والطالب في سن المرحلة المتوسطة أدرك الواقع وبإستطاعته التعبير عن موضوعاته بحس مرهف وعواطف جياشة تؤهله لإتمام عمله بحيوية ، لا سيما انه يلاقي التشجيع والرعاية ويمنح الثقة بنفسه لما يرسمه مما يقع امام نظره في البيت اوالشارع او المدرسة .","تنفيذ موضوعات تعبيرية بالرسم عن الطبيعة مباشرة ، ليتحسس الطالب: من خلال ادراك النسب بين العناصر والقيم اللونية ، و ذلك بتطبيق قواعد المنظور البسيطة ) المناظر الطبيعية من ابرز العناصر الجذابة والمحببة عند الطلبة ( فاللجوء مباشرة الى الطبيعية واندماج الطالب معها دائماً ، يجعله يحس بجمالها وما فيها من فتنة جذابة .","فالطالب تثيره حركات الطبيعة وتعبيراتها وما فيها من الوان واسرار ، تحرك مشاعره واحاسيسه ، فحين يطلب منه رسم المناظرالطبيعية ، فإنه بالتأكيد سيعطى رسماً يسجل فيه مشاعره وما يحسه من تعبيرات ، وسيكون المنظر مستوفياً القواعد الاساسية بتطبيق المنظور سواء أكان من ناحية الخط او ارتفاع الاشياء امامه وانخفاضها وقد يحسن الطالب التنسيق بانسجام الامور التي يتطلبها العمل الفني وهي ) الوحدة ، والاتزان ، وتوزيع الضوء( وبالتالي تظهر اللوحة التي يرسمها مستوفية الاصول والقيم التشكيلية .","رسم الموضوعات المستمدة من المناسبات والاعياد والموضوعات الانسانية. يفضل أن يقوم مدرسو التربية الفنية بالطلب من أبنائنا الطلبة رسم الموضوعات التي تستمد من المناسبات والاعياد لان ذلك يعني التعبير عن مكنونات الطلبة بما يجول بخواطرهم ازاءها وتذكيرهم بها .","والطلب برسم مجرياتها ويفضل ان يكون الطلب بعد مرور المناسبة ، حيث يعيش الطلبة تلك الابتهاجات والفعاليات لتصاغ لوحات ونتاجات فنية كل حسب أمكانياته وقدراته والتعبير عنها بخطوط وألوان وغير ذلك . التعبير عن موضوعات مستمدة من القصص الهادفة إن ذكر القصة أو المناسبة للطلبة كما وردت باحداثها ومجرياتها ، يجعل الطلبة يستلهمون معطياتها وما أفرزته من قيم يعتزون بها ، وتجعل الطالب يسير بهديها وما تحمله من معان سامية .","فضلاً عن تعلم الدقة في رسم حركات الانسان في هذه القصص ، وقد تكون القصص على السنة الحيوانات فيتعلم الطلبة رسمها بالتكرار لهذه الموضوعات."]}],"plates":["08_1.jpg","08_2.jpg"]},{"id":"09","grade":"الصف الأول المتوسط","unitName":"الوحدة الثانية","title":"الصف الأول المتوسط - الوحدة الثانية: التصميم والزخرفة","pages":"30–45","objectives":"تنمية معرفة الطالب بموضوع «الصف الأول المتوسط - الوحدة الثانية: التصميم والزخرفة» وفهم محاوره وممارساته الفنية كما عرضها دليل المعلم.","specific":["أن يتعرف الطالب إلى محور «فكرة عامة عن التصميم واغراضه ، من نحو تصميم الاغلفة والأعلانات».","أن يتعرف الطالب إلى محور «والتصميم انواع نذكر منه».","أن يتعرف الطالب إلى محور «التخطيط ) الدراسة التشريحية ( لا تدخل في ضمن محتويات الملصق المنجز»."],"tools":"الخامات والأدوات الواردة في الدليل: الألوان، الورق المقوى، القماش.","intro":"تهيئة مقترحة: يعرض المعلم مثالاً من موضوع «الصف الأول المتوسط - الوحدة الثانية: التصميم والزخرفة»، ثم يطلب من الطلبة وصف ما يلاحظونه وتحديد الفكرة الفنية التي يعالجها الدرس.","summary":["فكرة عامة عن التصميم واغراضه ، من نحو تصميم الاغلفة والأعلانات؛ بأنواعها التعليمية والتجارية إن للتصميم فوائد كبيرة في حياتنا اليومية إذ يعد الركن الرئيس من أركان الوسائل التعليمية فالنّشرات المدرسية وأغلفة…","والتصميم انواع نذكر منه؛ التصميم الصناعي : ويقصد به تصميم الاجهزة والأدوات والاثاث . - التصميم الطباعي : ويشمل تصميم المطبوعات كافة من صحف ومجلات واغلفة- . الكتب وتصميم الكارتات وبطاقات الدعوات والخ .....…","التخطيط ) الدراسة التشريحية ( لا تدخل في ضمن محتويات الملصق المنجز؛ بصورة نهائية وانما يأخذ بها المصمم ذهنياً يتبعه أو يتعلمه ويطبقة في اثناء التصميم. لا يحدد الملصق بشكل قطعي لقياسات معينة بل تكون المساحة…","ذكرنا سابقاً ان على المصمم ان يقتصد من اللون كَي لا يشتت إنتباه القارىء او؛ المشاهد ولكن في بعض الحالات قد تتطلب استخدام المزيد من الالوان ففي حالة في التلصيق ( أو استخدام صور فوتوغرافية- استخدام ) المونتاج…","تصميم الموضوعات التعبيرية او الزخرفية، وتنفيذها بأسلوب تفريغ؛ سطوح المقوى والطباعة عبر الفراغات . إن تصميم الموضوعات التعبيرية أو الزخرفية ، تساعد الطلبة في تنمية مهارتهم و تشجيعهم على الإبتكار والدقة في…"],"mcq":[{"n":1,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 1 في ترتيب الدرس؟","options":["فكرة عامة عن التصميم واغراضه ، من نحو تصميم الاغلفة والأعلانات","والتصميم انواع نذكر منه","التخطيط ) الدراسة التشريحية ( لا تدخل في ضمن محتويات الملصق المنجز"],"answer":"أ"},{"n":2,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 2 في ترتيب الدرس؟","options":["فكرة عامة عن التصميم واغراضه ، من نحو تصميم الاغلفة والأعلانات","التخطيط ) الدراسة التشريحية ( لا تدخل في ضمن محتويات الملصق المنجز","والتصميم انواع نذكر منه"],"answer":"ج"},{"n":3,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 3 في ترتيب الدرس؟","options":["والتصميم انواع نذكر منه","التخطيط ) الدراسة التشريحية ( لا تدخل في ضمن محتويات الملصق المنجز","فكرة عامة عن التصميم واغراضه ، من نحو تصميم الاغلفة والأعلانات"],"answer":"ب"}],"truefalse":[{"n":1,"q":"يتناول الدرس موضوع «فكرة عامة عن التصميم واغراضه ، من نحو تصميم الاغلفة والأعلانات» ضمن محاوره. ( )","answer":"صح"},{"n":2,"q":"المحور الأول في ترتيب الدليل هو «والتصميم انواع نذكر منه». ( )","answer":"خطأ"},{"n":3,"q":"يَرِد موضوع «فالزخرفة في مجال التعليم تحقق ما يأتي» ضمن محتوى هذا الدرس. ( )","answer":"صح"}],"answerKey":" الاختيار من متعدد: 1 ـ أ، 2 ـ ج، 3 ـ ب | الصح والخطأ: 1 ـ صح، 2 ـ خطأ، 3 ـ صح","topics":["فكرة عامة عن التصميم واغراضه ، من نحو تصميم الاغلفة والأعلانات","والتصميم انواع نذكر منه","التخطيط ) الدراسة التشريحية ( لا تدخل في ضمن محتويات الملصق المنجز","ذكرنا سابقاً ان على المصمم ان يقتصد من اللون كَي لا يشتت إنتباه القارىء او","تصميم الموضوعات التعبيرية او الزخرفية، وتنفيذها بأسلوب تفريغ"],"sections":[{"title":"فكرة عامة عن التصميم واغراضه ، من نحو تصميم الاغلفة والأعلانات","paras":["بأنواعها التعليمية والتجارية إن للتصميم فوائد كبيرة في حياتنا اليومية إذ يعد الركن الرئيس من أركان الوسائل التعليمية فالنّشرات المدرسية وأغلفة الكتب وبطاقات التهنئة والدعوات للمعارض اوالحفلات المدرسية وغيرها والمسرحيات والاعلانات بمختلف اغراضها التجارية منها والسياسية كلها تعتمد على التصميم .","ويتركز عنصر التصميم في المساحة وهي الحيز الذي يحدد شكله الخط وقد تكون منتظمة كالدائرة والمربع والمستطيل او المثلث او اي شكل هندسي ذي ابعاد معلومة . وقد تكون المساحة غير منتظمة اي تتساوى ابعاد اضلاعها . ويمكن تقديم دراسة تشريحية للاستعانة بها في توزيع العناصر الفنية ) النقطة ، الخط ، اللون ... الخ ( .","إن المركز الهندسي يمثل تقاطع اقطار الشكل ، اما المركز البصري فيضع فوق المركز الهندسي اذا كان رئيساً ، واذا احاط به فيكون ثانوياً . اما مركز الاهتمام فهو الذي يحدده الفنان في اي موقع يختاره . ويستطيع الفنان ان يوزع العناصر الفنية المطلوبة بما يلائم التصميم الذي يعزم على تنفيذه وبشكل مرتب وجميل ولا يخلو من الابداع والأبتكار .","وَيعّرف التصميم على انه ابداع الرسام او الفنان وابتكاره فكرة معينة ، فهو إذن فكرة تعّد بوساطة الرسم بطريقة ابداعية او ابتكارية ."]},{"title":"والتصميم انواع نذكر منه","paras":["التصميم الصناعي : ويقصد به تصميم الاجهزة والأدوات والاثاث . - التصميم الطباعي : ويشمل تصميم المطبوعات كافة من صحف ومجلات واغلفة- . الكتب وتصميم الكارتات وبطاقات الدعوات والخ ..... من المطبوعات تصميم الديكور : ويشمل تصميم الديكورات والزخارف الداخلية للابنيّة ، - . وديكور الأثاث تصميم الاقمشة : ويقصد به تصميم نقشات الاقمشة وزخارفها وطبعاتها وهي - .","على الاغلب تكون متكررة لتنتج الشكل النهائي - : وسنتحدث فيما يأتي عن بعض أنواع التصميم الطباعي تصميم اغلفة الكتب .. - أ غلاف الكتاب هو عنصر اساسي لتثبيت عائدية المصادر والمراجع ، اذ يعطيك عنوانه ومجال الاختصاص ، واسم المؤلف والجهة التي صدر عنها وسنة الطبع ومكانه وعدد النسخ التي طبعت منه وغيرها من المعلومات ، لذا اهتم المؤلفون به لانه اداة التعريف بما يحتويه الكتاب ، واحياناً يكون سبب في رواجه في المكتبات .","فعلى المصمم ان يختار العنصر المفاجىء والمؤثر في نفوس القراء من خط ولون وصورة بحيث يجلب بها انتباه القارىء على غلاف الكتاب من بين عشرات اغلفة الكتب المعروضة في المكتبة ، وعليه ايضاً ان يختار الرموز والعناصر التي تعبر عن مضمون الكتاب لتكون الفائدة اشمل .","كما ترى ان بعض الاغلفة تحتوي على كتابة فقط ، واحياناً اخرى كتابة وصورة او خطوط ورسوم ، بعضها يكون ملوناً وتكون مكلفة لطباعته حسب عدد الالوان الموجودة وبعضها قد يكون بلون واحد فقط وهذا اقل كلفة . ويمكن ملاحظة المخطط الآتي الذي يوضح توزيع العناصر في اغلفة الكتب بشكل عام ، وليست هذه قاعدة ثابتة في تصميم الأغلفة اذ يمكن تغيير موقع هذه العناصر.","في الشكلين نرى ان عنوان الكتاب احتل المركز البصري ، اما الشعار ) هوية الجهة المصدرة ( فإنه احتل الجزء الاعلى من يمين الناظر وهو يقع في ضمن الجزء الثانوي من صفحة الغلاف ، أما اسم المؤلف فقد اخذ الجزء الثانوي من اسفل الكتاب وبجهة اليسار كما ان هناك اختلافاً في حجم كتابةاسم المؤلف، فقد يكون اسم المؤلف في وسط المسافة من الجزء الثانوي ، أو يأخذ المركز البصري الأسفل وهو جزء ثانوي ايضاً ، ونلاحظ ان الرموز المستخدمة لها علاقة بعنوان الكتاب و كذلك الالوان مخطط لغلاف كتاب التي يعبر بها المصمم عن معنى الالوان واهميتها في تصميم الغلاف الفني ، فكلما كانت الرموز والالوان قليلة ومعبرة كان التصميم جيداً وناجحاً .","اي يجب ان يقتصد المصمم في اللون وفي الرموز كي لا يشتت انتباه القارىء او عندما يقع تصميمه بين مئات او آلاف الأغلفة في المكتبة او المعرض . كذلك الأخراج الجيد والتنفيذ له أهمية في الغلاف . الاعلان : اصبح الاعلان في العصر الحديث يمثل ضرورة لا…"]},{"title":"التخطيط ) الدراسة التشريحية ( لا تدخل في ضمن محتويات الملصق المنجز","paras":["بصورة نهائية وانما يأخذ بها المصمم ذهنياً يتبعه أو يتعلمه ويطبقة في اثناء التصميم. لا يحدد الملصق بشكل قطعي لقياسات معينة بل تكون المساحة حسب الحاجة: للملصق وحسب قياسات معينة ان كان ثمة معرض او مسابقة معينة يتفق فيها على تحديد الملصق ."]},{"title":"ذكرنا سابقاً ان على المصمم ان يقتصد من اللون كَي لا يشتت إنتباه القارىء او","paras":["المشاهد ولكن في بعض الحالات قد تتطلب استخدام المزيد من الالوان ففي حالة في التلصيق ( أو استخدام صور فوتوغرافية- استخدام ) المونتاج ، او الكولاج ملونة نرى ان عدد الالوان يزيد على سبعة او عشرة الوان ، ولكن يجب مراعاة زيادة عدد الالوان فكلما كانت الالوان قليلة ومعبرة عن فكرة الملصق كان وصول الرسالة الى المشاهد اسهل ، وأن الزيادة غير اللازمة لعدد الالوان سوف تشتت انتباه المشاهد، وهذا ما يجب ملاحظته في تصميم الملصق .","تصميم البطاقة - ج البطاقة : وسيلة اتصال بصرية تحدد زمان ومكان ومناسبة ما وينتهي مفعولها بانتهاء زمان الدعوة او المناسبة ، وقد تهمل بمجرد قراءتها او قد يحتفظ بها الشخص المدعو اذا كانت المناسبة محببة اليه او عزيزة عليه او قد اعجب بجمالهاوجمال التصميم أو الالوان او نوعية الورق المستخدم او للعبارات التي تحملها .","اذ ان لهذه البطاقة وقائع نفسية بين الداعي والمدعو وقد تسبب هذه البطاقة ربط اواصر المحبة او قد تكون سلبية اذا كان التصميم او الصور المعبر عنها غير لائقة . اذا كانت البطاقة صفحة واحدة ) شكل كارت ( ، وهنا قد تحمل الكتابة فقط ويبرز جمالها شكل الخط ) نوعيته ( وطريقة الطبع وقد يكون الحرف بارزاً او غائراً ويكون لون الخط بالوان جميلة وجذابة ، او استخدام اللون الذهبي او الفضي في كتابتها .","وقد تحمل زخارف نباتية او هندسية حسب نوع المناسبة او قد تكون ارضية البطاقة على شكل رسوم او رسم معين معبر عن المناسبة ويراعى ما نريد ان يبرز في البطاقة من رسم أو كتابة أو زخرفة . أما اذا كانت البطاقة مطوية فتكون طية واحدةً او اثنَين حسب الحاجة ذات صفحتين فتحمل الصفحة الاولى عادة - مثل غلاف الكتاب- او ثلاث .","فاذا كانت صفحتين بعض الرسوم او الزخارف او الزهور محلاّة بالوان جذابة وجميلة او قد تكون بعض الرسوم بارزة اوغائرة على الورق اوقد تحُفر وتجسم على الصفحة الاولى . اما الصفحة الثانية فتحتوي العبارة المراد ايصالها للشخص المدعو ."]},{"title":"تصميم الموضوعات التعبيرية او الزخرفية، وتنفيذها بأسلوب تفريغ","paras":["سطوح المقوى والطباعة عبر الفراغات . إن تصميم الموضوعات التعبيرية أو الزخرفية ، تساعد الطلبة في تنمية مهارتهم و تشجيعهم على الإبتكار والدقة في العمل ، و كذلك إكتساب مهارات الطلبة اليدوية وتعويدهم على دقة القياس ، كل ذلك يجعل الطلبة يقدرون ملكة الجمال والأتزان والأنسجام ، والتعود على العمل الدقيق المنظم .","ومن أجل ترسيخ ما تقدم يطلب من الطلبة أن يقوموا بعمل تصميمات من وحدات تعبيرية أو زخرفية تناسب اللوحة المراد أنجازها وهنالك عدة ممارسات أو فعاليات أو أنشطة يمكن أتباعها في تنفيذهم الموضوعات ، والقيام بطباعتها على الورق المقوى أو على الاقمشة وغيرها . - : وهنالك عدة أساليب وطرائق في تنفيذ هذه الموضوعات منها عمل زخرفة من الخطوط المتعرجة ، وتفريغ هذه الزخرفة على الرسم وطباعتها. - .","عمل وحدات زخرفية من أشكال هندسية ، وحفر هذه الزخرفة وطباعتها- . عمل زخرفة من ورق الأشجار على قطعة من الورق المقوى وطباعة محيطها- . عمل أطر لزخرفة جميلة وطباعتها- . تفريغ موضوعات تعبيرية متنوعة وطباعتها- . عمل زخارف من وحدات مقصوصة من الورق وطباعتها . تزيين أو زخرفة بطاقة لمناسبة الأعياد- طبع اطار بالقالب الزخرفي ، باختيار وحدة مناسبة ، والافادة من الخامات- .المحلية .","نورد مثلاً على أحدى الطرائق كما يأتي نأخذ قطعة من الورق المقوى ، ونرسم الوحدة الزخرفية المطلوبة وحسب التصميم - . نفرغ الوحدة الزخرفية المصممة كما جاء في أعلاه . نأخذ ورقة خاصة بالرسم ، وحسب الحاجة- . نضع الورقة ذات الوحدة الزخرفية والمفرغة على الورقة الكبيرة- . نهيىء الألوان التي يراد تلوين الانموذج المفرغ ، حسب ما جاء في التصميم- نبدأ بوضع الورقة ) القالب ( على الورقة الكبيرة ، التي قمنا بتقسيمها حسب- .","حاجتنا لأبراز الأنموذج وبشكل يوحي بالأتزان والأنسجام نرفع ) القالب الزخرفي ( الى قسم آخر ونلون الفراغ فيه ، وهكذا حتى ننتهي - .","من تلوين الورقة الكبيرة المراد زخرفتها أنموذج شكل مفرغ الأنموذج الاول لوحة مطبوعة بوساطةالتفريغ أنموذج شكل مقصوص الانموذج الثاني لوحة مطبوعةبوساطة الرسم التعرّف على الآلات الهندسية وطرائق استخدامها: يحتاج الطلبة الى استخدام الكثير من المواد والآلات في تنفيذ الاعمال التي يكلفون بانجازها او اتمامها ، سواء كان ذلك يتعلق بتنفيذ الموضوعات الهندسية أم مالها علاقة في الموضوعات التصميمية و على هذا الاساس يفضل والحالة هذه أن يتعرف الطلبة الآلات الهندسية وكيفية استخداماتها وكذلك العناية بها وصيانتها ويجب أن تكون ادوات الرسم دقيقة ومضبوطة اذ هي العنصر الاساس في العمليات الهندسية والرسم الهندسي ، وعليه يحتاج الطلبة الى معرفتها معرفة تامة ليحافظوا عليها ويحسنوا استعمالاتها .","وتنفيذها على الورق او الأواني والأدوات تعني كلمة الزخرفة ) الزينة ( ومعناها تجميل الشيء سواء أسطحاً كان أم جسماً و الزخرفة هذه الوسيلة التزينية ظهرت منذ ظهور الانسان على هذه الأرض . فإن تزيينات الكهوف والمغارات ومقابض الأدوات التي استعملها الانسان منذ القدم كانت دلالة على حبه للتجميل .","وقد مرت الزخرفة بتطورات عبر السنين ، وكانت آثارها واضحة في المعالم الحضارية في معظم ارجاء العالم ، وآثارها متميزة متنوعة تبعاً لظروفها وبيئاتها . ولقد دخلت العناصر والوحدات الزخرفية في شتى ميادين الأعمال الفنية وظهرت مع الرسم وفي النحت ، العمارة والتصميم وغيرها . إن َّ الرسوم والأشكال الزخرفية ذات التنسيق والانسجام المبتكر تبعث في النفس الارتياح وتشيع فيها الغبطة والسرور .","والغرض من تدريس الزخرفة في دروس التربية الفنية هو أن الزخرفة جزء لا يتجزأ من الجمال المحيط بنا ، فاذا تولتها يد الإنسان ورعتها وغذتها وزادت على الأشكال والمساحات قيماً جمالية ، فإنها تبرز معالمها واياتها البديعة لا سيما التي تنفذ ببساطة فإنها ايضاً تظهر محاسنها وتبدو نتاجاتها جذابة . والزخرفة والتنسيق والتزيين والتجميل كلها مميزات محببة للإنسان واصيلة في حياته ووجوده .","وما تنسيق محتويات المنزل وحجراته واختيار الملابس بتصميماتها الجميلة ، إلاّ تأكيد أصالة حس الانسان الجمالي ونزوعه الزخرفي . فالزخرفة في مجال التعليم تحقق ما يأتي تعويد الطلبة على التنسيق والتنظيم في الأعمال الفنية . - . تنمية خيال الطلبة ودفعهم للإبتكار والتجديد والإنشاء- تربية أذواق الطلبة والحس الجمالي لديهم ، للوصول الى درجة من النضج- .","والكمال إكساب الطلبة بعض المهارات والعادات في أثناء ممارسة بعض التصميمات كالدقة- . والإتزان وادراك العلاقات الشكلية إن عناصر الزخرفة ووحداتها كثيرة لا تعد ولا تحصى ، فهي موجودة في الطبيعة والجمال وفي معالم التراث الحضاري كلها ، ويمكن للطلبة أن يستلهموها من هذه المصادر .","وللزخرفة مثل ما لغيرها من الفنون قواعد واصول تقوم عليها ، ونعني بقواعد الزخرفة : الطريقة التي بوساطتها وبإتباعها يمكن وضع تصميمات ورسوم لوحدات زخرفية بسيطة طبيعية ونعني بها عناصر الوحدات النباتية والحيوانية والآدمية وكذلك عناصر الوحدات الهندسية .","لقد عني العرب بطرائق الزخرفة واساليبها ، ورتب الفنان العربي الوحدات الزخرفية ترتيباً غير مسبوق ، ولاءم بينها بطريقة مبتكرة ، ونسق بين اجزائها تنسيقاً جعلها تبدو جميلة وتستمد الزخرفة عناصرها ووحداتها الزخرفية من الطبيعة .","وتستند هذه العناصر والوحدات الى الخيال والقواعد الفنية ، وأخضع الفنان العربي والمسلم هذا الخيال وهذه القواعد الى القوانين الزخرفية كالتكرار والتماثل والتقابل والتوازن والتشعب ، وهذه الأساليب هي الأسس الرئيسة الخاضعة لأصول الجمال الفني ، التي يقوم عليها فن الزخرفة . إن أساليب الزخرفة واصولها كثيرة واستخداماتها متعددة فقد استخدمت على الورق وفي القماش وعلى الأواني وعلى المباني وعلى الأدوات وغيرها .","وبودنا أن نوضح بعضها وهي ) التكرار والتماثل والتشعب ( . وسنعطي بعض التطبيقات العملية عليها سواء ذلك كان فيما يخص الزخرفة الطبيعية ) النباتية ، الحيوانية ، الآدمية ( أم الزخرفة الهندسية . : التكرار التكرار يقصد به رسم وحدة زخرفية واحدة طبيعية كانت ام هندسية ثم تكرر عدة مرات وفي اتجاهات مختلفة لينتج عن ذلك تكوينات زخرفية طبقاً لما تتطلبه مقتضيات الموضوع المراد تنفيذه .","ولما كانت أساليب التكرارات كثيرة نذكر منها في سبيل المثال : التكرار العادي . التكرار العكسي . التكرار المتبادل . التكرارات الأفقية . التكرارات الرأسية . التكرارات المنحنية . التكرارات الدائرية ... الخ . التكرار العادي : وفيه تتجاوز وحدات الزخرفة او عناصرها ، وفي وضع ثابت واحد متواتر ، سواء ألأسطح شريطية مستقيمة او منحنية كانت أم لأسطح ممتدة كالمنسوجات أو دائرية كالحشوات .","والتكرار يعني تكرار الوحدات مرات على أبعاد متساوية في أتجاه أفقي او رأسي او مائل او منحني ، بحيث تتشابه الوحدات المتكررة جميعها…"]}],"plates":["09_1.jpg","09_2.jpg"]},{"id":"10","grade":"الصف الأول المتوسط","unitName":"الوحدة الثالثة","title":"الصف الأول المتوسط - الوحدة الثالثة: التشكيل الفني والهندسي","pages":"46–72","objectives":"تنمية معرفة الطالب بموضوع «الصف الأول المتوسط - الوحدة الثالثة: التشكيل الفني والهندسي» وفهم محاوره وممارساته الفنية كما عرضها دليل المعلم.","specific":["أن يتعرف الطالب إلى محور «الورق المقوى».","أن يتعرف الطالب إلى محور «أن يلم الطالب بمعرفة تكوين سطح » انفراد « المجسم المطلوب عمله ، ويرسم».","أن يتعرف الطالب إلى محور «عمل أنموذج للشكل المراد عمله من الورق المقوى ، ويكون هذا الأنموذج مما»."],"tools":"الخامات والأدوات الواردة في الدليل: الألوان، الطين، الجبس، الخشب، المعادن، القصب، الورق المقوى، الخيوط، القماش.","intro":"تهيئة مقترحة: يعرض المعلم مثالاً من موضوع «الصف الأول المتوسط - الوحدة الثالثة: التشكيل الفني والهندسي»، ثم يطلب من الطلبة وصف ما يلاحظونه وتحديد الفكرة الفنية التي يعالجها الدرس.","summary":["الورق المقوى؛ تصميم بعض المجسمات وتنفيذها ، والسعي الى تحويلها الى اشكال معمارية، - مثل العاب ، وأشياء نافعة ، وبعد زيادة ما يناسب ذلك من سطوح وزخارف والوان. أشغال الورق المقوى: إن دراسة هذا النوع من…","أن يلم الطالب بمعرفة تكوين سطح » انفراد « المجسم المطلوب عمله ، ويرسم؛ هذا السطح على الورق المقوى . أن يعرف كيفية تكوين الجسم بعد رسمه ، ثم يتمم عملية الصاقه ، ويجب: أن تكون الرسوم الخاصة بعمليات السطوح »…","عمل أنموذج للشكل المراد عمله من الورق المقوى ، ويكون هذا الأنموذج مما؛ يسهل بسطه وتكوينه ، ويكون » ملصقاً الصاقاً ضعيفاً « . يوضع لكل جزء من الأنموذج المعروض رقماً خاصاً لتمييزه عن الأجزاء: الاخرى . يقوم…","غطاء مصباح من الورق المقوى - أ؛ طريقة العمل نقسم محيط الدائرة الأولى بوساطة فتحة الفرجال ، وسنحصل على ستة نقاط: على المحيط . نوصل النقاط ببعضها ، اي الاقطار اولاً . نحصل على قطاعات ستة ، ونوصل: كذلك النقاط…","عمل حافظة نقود من الورق المقوى- ب؛ طريقة العمل للحصول على مجسم هندسي يكون بشكل حافظة نقود نتبع الخطوات الآتية : نفتح فتحة في احد جوانب المكعب من الاعلى ، بحيث تتسع هذه الفتحة لدخول: النقود . نقطع ورقة من…"],"mcq":[{"n":1,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 1 في ترتيب الدرس؟","options":["الورق المقوى","أن يلم الطالب بمعرفة تكوين سطح » انفراد « المجسم المطلوب عمله ، ويرسم","عمل أنموذج للشكل المراد عمله من الورق المقوى ، ويكون هذا الأنموذج مما"],"answer":"أ"},{"n":2,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 2 في ترتيب الدرس؟","options":["الورق المقوى","عمل أنموذج للشكل المراد عمله من الورق المقوى ، ويكون هذا الأنموذج مما","أن يلم الطالب بمعرفة تكوين سطح » انفراد « المجسم المطلوب عمله ، ويرسم"],"answer":"ج"},{"n":3,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 3 في ترتيب الدرس؟","options":["أن يلم الطالب بمعرفة تكوين سطح » انفراد « المجسم المطلوب عمله ، ويرسم","عمل أنموذج للشكل المراد عمله من الورق المقوى ، ويكون هذا الأنموذج مما","الورق المقوى"],"answer":"ب"}],"truefalse":[{"n":1,"q":"يتناول الدرس موضوع «الورق المقوى» ضمن محاوره. ( )","answer":"صح"},{"n":2,"q":"المحور الأول في ترتيب الدليل هو «أن يلم الطالب بمعرفة تكوين سطح » انفراد « المجسم المطلوب عمله ، ويرسم». ( )","answer":"خطأ"},{"n":3,"q":"يَرِد موضوع «يصنع المنسج المطلوب من قطعة من الكارتون وذلك بقصه من طرفيه بوساطة» ضمن محتوى هذا الدرس. ( )","answer":"صح"}],"answerKey":" الاختيار من متعدد: 1 ـ أ، 2 ـ ج، 3 ـ ب | الصح والخطأ: 1 ـ صح، 2 ـ خطأ، 3 ـ صح","topics":["الورق المقوى","أن يلم الطالب بمعرفة تكوين سطح » انفراد « المجسم المطلوب عمله ، ويرسم","عمل أنموذج للشكل المراد عمله من الورق المقوى ، ويكون هذا الأنموذج مما","غطاء مصباح من الورق المقوى - أ","عمل حافظة نقود من الورق المقوى- ب"],"sections":[{"title":"الورق المقوى","paras":["تصميم بعض المجسمات وتنفيذها ، والسعي الى تحويلها الى اشكال معمارية، - مثل العاب ، وأشياء نافعة ، وبعد زيادة ما يناسب ذلك من سطوح وزخارف والوان. أشغال الورق المقوى: إن دراسة هذا النوع من الاشغال اليدوية ، لها من المزايا الكبيرة مالا يستهان به . لأنها تقدم أمثلة محسوسة لما يدرس من الهندسة النظرية الخاصة بالمجسمات فيما بعد ، وتساعد الطلبة مساعدة جدية في فهم مبادىء تكوين الاشكال . واشغال الورق المقوى تحتاج الى أمرين :"]},{"title":"أن يلم الطالب بمعرفة تكوين سطح » انفراد « المجسم المطلوب عمله ، ويرسم","paras":["هذا السطح على الورق المقوى . أن يعرف كيفية تكوين الجسم بعد رسمه ، ثم يتمم عملية الصاقه ، ويجب: أن تكون الرسوم الخاصة بعمليات السطوح » الانفراد « هندسية دقيقة حتى تكون المجسمات المتكونة منها منتظمة . ونظراً لأهمية السطوح » الانفرادات « وضرورة مراعاة الدقة في عملها ، نورد هنا كيفية السير في خطوات العمل ."]},{"title":"عمل أنموذج للشكل المراد عمله من الورق المقوى ، ويكون هذا الأنموذج مما","paras":["يسهل بسطه وتكوينه ، ويكون » ملصقاً الصاقاً ضعيفاً « . يوضع لكل جزء من الأنموذج المعروض رقماً خاصاً لتمييزه عن الأجزاء: الاخرى . يقوم الطلبة برسم سطوح الانفراد الخاص بالأنموذج على الورق المقوى مباشرة،: على أن تراعى الدقة في الرسم والاحكام في التقدير والقياس . ويفضل رسم الخطوط بشكل واضح كي لا يختلط الامر بين الخطوط التي تثنى والخطوط التي تقص ."]},{"title":"غطاء مصباح من الورق المقوى - أ","paras":["طريقة العمل نقسم محيط الدائرة الأولى بوساطة فتحة الفرجال ، وسنحصل على ستة نقاط: على المحيط . نوصل النقاط ببعضها ، اي الاقطار اولاً . نحصل على قطاعات ستة ، ونوصل: كذلك النقاط بالمحيط ، ونحصل على مضلع سداسي ."]},{"title":"عمل حافظة نقود من الورق المقوى- ب","paras":["طريقة العمل للحصول على مجسم هندسي يكون بشكل حافظة نقود نتبع الخطوات الآتية : نفتح فتحة في احد جوانب المكعب من الاعلى ، بحيث تتسع هذه الفتحة لدخول: النقود . نقطع ورقة من المقوى تكون أكبر من مربع القاعدة ، ثم نلصقها تحت القاعدة ،: وذلك لزيادة استقرار المكعب ) الحافظة ( استقراراً جيداً . نرسم ستة مربعات ، أربعة منها بأتجاه واحد ، يتلاقى بمربعين ترتبط باحدى المربعات ويكون واحداً بالاعلى والآخر بالأسفل .","ويسمى هذا الرسم بانفراد سطوح المكعب . نحدد على المربعات الستة التي تكون المكعب الحواشي ) الحواف ( بقدر مناسب،: وذلك للصق المربعات التي تكون المكعب نقص الزوائد التي رسمت على الورق المقوى التي تحيط شكل المربعات مع الحواشي. بوساطة احدى ادوات القطع .","نسير رأساً مدبباً على الخطوط المرسومة للمربعات الستة ، وكذلك الحواشي،: وذلك من خلال مسطرة ، ونمرر الرأس المدبب على الخطوط ، ثم نثنيها لتكون الحدود للمربعات الستة بشكل جيد ومتقن ، ثم نصمغ الحواشي ليكون المكعب. النحت والفخار تنفيذ بعض الأشكال المجسمة من الطين الطبيعي او الاصطناعي بعد أن يعرف - أ الطلبة فكرة عن النحت البارز والمجسم ، وكيفية تحضير الطين . تنفيذ بعض الموضوعات التعبيرية أو الاواني النفعية عن طريق الفخار .","- ب لقد استخدم الانسان الطين منذ نشأته فلازم حياته واخضعه لحاجاته حيث صنع منه اوانيه وبعض ادواته التي يحتاجها في يومه ، كما كتب عليه تاريخه . وان المتاحف زاخرة بما خلفه الاوائل من الواح طينية تمكننا فيما بعد من معرفة حياتهم وكيف كانوا يعيشون .","وبتطور الزمن وعبر الاجيال الطويلة نمت وتطورت صناعة الطين واصبح لها أهمية كبرى ، وتفنن الصناع بهذه الخامة، وارتقت الزخرفة على الفخار وحملت بعض الاعمال الفخارية خطوطاً بسيطة واشكالاً هندسية ، واستطاع الانسان في تجاربه ومحاولاته ان يضفي عليها بعضاً من احاسيسه ومشاعره ، حتى بلغت صناعة الطين درجة عالية من الرقي والتقدم .","القاعدة ( حافظة نقود ) قاصة ولقد استخدم الانسان الة الدولاب ثم طورها واستعمل رجله بدلاً من يده لتكون اليد هي التي تتحكم بالطينة وتطوعها حسب التصاميم التي يروم تنفيذها ثم اخترع الدولاب الذي يدار كهربائياً ، مما سهل على الصانع جهداً كبيراً وظهرت الاشكال أكثر اتقاناً واحسن صورة .","وقد توصل الانسان بعد ان دفعته الحاجة الى ان يطلي مصنوعاته الفخارية بحيث أصبحت لماعة براقة هي ما ندعوها بالخزف او ) الفرفوري ( واصبح للفخار دراسات وللخزف اقسام تدرس فيها العلوم الخاصة بمواد التزجيج والطلي . وكذلك الافران الحرارية التي تحرق فيها هذه المصنوعات لتعطينا انواعاً لا تعد ولا تحصى من الاواني والتحف التي تحمل الموضوعات المختلفة .","ولقد أهتمت التربية الحديثة بما تحققه المواد الخام في ميدان التربية العملية وما تحققه للطالب من مهارات ، ومن هذه المواد الطين وهذه المادة المتوافرة بايدي الطلبة يمكن أن تشكل فيها اشياء كثيرة منها الأواني والتماثيل الصغيرة ، وهذه الأشكال تجعل الطالب يظهر ما في نفسه من تعبيرات نلمس فيها الحس الجمالي .","والطين يساعد في انماء الهوايات الفنية الكامنة في نفوس الطلبة ) القائمة على الخلق والأبداع وتنشط مكونات الشخصية المتكاملة ( . وليس من شك في أن مادة الطين تحقق اغراضاً عديدة منها . إيجاد الحركة الحيوية من النماذج والنسب بين الاجزاء . - . تكسب الطلبة القدرات والمهارات اليدوية- . تعويد الطلبة على دقة العمل وحسن الأنجاز- . اكساب الطلبة طرائق واساليب حديثة في عمل النماذج- . اكتساب المهارات وتدريب الحواس- .","ربط الاعمال الطينية في دروس التربية الفنية بدروس المواد الأخرى- . تنمية روح العمل الجماعي بالتعاون والمشاركة في… نصفي هذا السائل الطيني باحدى ادوات التصفية وقد تكون ) تيل شباك أو المنخل أوقماش ( . يترك الطين الصافي الذي تخلصنا من الشوائب العالقة به في مكان ويفضل وضعه: على قطعة من البلاستك حتى يجف او تجف منه بعض رطوبته .","نجمع هذا الطين الصافي والخالي من الشوائب في صندوق خشبي يفضل بداخله: صندوق من الزنك او غيره ، حتى نحافظ على رطوبته . يمكن تناول الكمية المطلوبة من الطين لإستخدامه في عمل الاشياء .","وبالامكان ان نعطي بعض الطرائق والأساليب في إنتاج الأشكال الطينية والأعمال الفنية ، تاركين لزملائنا المدرسين البحث عن أفضل الأعمال ، حيث أبداعاتهم لا تقف عند حد ، واثقين بقدراتهم ، وأن ما نعطيه من توجيه هو تذكيرهم أو معاونتهم في أداء واجبهم لا غير ، وهم المدركون حاجات الطلبة واعمالهم .","عمل لوحة لموضوع بارز تظهر فيها الحركة الطريقة يقوم المدرس بشرح واضح عن نوع العمل الذي سيقوم به الطلبة بوصفه موضوعاً ) ريليف ( ويمكن - بارزاً على الطين ، وهذه الطريقة تدعى في النحت ، نحت بارز - : اتباع احدى الطريقتين الآتيتين الحفر : بعد رسم الموضوع على قطعة الطين المعد على القاعدة المطلوبة المسطحة ، - أ يقوم الطالب بازالة الزوائد و ينحت في الطين حتى يبرز بشكله الجميل المطلوب ويسوى بالماء وينعم ويترك حتى يجف .","الاضافة : اي بعد رسم الموضوع على القاعدة يبدأ الطالب باضافة الطين الى -ب الشكل حتى تظهر الحركة ثم يسوى وينعم حتى يكتمل تماماً ، ويترك حتى يجف. وفي احيان كثيرة يصب قالب من الجبس فوق الموضوع المنجز ، والذي نحتاجه - : احياناً لصب مادة اخرى : وهذه الطريقة تكون كالآتي يهيأ الجبس ، ثم يمزج بالماء مزجاً جيداً وخفيفاً . - .","يصب رائب الجبس فوق الأنموذج الطيني ، ويترك حتى يجف- نحتفظ بالقالب الذي حصلنا عليه ، لكي نستعمله مرة أخرى ، وهنا يجب- استعماله لصب مادة اخرى كالجبس أو الاسمنت ، نقوم بدهن القالب الجبسي بدهن او زيت المكائن ليكون هذا عازلاً بين القالب والشكل الناتج .","« عمل أنموذج لأنسان في حالة حركة » تمثال مجسم الطريقة يقوم المدرس بتعريف الحركة في جسم الانسان ، ويفضل اعطاء نسب جسم الانسان كما هو معروف ، ويمكن الرجوع الى وحدات التعبير الفني في هذا الدليل. ثم يطلب المدرس من الطلبة رسم حركة الجسم الظاهرة والمطلوبة من قبلهم ، فقد تكون حركة لطالب يحمل كتاباً ، او طالب بحركة رياضية او عمل يومي يؤديه أشخاص في البيئة او الموضوعات الفلاحية وغيرها .","يبدأ الطالب بوضع الطين بدءاً بالقاعدة ، محاولاً اعطاء الحركة المطلوبة من - الارجل ثم الجسم ثم اليدين والرأس ، وهكذا يبقى الطالب يضيف الطين وينحته نحتاً دقيقاً مظهراً طيات أو ثنيات الملابس ويبقى يحاول ويدرس ويجسم الشكل حتى يكتمل العمل بصورته الجمالية ويترك حتى يجف . عمل أواني من الطين بوساطة الأشرطة أو اللفائف الطينية الطريقة يعد الطين اعدادً جيداً ) اي عجن وضرب ( حتى يصبح طيعاً للعمل . - .","نترك اختيار النماذج التي سيعملها الطلبة ، بأن يصمموها بأنفسهم- . ً يأخذ الطلبة الطين ، ويحاولون فركه حتى يصبح شريطاً او حبلاً طينيا- . ً تبنى قاعدة الاناء… النحت البارز عمل شكل بارز من الطين على قاعدة يقوم الطلبة في هذه الفعالية بعمل شكل بارز فوق قاعدة من الطين على شكل قاعدة رباعية او بشكل مستطيل ، وعلى شكل دائرة وغيرها . تعد القاعدة بالشكل المطلوب .","- يكون الشكل البارز قد صمم ورسم على ورقة بقدر مساحة القاعدة وقد يكون- . ًالشكل نباتاً او حيواناً او عنصراً زخرفيا يكون الطين قد هيأ واعطى للطلبة ، ويفضل توزيع أوراق أو الواح توضع فوق - المقاعد ، حتى لا تتلوث هذه المقاعد ببقايا الطين ، ويوضع الطين عليها او يكون العمل عليها . يبدأ الطالب باضافة الطين على القاعدة على وفق الانموذج المرسوم لهذا الغرض. - يبقى الطالب يزيد الطين ويحذف حتى يكتمل عمل الانموذج ، على وفق النسب- .","المعدة تزاد الزخارف او النقوش التي يتطلبها الانموذج . - . ينعم الشكل بوساطة الماء حتى يكون ملمسه ناعماً ، ويترك حتى يجف- اشغال الخشب معرفة الأدوات اليدوية والمستعملة في أعمال الخشب وطرائق استخدامها والمحافظة - أ عليها . تصميم بعض المشغولات الخشبية التزينية أو النفعية المجسمة أو المسطحة - ب وتنفيذها مثل ) حافظة أوراق ، حمالة الاقلام ، إطارات الصور ، رفوف ، ألعاب الاطفال ... وغيرها ( .","اشغال الخشب لأشغال الخشب أهمية بالغة في حياتنا ، اذ يمكن استخدامه في العديد من الأعمال وتشكيله الى أثاث وأدوات ومستلزمات مفيدة وقيّمة للمنزل أو للمكتب أو للحديقة ، و لجميع اوجه الانشطة الحياتية الحديثة . وبالرغم من أن اشغال النجارة نوع من التعليم المهني ، فأنها تتيح فرصاً عديدة لأرشاد الطلبة في عدد مختلف من ميادينها المهنية والاعمال الفنية المفيدة .","وتعد الأخشاب من أكثر المواد الخام في الاشغال النجارية أهمية بسبب انتشارها في أجزاء شتى من انحاء العالم ، ولما تمتاز به من خواص فنية . وتعددت استعمالات الأخشاب بسبب تعدد منافعها واستعمالاتها في اغراض نفعية وعلمية وفنية . ومن هذه الأهمية وردت في وحدة التشكيل الفني والهندسي فقرات منها اشغال الخشب . نعرضها فيما يأتي .","التعر َّف على الادوات اليدوية المستعملة في أعمال الخشب وطرائق استخدامها - أ والمحافظة عليها يُستخدم في مهنة النجارة العديد من الادوات اليدوية والعدد اللازمة لهذا الغرض.","وسنعرض في الصفحات الآتية بعض أشكال هذه الادوات والمواد والعدد كل - : حسب استخداماتها واستعمالاتها وكما يأتي أدوات القياس ٢ قدم ( مؤشر عليها تقسيمات السنتمتر من - مسطرة من الفولاذ الصلب طولها ) ١ جهة والانج من الجهة الثانية المتر الخطاط ذو الذراع الواحد والمزدوج .","تستعمل لضبط القياسات على الاخشاب وضبط قياسات الالسن الجناح اليد والرأس انواع الفراجيل المستعملة في النجارة فرجال خارجي : ) الكروي ( يستعمل لقياس محيط الخشبة الدائرية . ادوات النشر والقطع منشار شق طولي سراق ظهر - منشار الظهر حجم كبير - المنشار الدوار حجم صغير - منشار دوار منشار مفتاح أدوات الربط الفخة الحديدية: ادوات التثقيب مثقاب فردوندي .: ادوات البرد والتنعيم المبارد بأنواعها الخشنة والناعمة .","ادوات التنعيم أنواع الرندات رندة جانبين : تستعمل لعمل أفريز من خواص هذه الآلة هو أن يربط سلاح الرندة قريباً من مقدمة الجسم لكي تتعلق الآلة من المسح في المحلات الضيقة واخذ الزيادات الواقعة في الزوايا وتنظيم افريز الزجاج وأعمال أخرى .","رندة تنظيم طولها ٩ انجات : تستعمل للتصفية وتنظيم الخشب المناقير وانواعها المنقار هو الاداة المستعملة في نقر الخشب وخاصة النقر العميق ويختلف عن الشفرة الاعتيادية في عرضه وسمكه وفي كيفية الاستعمال وزاوية شطف الحد القاطع ٥٤ درجة وعرض المنقار المعتاد هو ١/٨ انج ثم يزاد حتى يصبح انجا واحدا . من انواع الشفرات : اشغال المعادن تنفيذ بعض الاشغال التعبيرية او التزينية او النفعية من الرقائق المعدنية المختلفة - أ وغيرها .","الضغط والطرق على النحاس عرف النحاس في العراق منذ القدم ، ومر استعماله بمراحل كثيرة ، وعرف الانسان كيف يستخرجه من باطن الأرض وكيف يستخلص المعدن النقي والتخلص من الشوائب العالقة فيه . كما استطاع خلط النحاس مع معادن أخرى مكوناً منها السبائك المعدنية ، مثل البرونز والنحاس الاصفر واستخدم العراقيون القدماء النحاس في الصناعات اليدوية ، وقد دلنا على ذلك ماعثر عليه في المواقع الأثرية من أدوات الصيد والزينة وغيرها .","وصناعة النحاس معروفة لدى العرب ، والبلاد العربية غنية بنتاجاتها الفنية، وقد بانت تلك النتاجات في الصناعات النحاسية ، من تحف وأباريق وصحون وثريات ومباخر ومزهريات وشمعدانات وغيرها . وفي العهد العباسي أزدهرت هذه الصناعة .","وكانت مدينة بغداد من اهم مراكز هذه الصناعة ، وأشتهرت مدينة الموصل آنذاك أيضاً في صناعة المعادن والتكفيت ، ) والتكفيت : هي عملية حفر الاشكال والزخارف بأقلام حفر فولاذية ثم تحشى الاجزاء المحفورة بأسلاك رقيقة أو رقائق عريضة من الفضة او الذهب ( واستعمل النقاشون طرائق متعددة في زخرفة ونقش التحف النحاسية .","ونمارس في دروس الاشغال الفنية بعض اشغال النحاس وضغطه او طرقه او نقشه او انتاج اعمال ذات قيم جمالية من رقائق النحاس مستلهمين من تراثنا الخالد بعض الاعمال واضفاء روح العصر عليها وما ينسجم ورغبات طلبتنا في هذا المجال .","الطرق على صفائح النحاس الرقيقة تمتاز صفائح النحاس الرقيقة بخفة الوزن ، وتعد ُّ من المواد المطاوعة عند الطرق او الضغط اذ يمكن طرقها بسهولة ، وجعلها تتخذ صوراً جديدة كما يمكن عمل نماذج متعددة لملامس السطوح ، واستغلال هذه الصفائح ذات الخصائص الجيدة في عمل تصاميم واعمال فنية مختلفة ، حيث تكسب الطالب الخبرة والمهارة اليدوية ، وتنمي لديه القدرة على الابداع والابتكار ويفضل وضع قطعة المعدن على سطح مستو من مادة الرصاص او القير لنتمكن من إظهار الشكل البارز وفيما يأتي توضيح لبعض الاساليب الخاصة بأعمال النحاس .","الطرق على النحاس - أ - : للحصول على نماذج واعمال مشغولة بوساطة الطرق ، نتبع الخطوات الآتية ترسم الاشكال او الموضوعات التعبيرية على الورق ، سواء اكانت اشكال - . للموضوعات المتنوعة ، او زخارف ، او عبارات من الخط العربي نطبع التصميم المطلوب على صفيحة النحاس بوساطة الكاربون ، أو يمكن رسمها - . من قبل الطلبة نؤشر التصاميم المرسومة بالكاربون بوساطة رأس معدني مدبب ، كي لا تمحى - .","الخطوط نقوم بعملية تحديد الخطوط بوساطة قلم التأشير ) البنطة ( والمطرقة ، وذلك بطرق - القلم بصورة خفيفة على الخطوط الخارجية . وعمل نقاط متتالية على جميع الخطوط المرسومة . نبدأ في عملية الطرق ، بغية أظهار تكوينات الشكل المطلوب ونستمر بهذه العملية - . وصولاً الى الشكل الافضل نقوم بتأطير الشكل او نضعه على قطعة خشب او معدن او قماش ليظهر شكله - .","الجميل ضغط صفائح النحاس- ب نرسم الشكل المطلوب على الوجه الخلفي من اللوح النحاسي . - نضع رقيقة النحاس على مواد لينة مثل ورق الجرائد او الفلين او الاسفنج او الخشب- . المضغوط وغيرها نقوم بعملية الضغط على الاجزاء المراد جعلها بارزة ، مستخدمين أدوات ملساء - . معدنية او خشبية كالملعقة او ادوات خشبية خاصة لهذا الغرض نقلب الصفيحة على الوجه الآخر . ونبين حدود التصميم بأدوات أكثر دقة ، بغية - .","الحصول على ألانموذج الجيد النقش على النحاس - ج نرسم الشكل المراد ابرازه على المعدن بوساطة الكاربون سواء أزخرفياً كان أم - .ًكتابيا نقوم بتحديد الخطوط الخارجية المرسومة على المعدن بآلة معدنية مدببة وحادة رقيقة، - . لكي لا تنمحي الخطوط الخارجية وتضيع معالمها نضع القطعة النحاسية على سندان حديدي مربع وعريض او على قطعة من الخشب - .","السميك نرسم الخطوط الخارجية للشكل بوساطة قلم حديدي من النوع الصلب باستخدام - ،المطرقة اليدوية بدقات خفيفة مركزه ومنتظمة على حافة القلم من الاعلى لتحديد الاشكال المرسومة . نضع قطعة النحاس على اناء مملوء بالجير ) أو على قطعة سميكة من القماش (، - . وذلك لاستجابة القطعة على النقش يستحسن ان تكون الاقلام محفورة بأشكال زخرفية ، حتى تترك اشكالاً زخرفية - .","ويفضل ان تكون الضربات خفيفة ، كي لا يتلف المعدن خامات بيئية واشغال حرّة إن هذه الوحدة اي وحدة التشكيل الفني والهندسي ، قد احتوت على العديد من الفقرات كما مر بنا سابقاً .","وفي هذه الفقرة نود ان نعطي توضيحات وخطوات عمل للعديد من الاشغال التي لا يستغني الطلبة عن تعلمها وممارستها لما لها من أهمية تربوية بالغة ، حيث يتعرف الطالب الخامات المتوافرة في محيطه وكيفية استخدامها في المجالات العملية ، التعبيرية والزخرفية والنفعية ، مثل الاعمال التي تنتج من سعف النخل ، الخوص ، عيدان القصب ، جذور أو جذوع أو قشور الاشجار ، القمح والبذور المختلفة ، الاصواف ، انواع الخرز ، الحجارة والحصى ، أشكال الخيزران .....","الخ . وفيما يأتي بعض الاساليب والطرائق التي نرى أن يتعلمها الطلبة في هذه المرحلة من حياتهم . أشغال القصب الاشغال المصنوعة من القصب تعد من الأشغال البسيطة والمفيدة معاً . يمكن الحصول على القصب من الاسواق بعد تنظيفه تنظيفاً كاملاً من القشور والفضلات تخزن في محل مخصص له .","وهناك طرائق متعددة لتصميم النماذج الفنية من هذه المادة منها : تنظم قاعدة للشكل من أغصان الصفصاف أو الرمان حسب طريقة صنع السلال من الخيزران ، ويمكن صنع ما شابه ذلك من أغصان الرمان والصفصاف وغيرها من الأغصان . أشغال سيقان الحنطة نتمكن بوساطة سيقان الحنطة من صنع الاشغال الآتية : سلال ، قبعات ، اطباق ، حقائب ، اغطية المزهريات ، مناظر ، ورود ، ، وسائل تعليمية ، وخرائط ... الخ .","كيفية الحصول على سيقان الحنطة يمكن الحصول على سيقان الحنطة بكل سهولة وبدون ثمن ، فقبل موسم حصاد الحنطة نطلب من الطلبة ، او اصدقائهم جمع كمية من السيقان من » بيادر« الفلاحين ، بعد فصل السنابل منها باليد نشدها على هيئة » حزمة « ونخزنها في البيوت أو المدارس . تحضيرها قبل البدء بالعمل يجب اجراء العمليات الآتية : انتقاء الافضل بشكله المستقيم وصلابته وبياضه الناصع ...","-: اما اذا ارد نا الحصول على سيقان ملونة ، فنتبع الطريقة الآتية لتلوينها تهيء اصباغ » الجوهر « الموجودة بكثرة لدى العطارين في المدن والقرى: ونضعه في اناء مهيأ لهذا الغرض ، ثم نزيد عليه الماء بكمية مناسبة ونتركه . يغلي فوق النار لمدة كافية نضع سيقان الحنطة في اناء بعد نثرها فيه ، مع وضع ثقل فوقها أو محاولة تغطيها بوساطة قطعة خشبية لبضعة دقائق ، ثم نخرجها من الماء وننشرها .","كيفية العمل اذا أردنا صنع » سلة « من سيقان الحنطة نتبع الطريقة الآتية : نضع السيقان في أناء فيه ماء ليلين لمدة ٠٢ دقيقة تقريباً . ولأجل أن نجرب مطاوعتها للعمل ) علينا أن نأخذ ساقاً واحدة من السيقان، ونمررها بين الاصبعين مع الضغط عليها ، فاذا لم تنكسر او تنقطع تعد ُّ جاهزة العمل.","ناخذ ) ثلاثة او اربعة من سيقان الحنطة حسب حجم المادة كما في شكل ) ١( مرة واحدة وتمسك باليد بصورة أفقية ، ونمسك باليد الاخرى ساقاً واحدة فقط ، ثم نحاول لفها فوق السيقان ) الثلاث ( بلفات متقاربة بمقدار ) انج واحد ( او اكثر كما في الشكل الآتي بانواعه .","نلفها على هيأة رقم )٥ ( بشكل حلقة ثم نربط طرفي الحلقة بوساطة الساق المنفردة وبعد ذلك نلف الساق المنفردة عدة مرات على الهيكل المتكون من ثلاثة سيقان ) ثلاث او اربع لفات ( ، ثم تربط أيضاً كالسابق . وهكذا الى أن تنتهي من الشكل ) ٤ ( .","( ) ١ ) ٢ ( ) ٣ ( ) ٤ ( ، قبل ان تنتهي من الساق المنفردة ، نزيد ساقاً اخرى من سيقان الحنطة ليمكننا ذلك من الاستمرار لعملية اللف ، وهكذا نزيد ساقاً جديد كلما أوشكت الاخرى على الانتهاء كما في الاشكال السابقة اعلاه .","أشغال القش يمكن الحصول على القش المطلوب من المخازن في الاسواق بكل سهولة وبألوان جذابة ، ويمكن ان نستعمل القش لنسج اشياء كثيرة وبطرائق مبسطة وذلك بأتباع - : الطريقة الآتية طريقة العمل يصنع المنسج المطلوب من قطعة من الكارتون وذلك بقصه من طرفيه بوساطة المقص ، ليصبح طرفاه العلوي والسفلي كاسنان المشط كما في الشكل )أ(.","يمرر الخيط بين الاسنان السفلى والعلوية الى ان ينتهي ، ثم يلف القش على: قلم الرصاص ، ويمرر بين خيوط السداة من أسفل الاول ومن اعلى الثاني بشكل متعاكس ، وهكذا إلى ننتهي من العمل ، او ليصنع المنسج من الخشب كاطارات الصور الفنية وتثبت على طرفيها العلوي والسفلي مسامير صغيرة ب ( ، ويمكن الاستفادة من القش في - لغرض ربط الخيوط فيها كما في ) أ صنع اشغال كثيرة منها ، تغليف الصناديق ، او اطارات الصور ، او حاملة اطباق ، وكذلك صنع الزخارف والنقوش واشكال أخرى .","( شكل ) ب ( شكل ) ا صنع الدمى من خامات متنوعة للدمية أهميتها لكونها محببة للأفراد واستخدامها وسيلة تعليمية تحقق غرضاً معيناً . ولقد استخدم في صناعة الدمى العديد من الخامات الأولية التي تنتشر في بيئة - : الطلبة نذكر منها في سبيل المثال لا الحصر قطع الأقمشة أي فضلات الأقمشة مختلفة الألوان والملامس . - . ( خيوط متنوعة ) صوفية ، قطنية ، حبال- . شرائط وأزرار- . ً مقصا- . صمغاً أو أي مادة لاصقة- .","( مصباحاً كهربائياً مستعمل ) لمبة- . أوراق جرائد أو مجلات قديمة- . ( ألوان مختلفة ) ألوان مائية ، أصباغ الجوهر- . أوانياً لوضع الماء أو الألوان فيها- . أشرطة من ورق الالمنيوم- . ورق كارتون سميك- . ( ملاعق خشبية مستعملة ) أي التي تستعمل في المرطبات- . ًَ طينا- . عجائن متنوعة- - : نتعرض لصناعة بعض هذه الدمى كما يأتي عمل الدمى من الخيوط ) الصوفية أو القطنية ( .","يمكن عمل لعب مختلفة من الخيوط ، وذلك باحضار كمية من الخيوط والتمييز بين أنواعها وألوانها أو أستعمالاتها . ويستطيع الطلبة الحصول على هذه الخامة بسهولة فهي متوافرة في أغلب البيوت. ويفضل أن يكون الصوف من النوع السميك ، لأن ذلك يسهل تكوين الدمية . ويتمكن الطلبة من صنع دمى بسيطة بمواد مختلفة مثل خيوط القطن أو ) القنب، والقش ( ويمكن الافادة من الأشكال الآتية ، نماذج يستطيع الطالب أن يصنع منها دمى متنوعة . ."]}],"plates":["10_1.jpg"]},{"id":"11","grade":"الصف الأول المتوسط","unitName":"الوحدة الرابعة","title":"الصف الأول المتوسط - الوحدة الرابعة: التذوق وتاريخ الفن","pages":"73–78","objectives":"تنمية معرفة الطالب بموضوع «الصف الأول المتوسط - الوحدة الرابعة: التذوق وتاريخ الفن» وفهم محاوره وممارساته الفنية كما عرضها دليل المعلم.","specific":["أن يتعرف الطالب إلى محور «معلومات عامة عن الفنون القديمة ومميزاتها وأهم اثارها في العراق والوطن».","أن يتعرف الطالب إلى محور «مايشاهده الطلبة من معروضات أو مخلفات آثارية ، وهذا يعطيهم مايتذوقونه».","أن يتعرف الطالب إلى محور «الخط والزخرفة»."],"tools":"الخامات والأدوات الواردة في الدليل: الخشب، المعادن، القصب.","intro":"تهيئة مقترحة: يعرض المعلم مثالاً من موضوع «الصف الأول المتوسط - الوحدة الرابعة: التذوق وتاريخ الفن»، ثم يطلب من الطلبة وصف ما يلاحظونه وتحديد الفكرة الفنية التي يعالجها الدرس.","summary":["معلومات عامة عن الفنون القديمة ومميزاتها وأهم اثارها في العراق والوطن؛ العربي . زيارة المعارض و المتاحف والأماكن الأثرية وتسجيل الملاحظات وماتتميز فيها: من خصائص فنية . - : أن مجالات التربية الفنية تعتمد…","مايشاهده الطلبة من معروضات أو مخلفات آثارية ، وهذا يعطيهم مايتذوقونه؛ من سمات الفن في تلك اللوحات أو تلك المخلفات ، مما يجعلهم قادرين علىتميز القيم الشكلية والجمالية والابتكارية فيها . - : ممارسةالأعمال…","الخط والزخرفة؛ الطباعة والحفر- أعمال الخشب: أن ما عرضناه انفاً جوانب مهمة في حياة الأفراد لأنها تنمي فيهم معارف حسية وما تنميه من اكتساب مهارات يدوية ، وصولاً الى تكامل شخصياتهم . لذلك أدرك المدرسون فوائدها…"],"mcq":[{"n":1,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 1 في ترتيب الدرس؟","options":["معلومات عامة عن الفنون القديمة ومميزاتها وأهم اثارها في العراق والوطن","مايشاهده الطلبة من معروضات أو مخلفات آثارية ، وهذا يعطيهم مايتذوقونه","الخط والزخرفة"],"answer":"أ"},{"n":2,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 2 في ترتيب الدرس؟","options":["معلومات عامة عن الفنون القديمة ومميزاتها وأهم اثارها في العراق والوطن","الخط والزخرفة","مايشاهده الطلبة من معروضات أو مخلفات آثارية ، وهذا يعطيهم مايتذوقونه"],"answer":"ج"},{"n":3,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 3 في ترتيب الدرس؟","options":["مايشاهده الطلبة من معروضات أو مخلفات آثارية ، وهذا يعطيهم مايتذوقونه","الخط والزخرفة","معلومات عامة عن الفنون القديمة ومميزاتها وأهم اثارها في العراق والوطن"],"answer":"ب"}],"truefalse":[{"n":1,"q":"يتناول الدرس موضوع «معلومات عامة عن الفنون القديمة ومميزاتها وأهم اثارها في العراق والوطن» ضمن محاوره. ( )","answer":"صح"},{"n":2,"q":"المحور الأول في ترتيب الدليل هو «مايشاهده الطلبة من معروضات أو مخلفات آثارية ، وهذا يعطيهم مايتذوقونه». ( )","answer":"خطأ"},{"n":3,"q":"يَرِد موضوع «الخط والزخرفة» ضمن محتوى هذا الدرس. ( )","answer":"صح"}],"answerKey":" الاختيار من متعدد: 1 ـ أ، 2 ـ ج، 3 ـ ب | الصح والخطأ: 1 ـ صح، 2 ـ خطأ، 3 ـ صح","topics":["معلومات عامة عن الفنون القديمة ومميزاتها وأهم اثارها في العراق والوطن","مايشاهده الطلبة من معروضات أو مخلفات آثارية ، وهذا يعطيهم مايتذوقونه","الخط والزخرفة"],"sections":[{"title":"معلومات عامة عن الفنون القديمة ومميزاتها وأهم اثارها في العراق والوطن","paras":["العربي . زيارة المعارض و المتاحف والأماكن الأثرية وتسجيل الملاحظات وماتتميز فيها: من خصائص فنية . - : أن مجالات التربية الفنية تعتمد على محورين أساسيين هما - : الثقافة الفنية ، التي تستند الى المحورين وهما- أ"]},{"title":"مايشاهده الطلبة من معروضات أو مخلفات آثارية ، وهذا يعطيهم مايتذوقونه","paras":["من سمات الفن في تلك اللوحات أو تلك المخلفات ، مما يجعلهم قادرين علىتميز القيم الشكلية والجمالية والابتكارية فيها . - : ممارسةالأعمال الفنية ،والتي تستند الى المحورين وهي- ب ذات البعدين ، التي منها- ممارسة الأعمال الفنية: الرسم والتصوير-"]},{"title":"الخط والزخرفة","paras":["الطباعة والحفر- أعمال الخشب: أن ما عرضناه انفاً جوانب مهمة في حياة الأفراد لأنها تنمي فيهم معارف حسية وما تنميه من اكتساب مهارات يدوية ، وصولاً الى تكامل شخصياتهم . لذلك أدرك المدرسون فوائدها وأدخلوها في البرامج التعليمية حسب المراحل الدراسية . معلومات عامة عن الفنون القديمة ومميزاتها واهم اثارها في العراق والوطن العربي.","تعد الفنون مرآة لحضارات البلدان تعكس فعاليتها الأبداعية ، ويقاس بموجب مستواها مقدار التقدم الفكري للبلد ، والبلاد العربية أوفر حظاً في غناها بالتراث الفني ، تضم جملة من أعرق وأول الحضارات الانسانية .","وكانت علىمرّ العصور في تفاعل حضاري دائم تمنح وتأخذ : تمنح النتاج الابتكاري للفكر الخلاق ، ولكن حين تأخذ ، لا تتناول على مستوى التقليد ، وانما تصهره في بوتقه شخصيتها المميزة وتعيده في وجه جديد ، وقالب جديد ، يفيض بالصفات الأساسية للسمات الروحية الشرقية الأصلية ، فياضاً بالحيوية ، ويصبح مصدراً من مصادر الإقتباس والهواية .","إن منطقة الحضارة العربية تمتد من المحيط الأطلنطي غرباً ، الى الخليج العربي شرقاً وهضاب الأناضول وأرمينيا شمالاً ، واواسط أفريقيا والمحيط الهندي جنوباً ، وسكنت هذه المناطق أمم عريقة في حضارتها التي تبدأ قبل الأسلام بقرون طويلة تمتد الى فجر التاريخ وقد أهتم الباحثون بالمنطقة العربية ودرسوا ظواهرها الطبيعية وتضاريسها ومناخها ، وخلصوا من ذلك الى أن المنطقة العربية تعد من المناطق النادرة التي تمتاز بشخصية أقليمية منفردة متميزة .","وأن البلاد العربية تتمثل فيها الوحدة الفكرية منذ أقدم العصور ، وبودنا أن نوضح أبرز الخصائص الحضارية وبخاصة فيما يتصل بالفن في البلاد العربية . إن حضارة الجزيرة العربية وبخاصة في الجنوب ، حضارة قديمة موغلة في القدم، ويمكن أن يكون هذا الجنوب الخصيب هو مصدر الهجرات المتلاحقة لشمال البلاد العربية في الشام والعراق وسيناء ، ومصر من جنوبها .","هذا فضلا عن الحركة التجارية التي قامت قبل العصور التاريخية التي تمتد فيما يذكر ،الى الألف الرابع قبل الميلاد ، وأقدم الحضارات في جنوب الجزيرة العربية الحضارة المعينية وحضارتها كانت في الجوف بين بخران وحضرموت ، وأهم مدنها معين والحزم والبيضاء والسوداء وكمنا . وما يزال الباحثون يعثرون في بقايا هذه المدن القديمة على آثار المعابد ، وما على جدرانها من نقوش .","والأحجار المكتوبة بالقلم المسند وعلى التماثيل النذرية والحلي والعملة القديمة . وأحدث الحضارات التي قامت قبل الاسلام في جنوب الجزيرة العربية ، الحضارة الحميرية ، وأهم مراكزها ظفار ومأرب وصنعاء ، ونجد بها بقايا المعابد والقصور…"]}],"plates":["11_1.jpg"]},{"id":"12","grade":"الصف الثاني المتوسط","unitName":"الوحدة الأولى","title":"الصف الثاني المتوسط - الوحدة الأولى: التعبير الفني والهندسي","pages":"80–96","objectives":"تنمية معرفة الطالب بموضوع «الصف الثاني المتوسط - الوحدة الأولى: التعبير الفني والهندسي» وفهم محاوره وممارساته الفنية كما عرضها دليل المعلم.","specific":["أن يتعرف الطالب إلى محور «الفن وأهميته في الحياة ، وعلاقته بالدروس الاخرى».","أن يتعرف الطالب إلى محور «رسم الموضوعات المستمدة من البيت والمدرسة والبيئة مع مراعاة نضوج».","أن يتعرف الطالب إلى محور «التعبير عن المناسبات والاعياد والموضوعات الاجتماعية والانسانية»."],"tools":"الخامات والأدوات الواردة في الدليل: الخشب، المعادن.","intro":"تهيئة مقترحة: يعرض المعلم مثالاً من موضوع «الصف الثاني المتوسط - الوحدة الأولى: التعبير الفني والهندسي»، ثم يطلب من الطلبة وصف ما يلاحظونه وتحديد الفكرة الفنية التي يعالجها الدرس.","summary":["الفن وأهميته في الحياة ، وعلاقته بالدروس الاخرى؛ الفن تعبير عن الذات الانسانية وعن الجماعة التي يعيش فيها الفنان ممثلاً لآرائها ومعبراً عن واقعها وما تصبوا اليه في اداء واضح مبتكر يؤثر في الحواس . والفن صفة…","رسم الموضوعات المستمدة من البيت والمدرسة والبيئة مع مراعاة نضوج؛ الطلبة العقلي إن من يعمل في تدريس مادة التربية الفنية ، يجب أن يلم الماماً كافياً في نمو القدرة التعبيرية لدى الطلبة ، اذ أن مراحل النمو هذه…","التعبير عن المناسبات والاعياد والموضوعات الاجتماعية والانسانية؛ تحدثنا في منهاج الصف الاول ووضحنا أهمية تذكر الطلبة بما يدور خلال العام الدراسي من مناسبات ، الهدف منها تفاعل الطلبة معها بما تفرزه من قيم…","إجراء تمرينات لدراسة الظل والنور ودرجاتهما بوساطة قلم الرصاص على؛ النماذج دراسة الظل والنور تتطلب الدقة المتناهية في تتبع النور وأين يقع وكيف يكون الجانب الذي لا يقع عليه نور . نحن نرى الاشياء حين يكون…","منابع اصطناعية : كالمصابيح البترولية والكهرباء والشموع وغيرها والضوء؛ ينتشر من منبعه بوساطة جسيمات صغيرة تنبعث منه وتنتشر على شكل خطوط مستقيمة تسمى ) اشعة ( . الظل: اذا وقع اي جسم في مسير الاشعة في منبع…"],"mcq":[{"n":1,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 1 في ترتيب الدرس؟","options":["الفن وأهميته في الحياة ، وعلاقته بالدروس الاخرى","رسم الموضوعات المستمدة من البيت والمدرسة والبيئة مع مراعاة نضوج","التعبير عن المناسبات والاعياد والموضوعات الاجتماعية والانسانية"],"answer":"أ"},{"n":2,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 2 في ترتيب الدرس؟","options":["الفن وأهميته في الحياة ، وعلاقته بالدروس الاخرى","التعبير عن المناسبات والاعياد والموضوعات الاجتماعية والانسانية","رسم الموضوعات المستمدة من البيت والمدرسة والبيئة مع مراعاة نضوج"],"answer":"ج"},{"n":3,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 3 في ترتيب الدرس؟","options":["رسم الموضوعات المستمدة من البيت والمدرسة والبيئة مع مراعاة نضوج","التعبير عن المناسبات والاعياد والموضوعات الاجتماعية والانسانية","الفن وأهميته في الحياة ، وعلاقته بالدروس الاخرى"],"answer":"ب"}],"truefalse":[{"n":1,"q":"يتناول الدرس موضوع «الفن وأهميته في الحياة ، وعلاقته بالدروس الاخرى» ضمن محاوره. ( )","answer":"صح"},{"n":2,"q":"المحور الأول في ترتيب الدليل هو «رسم الموضوعات المستمدة من البيت والمدرسة والبيئة مع مراعاة نضوج». ( )","answer":"خطأ"},{"n":3,"q":"يَرِد موضوع «دراسة المنظور بشكل أوسع واجراء تطبيقات عملية على الاشياء» ضمن محتوى هذا الدرس. ( )","answer":"صح"}],"answerKey":" الاختيار من متعدد: 1 ـ أ، 2 ـ ج، 3 ـ ب | الصح والخطأ: 1 ـ صح، 2 ـ خطأ، 3 ـ صح","topics":["الفن وأهميته في الحياة ، وعلاقته بالدروس الاخرى","رسم الموضوعات المستمدة من البيت والمدرسة والبيئة مع مراعاة نضوج","التعبير عن المناسبات والاعياد والموضوعات الاجتماعية والانسانية","إجراء تمرينات لدراسة الظل والنور ودرجاتهما بوساطة قلم الرصاص على","منابع اصطناعية : كالمصابيح البترولية والكهرباء والشموع وغيرها والضوء"],"sections":[{"title":"الفن وأهميته في الحياة ، وعلاقته بالدروس الاخرى","paras":["الفن تعبير عن الذات الانسانية وعن الجماعة التي يعيش فيها الفنان ممثلاً لآرائها ومعبراً عن واقعها وما تصبوا اليه في اداء واضح مبتكر يؤثر في الحواس . والفن صفة لازمت الانسان منذ نشأته ورافقته وما زالت تلازمه . وتعني كلمة ) فن ( وهي مفرد لكلمة فنون وهي الانواع وكذلك الاسلوب .كما تعطي معنى التنويع والتعبير . وتحمل كلمة الفن ، معنى تجميل الشيء وتزيينه ويمكن ان تطلق على كل شيء له شكل جميل ...","فالفن مظهر من مظاهر الحياة الحضارية ، ولا سيما حضارتنا فقد حل كل شيء يستعمله الانسان المتحضر من مسكن واثاث بيتيه - المعاصرة وادوات ووسائط وملابس . ابتدعها بتجميل كل شيء يراه وله صلة به . والفن ... اصطلاح يحمل مدلولاً غير محدود ، يشير الى انواع عديدة من مظاهر النشاط الابداعي للانسان كالادب بنوعيه ) الشعر والنثر ( والموسيقى والتمثيل والعمارة ...","الخ وهذا الاتساع دعا الى حصر كل جملة من هذه النشاطات الفنية من مصطلح خاص بها . فهناك ) فنون تشكيلية( كالرسم والتصوير والحفر والنحت والعمارة ... ولا نريد الخوض هنا في تعريف الفن ومجالاته فإنها كثيرة ومتعددة ، كي لا يطول الحديث عنها ، ونكتفي بعلاقة مادة التربية الفنية ، او الرسم بالتحديد بالمواد الدراسية الاخرى .","فالرسم هو احدى الوسائل التي تعبر عن الذات الانسانية في المجتمع وهو احساس زاخر بالعواطف التي تثيرها الطبيعة باسرارها والوانها . فيضفي عليها الرسام مشاعره لتخرج تلك الاحاسيس صورة ناطقة بكامل فكرتها وتخطيطها والوانها منسجمة للتعبير عن الحقائق الكامنة التي تحمل معاني الخير والجمال . وان الرسم يعد اساساً لاعمال فنية كثيرة ان لم يكن اساساً للطرائق التنفيذية الاخرى .","فالرسم هو وسائل ايضاحية منظورة لما يفكر فيه وما يقوم بتخطيطه في ميادين الانشاء التشكيلي كلها . إن اهداف التربية الفنية جزء متمم لاهداف التربية بشكل عام بعدّها وسيلة من الوسائل التي تعتمد عليها المدرسة في تحقيق اهدافها .","فالشخص الذي تنشده التربية هو الذي يجمع بين المعرفة بنوعيها العقلية والعاطفية التي نصل اليها عن طريق الحواس المختلفة ، والتي هي بمثابة وسائل أو أدوات تساعد على بناء وتوطيد الصلة بينه وبين الوسط الذي يعيش فيه . ونحن ندرس مادة الرسم لتحقيق غرضين : الاول كونه مادة مكملة للمواد الدراسية الاخرى . والغرض الثاني كونه ينمي الناحية العاطفية بعدّها من وسائل المعرفة ..","وتدريب الحواس ، وتكامل الشخصية حتى تتوافر للفرد القدرة ليكون جزءاً من المجتمع الذي يعيش ويحيا في كنفه . ويعتقد الكثيرون : إن مادة الرسم مادة كمالية او وسيلة للترفيه ، والحقيقة ان ما يلاقيه الطالب من مهارة…"]},{"title":"رسم الموضوعات المستمدة من البيت والمدرسة والبيئة مع مراعاة نضوج","paras":["الطلبة العقلي إن من يعمل في تدريس مادة التربية الفنية ، يجب أن يلم الماماً كافياً في نمو القدرة التعبيرية لدى الطلبة ، اذ أن مراحل النمو هذه تحمل في ثناياها خصائص ومميزات ، لها دلالاتها وأساليبها في التعبير الفني ، وهذه الدلالات والاساليب ، يظُهرها الطلبة في تعبيراتهم بوصفها أنماطاً تمثل قدراتهم وملكاتهم وما يمتلكون من طاقات أبداعية في تنفيذ موضوعاتهم .","وحين يطلب المدرس من طلبته رسم الموضوعات المستمدة من بيئة الطالب ومحيطه فإن هذا المدرس يدرك مرحلة هذا الطالب . وهذه المرحلة يصفها المربون » مرحلة التعبير الواقعي « . إن طلبة هذه المرحلة ، تظهر لديهم إتجاهات ، يسميها المربون الاتجاه البصري والاتجاه الذاتي . وان ما يتميز به الإتجاه البصري هو اعتماد الطالب على الحقائق البصرية عند التعبير . وعن الاتجاه الذاتي : فإن نمط الطالب يعتمد على نظرته الشخصية وإنفعالاته الخاصة .","لقد عرضنا هذه الخصائص ليتعرف المدرس أساليب الطلبة وما يقدمونه من نتاجات فنية وانماطهم ، فانها ضرورية لتقدير ذلك لديهم . وما يمتلكون من إتجاهات معينة ) فإن لكل طالب طريقته في التعبير واسلوبه الخاص به ( . وتتدرج هذه المميزات الجديدة في الظهور شيئاً فشيئاً في أعمال الطالب الفنية بصورة افضل ، فمعرفة الطالب كيفية رسم الاشكال التوضيحية وعمل الوسائل لإعتماده على الخبرات البصرية والحسية .","وأن ظهور الأثر الواقعي في هذه المرحلة دليل على نمو الطالب وإدراكه الواعي لمظاهر أشكال عناصر الاشياء المحيطة به وألوانها. من هذه الاعتبارات ومن أجل معرفة إتجاهات الطلبة وقدراتهم ، يطُلب رسم الموضوعات المستمدة من واقعه وبيئته ، كل حسب أمكاناته ."]},{"title":"التعبير عن المناسبات والاعياد والموضوعات الاجتماعية والانسانية","paras":["تحدثنا في منهاج الصف الاول ووضحنا أهمية تذكر الطلبة بما يدور خلال العام الدراسي من مناسبات ، الهدف منها تفاعل الطلبة معها بما تفرزه من قيم ومضامين أخلاقية وإنسانية . مثل عيد الأم وعيد المعلم وعيد الطالب وغيرها ..."]},{"title":"إجراء تمرينات لدراسة الظل والنور ودرجاتهما بوساطة قلم الرصاص على","paras":["النماذج دراسة الظل والنور تتطلب الدقة المتناهية في تتبع النور وأين يقع وكيف يكون الجانب الذي لا يقع عليه نور . نحن نرى الاشياء حين يكون هنالك ضوء وعند عدم توافر ضوء لا ترى الاشياء : فهناك الظلام. وترى العين الضوء بسبب الاشعاعات القوية التي تصدر منه أو من الاجسام التي تنعكس عنها الاشعاعات الضوئية .","المنابع الضوئية إن الاجسام التي ينبعث منها الضوء وتضيء اجساما مضيئة تعّد منابع ضوئية وهناك الاجسام التي ينبعث منها الضوء ولا ترى الا اذا وقع عليها فتدعى احيانا"]},{"title":"منابع اصطناعية : كالمصابيح البترولية والكهرباء والشموع وغيرها والضوء","paras":["ينتشر من منبعه بوساطة جسيمات صغيرة تنبعث منه وتنتشر على شكل خطوط مستقيمة تسمى ) اشعة ( . الظل: اذا وقع اي جسم في مسير الاشعة في منبع ضوئي ينشأ عن ذلك ما يعرف ب ) الظل ( والظل يعبر عن شكل الاجسام ويكسبها شيئاً من الحياة فتبدو بارزة . فلو وضعنا تفاحة امام ضوء شمعة . لشاهدنا الآتي : جزءاً منيراً يسقط عليه النور ) الضوء المباشر ( ويسمى ) الضوء الساطع( أو ) النور الساطع ( .","ويظهر خيال التفاحة على السطح الموضوعة عليه ويسمى هذا الخيال: ) الظل الساقط ( وهذا الظل يكون قاتماً بالقرب منها ثم يصير فاتحاً كلما بعد تدريجياً.","النور والظل لا يظهران على الاجسام بدرجة واحدة بل يختلفان تبعاً لشكلها والمادة المصنوعة منها ويمكن تصنيف الاجسام الموجودة في الطبيعة الى ثلاثة اقسام من حيث عتمتها وشفافيتها : أجسام شفافة فالاجسام المعتمة : هي هي التي تمتص النور وتحجبه ولا تدع النور ينفذ من خلالها فهي تمتص معظم النور الذي يقع عليها وتعكس جزءاً يسيراً منه . كالخشب والمعادن والورق السميك وغيرها .","والاجسام نصف الشفافة : هي الاجسام التي لا تظهر من ورائها المرئيات بشكل واضح كالزجاج غير المصقول ومثل هذه الاجسام تنفذ قليلاً من النور الذي يقع عليها بينما تعكس كمية كبيرة منه وتمتص الباقي . الاجسام الشفافة : هي التي تسمح للنور بالمرور من خلالها كالماء الصافي والزجاج العادي وهي تختلف عن غيرها من الاجسام لكونها تمتص جزءا من النور الذي يقع عليها وتعكس جزءا ضئيلا منه .","الضوء المباشر والضوء المنعكس : الضوء المباشر هو الشعاع أو الاشعة الاتية من المنبع الضوئي أو المصدر الضوئي اما الضوء المنعكس : فهو عبارة عن انعكاس النور من جسم مضاء . فنحن نرى ضوءاً منعكساً في منطقة الظل ناشئاً عن انعكاس الجسم الموضوعة عليه الاجسام أو السطوح الاخرى مجاورة للشكل أو السطح . وهذا الضوء المنعكس يختلف باختلاف الاجسام وتبعاً للمادة التي صنعت منها كأن تكون مصقولة لامعة أو معتمة غير شفافة .","ويعدّ هذا الضوء المنعكس في الظل نصف نور او نوراً ضعيفاً ويمكن عدّه بين النور والظلام أي نصف ظل في الرسم .","سلمّ القيم ان القيم في الرسم تعني مقدار الضوء والظل ) أو كمية شدة تدرج الظل والنور من السواد الى البياض وكمية تدرج اللون من القاتم الى الفاتح ( ودراسة قيم الظل القصد منها درجات الظل من حيث الشدة والقوة والخفة وبمعرفة هذا التدرج في سلم القيم نكون قد توصلنا الى معرفة طريقة التظليل بصورة حقيقية فنية وسلم القيم عبارة عن مستطيل مقسم الى ثمانية مستطيلات صغيرة متدرجة من الاسود القاتم الى الابيض الناصع وهذا السلم يساعد الطالب في التدرج في تظليل الاجسام .","التظليل قلنا ان التظليل يكسب الاجسام شيئا من الحياة ويقوم مقام التلوين ، والتظليل معناه التدرج في قيم الظل وملاحظة ما يقع على الجسم من نور وظل حتى يظهر الشكل وقد ارتبطت تفاصيله ببعضها . هنا وجب ملاحظة اتجاه سير الضوء على الجسم وكيف ان هذا الضوء عند سقوطه على الجسم سيضيء احد جوانبه ويظلم الجانب الاخر . وكيف سيرمي الجسم نفسه ظلا على الارض .","وكيف إن الضوء اذا سقط على جسم ما اضاء الجزء المقابل له ثم يضعف ويتدرج هذا الضوء حتى يتلاشى نهائياً من الجانب الاخر . اما الظل الذي يلقيه الجسم فأنه يبدو قوياً وقاتماً ثم يتلاشى بدوره تدريجياً حتى ينتهي فجأة . ويجب ان نلاحظ في التظليل مناطق الظل والنور وهي ثلاث مناطق منطقة شديدة الضوء : هي المقابلة للنور مباشرة .","- منطقة متوسطة الظل : هي الواقعة بين… الخروج الى الطبيعة والرسم من الواقع لا شك ان للفن جذوراً اصيلة في الطبيعة، والجمال كائن فيها يراه الفنان ويحسه، فعمله الفني ينحصر في تمييز هذه العناصر والتوليف بينها والفنان إنسان يستجيب للعواطف وقادر على تسجيلها.","إن رسم المناظر الطبيعية ، يتطلب دراسة الطبيعة والاندماج معها وحصر الموضوع المراد رسمه في الذهن وتحديد ابعاده وتخطيطه بمرونه وتفكير سليم ليظهر )جمال التكوين( وهذا يستند الى أمور ثلاثة هي الوحدة ،الاتزان ، وتوزيع الضوء. أما الوحدة فيجب ان تعالج في الموضوع بحيث تكون كمجموعة أوكتلة واحدة ذات نقطة نظر مهمة . والاتزان هو ان نجعل الموضوع متناسباً في اطرافه كلها .وأما توزيع الضوء بحيث يشكل أتزاناً تاماً في الموضوع .","أن وقوف الطلبة امام المناظر الطبيعية يكسبهم الكثير من سحر الطبيعة ومفاتنها الخلابة، لذلك جاءت هذه الفقره لإنسجام الطلبة بما يتمتعون به من هذا الجمال الساحر. وكلما درسوا الطبيعة عن كثب ، فإن رسومهم تأتي معبرة وصادقة عما يشاهدونه فيها من مفاتن ، وبالتالي يتحقق الهدف التربوي ومن ثم يتحقق الغرض الفني في الوصول الى رسم اشياء أو اشكال من الطبيعة.","ملاحظة : يرجى الرجوع الى موضوع الظل والنور وتوضيحهُ للطلبة عند الرسم من الطبيعة ، ليكون الموضوع المرسوم أكثر جمالية. التعبير عن الموضوعات المستمدة من الدروس الاخرى كالرياضيات والعلوم والتاريخ والجغرافية ... الخ . إن مدرس التربية الفنية يستطيع معاونة كثير من مدرسي المواد الدراسية الاخرى، ويقوي الرابطة التربوية بينه وبينهم ، وكلما كان التفاعل مستمراً أعطت هذه الفعاليات التعاونية الخبرات ذات الطابع العلمي والاجتماعي .","إن تدريس التربية الفنية منعزلة عن باقي المواد الدراسية امر غير طبيعي بالنسبة للطالب وبالنسبة للمادة نفسها . فالحياة الواقعية لا تعرف هذا الفصل ، وخير وسيلة للتربية ما كانت تلائم طبيعة الطالب وتساير الحياة الواقعية التي يحياها .. ففي الحياة الواقعية نلمس أن فروع المعرفة المختلفة تنمو وتترعرع جنباً الى جنب كما ذكرنا سابقاً .","إن مناهج المواد الدراسية المختلفة ومقرراتها الدراسية ) اي كتبها ( تتضمن العديد من الموضوعات التوضيحية أو التخطيطية او الرسوم المعبرة .","زميلنا المدرس عند الرجوع الى هذه الكتب وغيرها فإنك ستجد الكثير من الرسومات والتخطيطات التوضيحية فيها : فعندما تطلب من الطلبة رسمها او تكبيرها او عمل وسائل ايضاح منها او وسائل تعليمية ، فإنك حقاً تحقق غرض التربية الفنية بعدّها مادة مكملة للمواد الدراسية الأخرى ، ولها العلاقة الصميمية لما ورد فيها . فهذا الربط هو المطلوب تربوياً في أهداف مادة التربية الفنية وما نتوخاه منها .","دراسة المنظور بشكل أوسع واجراء تطبيقات عملية على الاشياء الموجودة داخل الصف وخارجه نضيف الى ما ورد في الصف الأول في دراسة المنظور أنواع نقاط التلاشي.","- أ وهي تلك النقاط التي تلتقي فيها الخطوط المتلاشية وتكون على ثلاثة انواع حسب موقعها في اللوحة ، فهناك نقاط تلاشي تقع على خط الآفق ومستوى النظر وتسمى نقاط التلاشي الافقية نسبة الى الافق وهناك نقاط تلاشٍ فضائية ، وهي التي تقع فوق مستوى النظر اي في الفضاء ، ونقاط تلاشٍ ارضية اي تحت مستوى النظر وكأنها في باطن الارض ) لاحظ الشكل في أدناه ( فالنقاط )أ ، ن ، ج ( تقع على الافق الذي هو ) قطر الدائرة ( فهي نقاط تلاشٍ أفقية والنقطتان ) د ، و( فوق مستوى النظر اي في الفضاء فهي نقاط تلاشٍ فضائية ، والنقطتان )س ، ط ( تقعان تحت مستوى النظر اي في باطن الارض فهي نقاط تلاشٍ ارضية .","نقطة النظر الرئيسة هي أحدى نقاط التلاشي المهمة التي تقع على الافق وتكون امام المشاهد مباشرة، اي هي نهاية الشعاع المركزي ، فهي مركز الدائرة ، هذه النقطة مهمة جداً في دراسة المنظور ، لانها تنتقل مع المشاهد ، ويتغير موقعها تبعاً له ، فهي نقطة تلاشي للخطوط المتلاشية القائمة اي الخطوط التي تكون زاوية ٠٩ درجة مع سطح اللوحة ، .. ويرمز لها بحرف ن . ) لاحظ الشكل ( . . ط ا ن ج . د . و . س . . .","نقطتا المسافة هما نقطتا تلاشٍ تقعان على الافق أيضاً ، وعلى مسافة متساوية في البعد عن نقطة النظر الرئيسة ، وتسميان نقاط المسافة لانهما تمثلان المسافة الحقيقة التي تفصل المشاهد عن قاعدة اللوحة ، وفي الواقع هي المسافة نفسها التي تفصل المشاهد عن الاشكال التي يراد رسمها .","ويرمز لها بحرفي ) ق ، قَ ( نقطتا التلاشي العرضية هما نقطتا تلاشٍ أفقية وتقعان على مسافة غير متساوية ومتغيرة بالنسبة لنقطة النظر الرئيسة ، نتيجة وتبعاً لدرجة ميلان الخطوط المتلاشية ، والتي تكون درجة ميلانها اقل أو اكثر من ٥٤ ̊ درجة بالنسبة لسطح اللوحة .","الوضعيات المختلفة للمربع المتلاشي للمربع المتلاشي الافقي الذي يكون متعامدا مع سطح اللوحة ثلاث وضعيات - : أساسية بالنسبة لموقعه من المشاهد وهي الحالة الاولى : عندما يكون المربع مشاهداً من الامام أي تكون قاعدته موازيه لسطح اللوحة » أي موازية للافق « ومركز المربع أمام نقطة النظر الرئيسة ، أما الضلعان الآخران فيكونان متلاشيين لاحظ الشكل : .","ق ن ق َ الحالة الثانية : عندما يكون المربع مائلا بالنسبة للمشاهد أي تكون أضلاعه الاربعة وقطراه غير موازية لسطح اللوحة . أي غير موازية للافق فتكون الاضلاع متلاشية بزاوية أقل أو أكثر من ٥٤ درجة أي تتلاشى في نقاط تلاشٍ عرضية ولأجل وضع هذا المربع في حالة المنظور يجب الاستعانة بمسقطه…"]}],"plates":["12_1.jpg","12_2.jpg"]},{"id":"13","grade":"الصف الثاني المتوسط","unitName":"الوحدة الثانية","title":"الصف الثاني المتوسط - الوحدة الثانية: التصميم والزخرفة","pages":"97–106","objectives":"تنمية معرفة الطالب بموضوع «الصف الثاني المتوسط - الوحدة الثانية: التصميم والزخرفة» وفهم محاوره وممارساته الفنية كما عرضها دليل المعلم.","specific":["أن يتعرف الطالب إلى محور «تمرينات لتكوين أشكال هندسية منتظمة أساسها المربع والمثلث والدائرة.».","أن يتعرف الطالب إلى محور «الخط العربي المناسب».","أن يتعرف الطالب إلى محور «التدريب على استخدام الأدوات الهندسية وتطبيق ذلك على تصميم»."],"tools":"الخامات والأدوات الواردة في الدليل: المسطرة.","intro":"تهيئة مقترحة: يعرض المعلم مثالاً من موضوع «الصف الثاني المتوسط - الوحدة الثانية: التصميم والزخرفة»، ثم يطلب من الطلبة وصف ما يلاحظونه وتحديد الفكرة الفنية التي يعالجها الدرس.","summary":["تمرينات لتكوين أشكال هندسية منتظمة أساسها المربع والمثلث والدائرة.؛ سنعرض بعض التمرينات العملية لأشكال هندسية منتظمة ، نريد من طلبتنا الأعزاء دراستها ومحاولة رسمها ليتسنى لهم ادراكها ومعرفة تنفيذ أساليبها .…","الخط العربي المناسب؛ إن من العناصر المهمة في تصميم البطاقات أو أغلفة الكتب أو الاعلانات الإعلامية وغيرها ، وجود الحرف العربي بأنواعه كافة بعدّه عنصراً من عناصر التشكيل . وليس من شك في أن الحروف العربية فيها…","التدريب على استخدام الأدوات الهندسية وتطبيق ذلك على تصميم؛ الأشكال الزخرفية البسيطة يحقق استخدام الأدوات الهندسية كالفرجال والمسطرة والمنقلة الحصول على أشكال هندسية كالدائرة والمربع ، والاشكال الاخرى في…"],"mcq":[{"n":1,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 1 في ترتيب الدرس؟","options":["تمرينات لتكوين أشكال هندسية منتظمة أساسها المربع والمثلث والدائرة.","الخط العربي المناسب","التدريب على استخدام الأدوات الهندسية وتطبيق ذلك على تصميم"],"answer":"أ"},{"n":2,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 2 في ترتيب الدرس؟","options":["تمرينات لتكوين أشكال هندسية منتظمة أساسها المربع والمثلث والدائرة.","التدريب على استخدام الأدوات الهندسية وتطبيق ذلك على تصميم","الخط العربي المناسب"],"answer":"ج"},{"n":3,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 3 في ترتيب الدرس؟","options":["الخط العربي المناسب","التدريب على استخدام الأدوات الهندسية وتطبيق ذلك على تصميم","تمرينات لتكوين أشكال هندسية منتظمة أساسها المربع والمثلث والدائرة."],"answer":"ب"}],"truefalse":[{"n":1,"q":"يتناول الدرس موضوع «تمرينات لتكوين أشكال هندسية منتظمة أساسها المربع والمثلث والدائرة.» ضمن محاوره. ( )","answer":"صح"},{"n":2,"q":"المحور الأول في ترتيب الدليل هو «الخط العربي المناسب». ( )","answer":"خطأ"},{"n":3,"q":"يَرِد موضوع «التدريب على استخدام الأدوات الهندسية وتطبيق ذلك على تصميم» ضمن محتوى هذا الدرس. ( )","answer":"صح"}],"answerKey":" الاختيار من متعدد: 1 ـ أ، 2 ـ ج، 3 ـ ب | الصح والخطأ: 1 ـ صح، 2 ـ خطأ، 3 ـ صح","topics":["تمرينات لتكوين أشكال هندسية منتظمة أساسها المربع والمثلث والدائرة","الخط العربي المناسب","التدريب على استخدام الأدوات الهندسية وتطبيق ذلك على تصميم"],"sections":[{"title":"تمرينات لتكوين أشكال هندسية منتظمة أساسها المربع والمثلث والدائرة","paras":["سنعرض بعض التمرينات العملية لأشكال هندسية منتظمة ، نريد من طلبتنا الأعزاء دراستها ومحاولة رسمها ليتسنى لهم ادراكها ومعرفة تنفيذ أساليبها .","أعطاء تصاميم مبنية على مبدأ التكرار والتماثل والتناظر والتوزيع: النجمي تستند تنفيذ التصاميم الزخرفية الى قواعد ونظم يعرفها العاملون بها والقواعد الزخرفية : هي الطريق الذي بوساطته يمكن وضع رسومات وتصميمات وموضوعات زخرفية طبيعية وهندسية مأخوذة او مقتبسة من الطبيعة على اسس سليمة من الناحية الفنية والعلمية وهذه القوانين المستنتجة من الطبيعة لاحصر لها ومن أهم هذه القواعد الرئيسة : التكرار والتماثل والتناظر والتوزيع النجمي .","والتمرينات الواردة فيما يأتي تعطينا صورة واضحة عن هذه القواعد والنظم ."]},{"title":"الخط العربي المناسب","paras":["إن من العناصر المهمة في تصميم البطاقات أو أغلفة الكتب أو الاعلانات الإعلامية وغيرها ، وجود الحرف العربي بأنواعه كافة بعدّه عنصراً من عناصر التشكيل . وليس من شك في أن الحروف العربية فيها من المرونة والمطاوعة قد لا نجدها في غيرها من الحروف الأخرى .","وأن هذه الخصائص في هذه الحروف جعلت منها عنصراً مهماً في التشكيل ، ولهذا السبب استخدمها معظم الفنانين في لوحاتهم المخطوطة او المصورة ، بوصفها عناصر رئيسة ، أو مهمة في التكوين والتشكيل الفني . وبالفعل ظهرت هذه الخطوط بارزة بشكل واسع في كثير من اللوحات الاعلامية ، ويكاد يكون الحرف أبرز سمة من سمات اللوحة الخطية ، وقد انتشرت هذه الأساليب في ميادين عدة .","ويعتمد تنفيذ الكتابات المختلفة في هذه المجالات على تعلم أصول الخط العربي وقواعده ، وهذه القواعد ان أتقنها الطالب ولو بشكل بسيط فإنه يستطيع كتابة النشرة المدرسية أو بطاقات المناسبات أو مناهج المهرجانات والحفلات وغيرها ونذكر بعض الخطوط العربية وهي كثيرة منها خط الثلث وخط النسخ ، وخط الرقعة ، والخط الديواني ، والخط الكوفي وغيرها ويمكن للطلبة التدريب على كتابتها من خلال الكراسات المطبوعة بأنواع الخطوط المختلفة .","ولقد عدت الحروف العربية ضرباً من ضروب الفنون التشكيلية ، ولذا نجدها قد استخدمت علامة أو وحدة أو عنصراً من عناصر تكوين الإعلان أو الملصق أو الوسيلة أو الغلاف الذي يراد التوضيح عن مضامينه .","ومن هذه الأهمية نرى الراغب في الاعلان أو صاحب البطاقة أو مؤلف الكتاب يبحث عن المصمم الجيد والخطاط البارع ، ليزيد الى النتاج القيم الجمالية ، واظهار المنتج بوصفها وسيلة تعريفية أو وسيلة من وسائل الترغيب والتشويق عن المضمون الذي عد من أجله . ومن هنا وجدنا الكتابة الجيدة والخط الجميل المتقن يعد وسيلة للأعلان وعلامة مضيئة في التعريف . وإن استخدامات الحروف العربية كثيرة ودخلت مجالات عدة منها مجال الطباعة ، وطباعة الاقمشة .","- . في مجال الحاسب الالي » الكومبيوتر « والآلات التعليمية- . في مجال الاعلانات علىاختلافها التجارية والثقافية والتعليمية وغيرها- في مجال العلامات المرورية . وغيرها-"]},{"title":"التدريب على استخدام الأدوات الهندسية وتطبيق ذلك على تصميم","paras":["الأشكال الزخرفية البسيطة يحقق استخدام الأدوات الهندسية كالفرجال والمسطرة والمنقلة الحصول على أشكال هندسية كالدائرة والمربع ، والاشكال الاخرى في داخلها من مثلثات وخطوط متنوعة . والاشكال التالية ترينا ذلك :"]}],"plates":["13_1.jpg"]},{"id":"14","grade":"الصف الثاني المتوسط","unitName":"الوحدة الثالثة","title":"الصف الثاني المتوسط - الوحدة الثالثة: التشكيل المجسم","pages":"107–138","objectives":"تنمية معرفة الطالب بموضوع «الصف الثاني المتوسط - الوحدة الثالثة: التشكيل المجسم» وفهم محاوره وممارساته الفنية كما عرضها دليل المعلم.","specific":["أن يتعرف الطالب إلى محور «اعطاء فكرة عن عمل القوالب للمنحوتات من الجبس وتطبيق ذلك على الأشكال».","أن يتعرف الطالب إلى محور «صب القوالب الجبسية».","أن يتعرف الطالب إلى محور «٣ سنتمترات وبشكل متساوٍ على جميع اجزاء التمثال الطيني وبعد أن»."],"tools":"الخامات والأدوات الواردة في الدليل: الحبر الصيني، الأصباغ، الألوان، الطين، الجبس، الخشب، المعادن، القصب، الورق المقوى، الجلود.","intro":"تهيئة مقترحة: يعرض المعلم مثالاً من موضوع «الصف الثاني المتوسط - الوحدة الثالثة: التشكيل المجسم»، ثم يطلب من الطلبة وصف ما يلاحظونه وتحديد الفكرة الفنية التي يعالجها الدرس.","summary":["اعطاء فكرة عن عمل القوالب للمنحوتات من الجبس وتطبيق ذلك على الأشكال؛ البسيطة . دراسة طرائق عمل الأواني الفخارية مع اجراء تطبيقات عملية لعمل بعض: الاشكال وكيفية تجفيفها ، وحرقها ) ان امكن ( . تحدثنا عن فقرة…","صب القوالب الجبسية؛ بعد أن يكتمل نحت التمثال الطيني ، وخاصة عندما نريد الاحتفاظ بالانموذج المطلوب بشكل دائم . كأن يوضع في مكان مخصص قد يرمز لموضوع أو حدث معين . ويصب اما بالجبس او الاسمنت او البرونز وذلك…","٣ سنتمترات وبشكل متساوٍ على جميع اجزاء التمثال الطيني وبعد أن؛ يتصلب الجبس على التمثال الطيني ، يمكن فتح قطعتي القالب بعد الجبس من الاماكن التي توجد فيها الصفائح المعدنية ويصبح ذلك القالب قطعتين . نغمس…","المخصص نقوم بالخطوات الآتية؛ نربط قطعتي القالب الجبسي بعد ان نرجعها ثانية الى موضعهما بالحبال او الاسلاك - . ًحتى نؤمن عدم انفتاحه ، وتشد شداً محكما نحدث فتحة مناسبة في اعلى القالب الجبسي . كي نصب منه…","ثانياً : اشغال القصب؛ تختلف هذه الطريقة عما سبق في الصف الأول من حيث طريقة التحضير وتهيئة القصب وكذلك طريقة عمل النماذج . إذ تمر عملية تهيئة النماذج بعدة مراحل تعتمد جميعها على مهارات عدة فبعد قطع القصب…"],"mcq":[{"n":1,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 1 في ترتيب الدرس؟","options":["اعطاء فكرة عن عمل القوالب للمنحوتات من الجبس وتطبيق ذلك على الأشكال","صب القوالب الجبسية","٣ سنتمترات وبشكل متساوٍ على جميع اجزاء التمثال الطيني وبعد أن"],"answer":"أ"},{"n":2,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 2 في ترتيب الدرس؟","options":["اعطاء فكرة عن عمل القوالب للمنحوتات من الجبس وتطبيق ذلك على الأشكال","٣ سنتمترات وبشكل متساوٍ على جميع اجزاء التمثال الطيني وبعد أن","صب القوالب الجبسية"],"answer":"ج"},{"n":3,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 3 في ترتيب الدرس؟","options":["صب القوالب الجبسية","٣ سنتمترات وبشكل متساوٍ على جميع اجزاء التمثال الطيني وبعد أن","اعطاء فكرة عن عمل القوالب للمنحوتات من الجبس وتطبيق ذلك على الأشكال"],"answer":"ب"}],"truefalse":[{"n":1,"q":"يتناول الدرس موضوع «اعطاء فكرة عن عمل القوالب للمنحوتات من الجبس وتطبيق ذلك على الأشكال» ضمن محاوره. ( )","answer":"صح"},{"n":2,"q":"المحور الأول في ترتيب الدليل هو «صب القوالب الجبسية». ( )","answer":"خطأ"},{"n":3,"q":"يَرِد موضوع «وهناك طريقة حياكة السجادة أو الشرشف وغيرها بطريقة الأبرة والقماش المخرم،» ضمن محتوى هذا الدرس. ( )","answer":"صح"}],"answerKey":" الاختيار من متعدد: 1 ـ أ، 2 ـ ج، 3 ـ ب | الصح والخطأ: 1 ـ صح، 2 ـ خطأ، 3 ـ صح","topics":["اعطاء فكرة عن عمل القوالب للمنحوتات من الجبس وتطبيق ذلك على الأشكال","صب القوالب الجبسية","٣ سنتمترات وبشكل متساوٍ على جميع اجزاء التمثال الطيني وبعد أن","المخصص نقوم بالخطوات الآتية","ثانياً : اشغال القصب"],"sections":[{"title":"اعطاء فكرة عن عمل القوالب للمنحوتات من الجبس وتطبيق ذلك على الأشكال","paras":["البسيطة . دراسة طرائق عمل الأواني الفخارية مع اجراء تطبيقات عملية لعمل بعض: الاشكال وكيفية تجفيفها ، وحرقها ) ان امكن ( . تحدثنا عن فقرة النحت والفخار في الصف الأول ) يرجى الرجوع اليها رجاءً(: وبودنا أن نعطي في هذا الصف بعض الأساليب التي تدخل في عملية النحت وصنع الاعمال الفخارية وبطرائقها المتعددة .","وتحدثنا عن الطين وعن بعض طرائق تحضيره واعداده للعمل الفني سواء اكان فيما يخص النحت او الفخار لأن الطين قاسم مشترك بينهما ويدخل احياناً الطين الاصطناعي بصورة متممة لهذه الأعمال والصغيرة منها على الأخص والذي يمكن الحصول عليه من الاسواق .","فالنحت على الطين الطبيعي : وبعد أخذه من أماكن حفظه في الصناديق المعدة لهذا الغرض وبعد ترطيب الطين ، يتطلب استخدام أدوات خاصة في عملية النحت، بعضها من الخشب ترتبط في رؤوسها اسلاك معدنية للافادة منها في ازالة الطين الزائد عند النحت . ونحتاج كذلك الى مسند من الخشب توضع عليه قطعة حديدية عمودية الشكل يبنى عليه التمثال الطيني في حالة نحت جسم مدور .","وفي حالة نحت الاعمال البارزة نحتاج الى لوحة خشبية يوضع عليها الطين بعد ترطيبه بالماء . : أما فيما يتعلق بالطين الاصطناعي نحتاج الى الات متشابهة للالات المستخدمة في حالة النحت على الطين الطبيعي، كما نحتاج الى تهيئة اسلاك معدنية ، نأخذ الشكل المراد نحته نفسه وتدق بالمسامير على لوحة خشبية . والطين الاصطناعي يحفظ داخل أكياس من » النايلون « ويضاف اليه قطرات من مادة » الكليسرين « في حالة تصلبه ."]},{"title":"صب القوالب الجبسية","paras":["بعد أن يكتمل نحت التمثال الطيني ، وخاصة عندما نريد الاحتفاظ بالانموذج المطلوب بشكل دائم . كأن يوضع في مكان مخصص قد يرمز لموضوع أو حدث معين . ويصب اما بالجبس او الاسمنت او البرونز وذلك يتطلب عمل قالب من الجبس ، - : اما طريقة صب القالب فتتطلب الآتي نهيىء وعاء اي كان نوعه - ً نحضر ماء- ً نحضر جبسا- نضع الماء في الوعاء او الاناء ونضع عليه الجبس ، ونمزجه جيداً حتى يصبح الخليط- .","رائباً معتدل الكثافة نبدأ بأخذ الجبس الرائب ونرشه فوق التمثال الطيني الى أن يصبح سمكه حوالي -"]},{"title":"٣ سنتمترات وبشكل متساوٍ على جميع اجزاء التمثال الطيني وبعد أن","paras":["يتصلب الجبس على التمثال الطيني ، يمكن فتح قطعتي القالب بعد الجبس من الاماكن التي توجد فيها الصفائح المعدنية ويصبح ذلك القالب قطعتين . نغمس قطعتي القالب بالماء لتنظيفها - ندهن القالب الجبسي بدهن عازل من الداخل .وعندما نريد صبه ووضعه في المكان-"]},{"title":"المخصص نقوم بالخطوات الآتية","paras":["نربط قطعتي القالب الجبسي بعد ان نرجعها ثانية الى موضعهما بالحبال او الاسلاك - . ًحتى نؤمن عدم انفتاحه ، وتشد شداً محكما نحدث فتحة مناسبة في اعلى القالب الجبسي . كي نصب منه السائل المراد صبه - . في بطن هذا القالب نهيىء الجبس مثلاً في حالة رائبة ونسكبه داخل القالب ومن الفتحة التي اشرنا - اليها اعلاه . كي نحصل على تمثال من الجبس مشابه للتمثال الذي صنعناه من الطين .","وأخيراً نفصل القالب الجبسي من خلال تكسيره بشفرة حديدية على أن نقوم - باصلاح ما قد ينكسر من التمثال باضافة شيء من الجبس في الاماكن التي قد تتضرر. نقوم بتنظيف التمثال من الزوائد كي يصبح نظيفاً .- عمل انموذج برتقالة بطريقة الصب لانتاج أنموذج فاكهة او لعبة او أي شكل مثل )البرتقالة( فنتبع الخطوات الآتية : ١ يملأ إناء مسطحاً بالرمل ، ثم ندس فيه البرتقالة على أن يكون نصفها غائراً والنصف الآخر ظاهراً .","٢ نسكب الجبس على النصف الظاهر من البرتقالة حتى يصبح بسمك أنج تقريباً . ٣ نرفع البرتقالة مع القالب الجبسي الملتصق بها في الرمل بعد التكلس ثم نفصلهما عن بعضهما ونغسل القالب ونقوم بتنظيف حواف القالب الملاصقة للرمل بوساطة سكين على أن ننزل بها حفرتين صغيرتين ثم نغسلهما . ٤ ندهن الحافة ونضع البرتقالة في هذا النصف الجاهز وبصورة متقنة كما كانت ملتصقة في الخطوة الثالثة .","٥ نسكب الجبس على النصف الظاهر من البرتقالة بسمك انج ايضاً وبعد تكلسه نفتح القالب المكون من قطعتين وذلك بدق خشبة صغيرة بينهما ثم نطرح البرتقالة جانباً . ٦ نعمل بوساطة السكين فتحة في كلا النصفين عند الاثر الذي تركته الخشبة ثم نغسل القالب ونتركه عدة ساعات في الهواء ليجف ثم نطلي سطحه الملامس للبرتقالة بطبقة خفيفة من سائل الدملوك ونرطبه وندهنه .","٧ نربط قطعتي القالب بالخيوط ونسكب الجبس في داخلها من الفتحة حتى يمتلىء القالب تماماً ونتركه عدة دقائق الى أن يتكلس ثم نفتحه ونخرج البرتقالة الجبسية ونجري عليها التصليح اللازم ، فيتم لنا صنع انموذج الفاكهة المطلوبة وبامكاننا اخراج اي عدد من النسخ باستعمال القالب نفسه .","-: يرجى ملاحظة خطوات العمل كما مؤشرة في التخطيطات الآتية ٣ دراسة طرائق عمل الاواني الفخارية مع اجراء تطبيقات عملية لعمل بعض الاشكال البسيطة وكيفية تجفيفها وحرقها )إن امكن( إن احب الاشياء عند الطلبة هو دروس الاعمال اليدوية بالنسبة للفنون العملية وان الطين هو اقرب واكثر توافراً في المناطق جميعها .","ورخيص الثمن ويمكن الافادة من الطين في صنع الاواني البسيطة اليدوية او عن طريق الدولاب )الويل( والدولاب يمكن صنعه محلياً او شراؤه جاهزاً من المحلات وهذا النوع…"]},{"title":"ثانياً : اشغال القصب","paras":["تختلف هذه الطريقة عما سبق في الصف الأول من حيث طريقة التحضير وتهيئة القصب وكذلك طريقة عمل النماذج . إذ تمر عملية تهيئة النماذج بعدة مراحل تعتمد جميعها على مهارات عدة فبعد قطع القصب باختيار النوع النامي منه بقدر كاف لكي تكون القصبة مقاومة لمدة اطول من الزمن . - : ومن هذه المهارات الدقيقة هي مهارة الربط والتثبيت بشكل جيد لتكوين أنموذج منظم . وتشكل هذه المهارات جميعها اجزاء من مهارة تنفيذ الانموذج بشكله النهائي .","الهدف الخاص : تعرف كيفية تهيئة القصب والمواد اللازمة لعمل النماذج من خلال تحضير مستلزماته .","الاهداف السلوكية : بعد دراسة هذه الوحدة يكون الطالب قادراً على ان : تهيئة القصب تتم تهيئة القصب وتحضيره لعمل النماذج عن طريق تنظيفه اولا من القشور التي تغطي السيقان ثم قطعة بوساطة المنشار الحديدي اليدوي او منشار التخريم بدقة ويفضل ان تقطع القصبة من مكان العقدة لكي يقاوم لمدة اطول من الزمن ، بعد تثقيب القصبة من الطرفين حسب الانموذج او النماذج التي سيأتي شرحها في الوحدات التالية ويكون التثقيب بشكل عمودي بحيث يكون الثقب مقابل الثقب الاخر من الجهة الاخرى لان شكل القصبة اسطواني كما هو موضح في الشكل.","( ) استخدم ابرة كبيرة بعد احمائها بالحرارة كي لا تكسر القصبة عند التثقيب القياسات ليس هناك ثمة قياسات يمكن عدها معياراً نحدد به اجزاء القطع المستخدمة واطوالها، اذ تخضع هذه العملية الى الابعاد والقياسات التي يحددها الانموذج المستخدم او ان لكل نوع من انواع النماذج قياسات معينة تختلف عن باقي الانواع الاخرى من النماذج . ومن وحدات القياس التي نستطيع ان نقيس بها عيدان القصب والاكثر ملائمة من غيرها هي المسطرة الاعتيادية .","فيمكن قياس احدى القطع وقياس باقي القطع على طول القطعة الاولى . الاضافات الجمالية بامكانك استخدام بعض المواد الاضافية لاضافة جمالية على عمل النماذج : ومنها اضافة الخرز بين قصبة واخرى بدلاً من قطع القصب الصغيرة ، وستلاحظ ذلك في الوحدات التالية . أو اضافة النقش بوساطة الكاوية على سيقان القصب .","أ ب ج القطع الصغيرة القطع الكبيرة مناطق الثقوب للقصبة عمل ثلاثة أشكال لمظلات المصباح المنضدي تمر مراحل هذه الاشكال الثلاثة بالمراحل السابقة نفسها في القطع والتثقيب فقد اكتسب الطالب مهارة دقيقة في تثقيب قطع القصب بشكل جيد واصبح يجيد القطع جيداً فتسهل عليه مهمة عمل هذه النماذج . الهدف الخاص عمل ثلاثة نماذج من مظلات المصباح المنضدي .","- : الاهداف السلوكية بعد الانتهاء من هذه الوحدة يستطيع الطالب ان يُنشأ نماذج اخرى من ابتكاره . ملاحظة : يقوم المدرس بالعمل أمام الطلبة ثم يطلب منهم العمل معه خطوة بخطوة الأنموذج الاول خطوات العمل بعد ان أتقن التثقيب في المرحلة السابقة خذ مجموعة من القصب غير محدد: العدد فكلما زاد العدد كبر حجم المظلة وزاد قطرها .","اربط القطع من جهة بوساطة خيط النايلون بشكل حلقة دائرية مع مراعاة قطر الدائرة المطلوب في اعلى المظلة ثم اربط نهاية الخيط بشكل جيد . اما الجهة الثانية خذ مجموعة اخرى من القصب بعد تثقيبها من الوسط فقط: اربطها مع القطع الاولى بين كل قطعة واخرى .","بامكانك ان تربط الخرز من الجهة الثانية بدلا من قطع القصب حسب الرغبة.: الأنموذج الثاني خطوات العمل بعد ان تثقب نهايتي القصبة من الطرفين واختيارك لاطوال مناسبة والعدد المرغوب فيه أي كلما كثر العدد كبر حجمها . يتكون الانموذج من جهتين فأربط كل جهة على حدة ثم اربط طرفي الجهتين معاً: على شكل حلقة دائرية . اربط الجهتين بالتناوب أي ) قصبة من جهة مع قصبة من جهة اخرى ( حتى: يكتمل الانموذج .","خطوات عمل الانموذج الثالث يمر هذا الانموذج بمراحل الانموذج الثاني نفسها ولكن بامكانك اضافة قطع صغيرة من القصب بين كل قصبة واخرى قياس ) ٣ ( سم وذلك بدلاً من ربطهما مباشرة ) كالانموذج الثاني ( . يمكنك استخدام الخرز بدلاً من القطع الصغيرة للقصب وذلك ليضفي جمالية: عليه . الربط بوساطة الخرز .: الربط الربط ( ) ١() ٢ اشغال الورق المقوى- ً ثالثا دراسة كيفية عمل متوازي المستطيلات والمخروط والهرم وما شابه وتطبيقها .","- أ دراسة الاشكال الهندسية المجسمة وعلاقتها بالسطوح المكونة منها ، الابعاد - ب والتكوينات المعمارية وزخرفتها وتلوينها . متوازي المستطيلات طريقة العمل : نرسم الانفراد المبين بالشكل ادناه ، وهو مكون من مستطيلات مختلفة حيث - . يكون كل أثنين متقابلين متساويين نقطع الاشكال التي يراد تقطيعها وفقاً للمرسوم .","- « نلصق المستطيلات بوساطة الحواف المثنية » المظللة والمبينة بالشكل- المخروط الحواشي المخطط المرسوم لشكل متوازي المستطيلات انفراد متوازي المستطيلات المخروط طريقة العمل : السطح الجانبي للمخروط ، هو عبارة عن قطاع دائري نصف قطره يساوي طول الراسم ) الارتفاع ( وطول قوس القطاع يساوي محيط دائرة قرص القاعدة . والخطوات الآتية توضح الحصول على الشكل . نقوم بلصق الشكل ، وكذلك القاعدة ، وبالتالي نحصل على الانموذج .","انفراد المحيط القاعدة حافة اللصق الهرم الهرم الكامل - ًأولا طريقة العمل يرسم الانفراد المبين بالشكل ادناه . وهو مكون من أربعة مثلثات متساوية: الاضلاع .","يقطع ويلصق بوساطة حواف اللصق المظللة والمبينة بالشكل: الهرم الناقص - ًثانيا يرسم بالطريقة نفسها مع انقطاع رؤوس المثلثات المخططة شكل الهرم الناقص أحد الأجزاء المقطوعة أنفراد الهرم الناقص رابعاً : اعمال الجلود عمل حقائب صغيرة من الجلود : يمكن الإفادة من الجلود المستعملة سابقاً في صنع الحقائب القديمة لصنع حقائب جديدة من عمل الطلبة .","وذلك بتقطيع قطع الجلد بحسب التصميم الجديد ثم تثقيب أطراف القطعة ، مع عمل خيوط أو حبال رفيعة من الجلد نفسه أو لون آخر ، ليتم ربط كل قطعة مع الأخرى لتنتج لنا حقيبة جديدة ويمكن إضافة بعض النقوش أو الرسوم أو لصق ) صور من الجلد ( لاضفاء الجمالية والتزيين . تنفيذ أشغال بطريقة الحرق والكي على الخشب .","تلاقي أشغال الخشب لدى الطلبة أهتماماً ملحوظاً ، خاصة أعمال التخريم ، فان الطلبة يستطيعون إنجاز قطع فنية من الخشب المعاكس او البلاستك على شكل مخطوطات مخرمةٌ او أشكال لأعمال نفعية مثل الاطارات والمشغولات الزخرفية او حاملات الصور الشخصية او الثريات وغيرها من الاعمال الخشبية او البلاستيكية وقد يدخل القماش أرضية لبعض القطع المخرمة .","ويستمتع الطلبة بأعمال حرق الخشب وكيه ، وتنفيذ موضوعات متنوعة وذلك بوساطة الكي والحرق الخاصة سواء ألكهربائية كانت أم الحديدية التي تسخن على النار . وهكذا يدخل التنظيف والتنعيم والطلاء مكملة بعضها لبعضها الاخر للحصول على أشكال جميلة . التفريغ في الخشب ) التخريم ( التفريغ ) التخريم ( في الخشب من الاشغال التي انتشرت انتشاراً سريعاً . فأخذت دوراً مهماً في المدارس ، كما اصبحت تسلية ممتعة نافعة في البيت.","والسبب في ذلك راجع الى قلة الادوات التي يتطلبها العمل ، ورخص نوع الخشب المستعمل ، وجمال اشكال النماذج التي تنتج ، والفوائد الجمة التي يمكن الحصول عليها فضلاً عن انها وسيلة طيبة بتدريب اليد والعين إذا احسن استخدامها .","الأدوات يحتاج العمل في التفريغ ) التخريم ( في الخشب الى بعض الادوات المستعملة في اشغال النجارة وهي : منشار التخريم ويتركب من ذراع معدني على شكل ثلاثة اضلاع من مستطيل وله قبضة خشبية يمُسك بها عند العمل ، ويثبت المنشار بين فكين في نهايتي الذراع بمسمارين محورين، ، لجعل المنشار مشدوداً بعد تثبيته ، ويجب ملاحظة اسنانه إذ يراعي عند تركيبه ان تكون الاسنان متجهة في ميلها إلى اسفل علماً أن نصل المنشار له درجات مختلفة في الخشونة والنعومة .","المسند وهو أما من الخشب أو المعدن . ويمكن عمله في المدرسة من الخشب . ويثبت على المنضدة بوساطة ماسكة معدنية او يثبت بمسامير على المنضدة . المثقاب: وهو كالملف المستعمل في النجارة ، وله رأس يضغط عليه عند استعماله كما هو في الملف . وتركب ) البرينة ( في طرفه الآخر . ويجب عند استعماله وضعه رأسياً ، واستخدام ) البرينة( المناسبة للثقب المطلوب والخشب المستعمل . المواد الاخشاب التي تستعمل في هذه الاعمال هي الخشب المعاكس .","وهي عبارة عن طبقات خفيفة من الخشب ، مثبتة بعضها فوق بعضها الآخر بالغراء ، وتتكون من ثلاث طبقات فأكثر تلصق بالغراء احدهما فوق الاخرى بحيث تكون ألياف كل طبقة متعامدة مع الياف الطبقة التي تليها وتعامد الألياف بهذه الطريقة يجعل المعاكس متيناً مع قلة سمكه .","طريقة العمل بعد مسحه ) بكاغد الجام ( ) السمبادة( - ينقل الرسم من الورقة على الخشب ليكون الخشب نظيفاً ، ونوضع الورقة على الخشب ويوضع تحتها ) الكاربون ( بعد تثبيت الورقة بوساطة الدبابيس ويمرر القلم على الرسم فينطبع الشكل على الخشب. تفرغ الحواف غير التي لها مساس بالشكل بمنشار خشبي كبير ، ويبقى الشكل: المرسوم . نضع الخشبة المراد تفريغها على المسند ، ونثبتها في مكانها ببسط راحة اليد اليسرى عليها .","ونستخدم اليد اليمنى أيضاً في تحريك المنشار ومسكه ويباشر في نشر الخشب على خطوط الرسم . - : وعند العمل يراعى في اثناء النشر ما يأتي ان المنشار في حركته يقع في وسط زاوية المسند تقريباً وفي حالة الزخرفة الدقيقة - أ يكون في وسط الثقب الذي في المسند المذكور . ان يكون ذراع المنشار دائماً افقياً والنصل رأسياً تماماً أوان يلامس ذراع المنشار - ب كتف الطالب على الدوام .","فاذا أريد قطع الخشب في اتجاه معين اديرت قطعة الخشب باليد اليسرى حتى يكون القطع في الاتجاه المطلوب ، مع الاحتفاظ بوضع المنشار كما ذكر . ان يسحب المنشار الى اسفل ويدفع الى أعلى اثناء النشر بكل خفة ، حتى لا - ج يكسر المنشار . عند الدوران بالمنشار في اقواس او زوايا ، يجب الاستمرار في تحريك المنشار - د كالمعتاد في أثناء النشر وادارة قطعة الخشب تدريجاً مع القوس وفي حالة عمل زاوية يحرك المنشار في الموضع نفسه الى اسفل واعلى .","عند تفريغ الاجزاء الداخلية السابقة ذكرها في ) ٤ ( بفك احد طرفي نصل - ه المنشار ثم يدخل في الثقب الذي عمل في الجزء الداخلي المراد تفريغه ، ويربط مرة اخرى ويستمر في النشر . يمسح الخشب عند الانتهاء مرة اخرى بالورقة الزجاجية ) السنباده ( لازالة بقايا الرسم وتثبت الاجزاء بعضها ببعض بالغراء او المسامير . اعطاء فكرة عن عملية صقل الخشب وطلائه: ان فكرة عملية صقل الخشب وطلائه تختلف من عمل الى آخر ومن نجار الى آخر ايضاً .","عملية الصقل : تعني التنعيم ويتم ذلك بطرائق مختلفة قد تستخدم الآلات كالرندة مثلاً او المبرد الخاص بالخشب او ورق الزجاج ) السنباده ( وبعد الانتهاء من عملية التنظيف والتنعيم اي صقل الخشب نبدأ بعملية الطلاء . والطلاء يعني : وضع اما الاصباغ الدهنية ) البوية ( الدملوك ، وهناك مواد للصبغ ممزوجة من مواد عديدة يمكن الحصول عليها من الاسواق المحلية .","التمرينات عمل صينية خطوات العمل : ينقل رسم المحيط الخارجي والمحيط الداخلي الاول وحدهما على قطعة اخرى من: الخشب ويقطعان ايضاً . ننقل رسم المحيط الخارجي والمحيط الداخلي الثاني وحدهما على قطعة ثالثة من: الخشب ويقطعان كذلك . ننقل المحيط الخارجي والمحيط الداخلي الثالث على قطعة رابعة من الخشب ويقطعان ايضاً .","أشغال حرق الخشب: نتمكن من الحصول على زخارف ورسوم واشكال جميلة جداً بوساطة حرق الخشب ، ويستعمل الحرق على الخشب بدلاً من الألوان والأصباغ .","طريقة العمل : نهيء مزارف باحجام مختلفة ذات المقابض الخشبية أو اللدائن كمقابض: ) المفل( ، ثم نهيء ناراً ونضع المزارف فوقها لتحمى الى ان تصبح أشكالها حمراء ) الجمر ( ثم نحاول امرارها على الخطوط المرسومة فوق الخشب ، فبهذه الطريقة تحرق الخطوط وتظهر على الخشب خطوط سوداء ، أو قهوائية غامقة فنحصل بذلك على رسوم أو زخارف جميلة ظاهرة على الخشب . نطلي سطح الخشبة ) بالوارنيش ( ليضفي على الخشبة لمعاناً ورونقاً .","ملاحظة يمكن حرق الخشب أو رسم الزخارف عليه بوساطة الآلة الكاوية الكهربائية ذات الرؤوس الرفيعة التي تستعمل للحيم أو أبدال رأس الآلة الكاوية بقطعة من السلك النحاسي بعد برد رأسه بالمبرد . أشغال المعادن- ًسادسا سبق أن وضحنا هذه الفقرة في مكان اخر في هذا الدليل ، ولنا ثقة كبيرة بزملائنا الأساتذة العاملين في حقل تدريس هذه المادة بقدراتهم وامكاناتهم وتسخير كل هذه الأمكانات باعطاء ما يتوافر في بيئتهم من هذه الأعمال.","ولا نريد تحديد الموضوعات الخاصة بهذه الأشغال . الطباعة - ًسابعا تصميم موضوعات تعبيرية أو زخرفية وحفرها : - أ أن الطباعة وسيلة من الوسائل التعليمية وأولى مراحلها تبدأ بتهيئة التصميم المراد طبعه ثم رسمه على الخشب المعاكس بالحبر الصيني ، أو على البطاطا ، حيث نحضر الأشكال التي يراد طباعتها بشكل بارز أو غائر وحسب التصميم المطلوب . ويمكننا اتباع الخطوات الآتية عندما نريد أن نطبع بوساطة البطاطا .","نأخذ البطاطا الجيدة التي تلائم عملية الطبع ، ونشطرها بالسكين . - نرسم حدود الشكل الذي نريد طبعه على أن يكون بصورة معكوسة ، وذلك- . برسم الشكل أولاً على ورقة شفافة ثم توضع على سطح البطاطا بصورة مقلوبة ثم نضع قطعة كاربون تحتها ، وبإمرار القلم على الخطوط الظاهرة . يظهر الشكل المطلوب . نزيل جميع الاجزاء التي تحيط بالشكل والتي لا نريد ظهورها في الطبع بوساطة - .","ًسكين دقيقة ، حتى يبدو الشكل بارزا ننشر طبقة من الأصباغ المائية أو أي أصباغ أخرى مماثلة على الجزء البارز مستخدمين - . في ذلك الفرشاة الناعمة نجري عملية الطبع على الأوراق المعدة ) ويفضل استعمال الورق غير الصقيل(.- - : أما اذا كانت الصورة مؤلفة من لونين أو أكثر فنتبع الخطوات الآتية نحضر شطرين أو أكثر من البطاطا حسب تعدد الألوان . - . نرسم الصورة على الورقة الشفافة ونقسمها حسب الألوان المطلوبة- .","ننقل كل جزء يمثل لوناً معيناً من الصورة على قطعة من البطاطا- . نجري عملية الحفر السابقة لأبراز الجزء المرسوم- نلون احدى قطع البطاطا باللون المقصود حسب التصميم ثم نقوم بطبع الأوراق- المهيأة على جزء ملون واحد من الصورة ونترك الأوراق حتى تجف ، ثم نستعمل قطعة آخرى من البطاطا لطبع جزء ملون آخر من الصورة على الأوراق جميعها ونتركها تجف وهكذا نكرر طبع بقية الأجزاء حتى تكتمل الصورة .","الحفر على سطح الجبس الأملس والطباعة بلونين او أكثر . - ب - : ويمكن أجراء عملية الطباعة على سطح الجبس الأملس بإتباع الخطوات الآتية نأخذ لوحة من الزجاج تحاط باطار من الكارتون أو الخشب أو غيرها . - نصب الجبس سائلاً على الزجاج المحاط بالاطار كما جاء في أعلاه ، ونتركه حتى- . يجف للحصول على قطعة ذات سطح أملس صالحة للرسم والحفر والطباعة يُهيأ التصميم على ورقة شفافة للموضوع المراد طباعته . - .","يُرسم الموضوع المصمم على سطح الجبس الأملس بعد جفافه- . نحفر التصميم للموضوع… . نضع اللون المطلوب على القطعة الجبسية الملساء نضع الورقة التي نريد أن يكون المصمم مطبوعاً عليها ، وهكذا فأن اللون يظهر- . على الورقة في الأماكن البارزة الموجودة على القطعة الجبسية اذا كانت بلونين فيصار الى ابدال اللون الأول . ويكون اللون الثاني هو العملية الثانية ونطبع اللون الثاني على الورقة .","استعمال ) الجنفاص ( بالتطريز بغرزة الأتمين بوساطة السنارة ) الكروشي ( للبنات . النول اليدوي البسيط تستخدم في الحياكة والنسيج العديد من الأنوال منها ورق المقوى ومنها الخشب وهذه تختلف أيضاً بأختلاف المادة المنسوجة .","النول من ) الكارتون ( يتألف هذا النول من قطعة من ) الكارتون المقوى السميك ( تقص على شكل مستطيل بقياس ٠٢ ×٥١ سم أو أكثر ، ويحيط على بعد ٢ سم من حافاته على شكل مثلث بالتساوي أو تثقب هذه الكارتون بثقوب متساوية من الجهتين. عملية التسدية يثبت خيط السدى ، سواء كان من القطن ، أو الصوف ، في أول علامة وتكون البداية . نستمر بأمرار الخيط من أعلى الى أسفل النول الكارتوني حتى تصل الى نهاية: الكارتونة .","ثم نشد الخيط شداً محكماً .: اللحمة نضع خيط اللحمة في أبرة غليظة ) مخيط ( ، نغرز بين خيوط السدى من اعلى واسفل بالتناوب ثم الرجوع بصورة معكوسة ، وبتكرار العملية يصنع النسيج المطلوب ويمكن وضع لون آخر من الصوف او الخيوط لعمل نقوش بسيطة،ونستعمل مشط الشعر لرصف خيوط اللحمة بعد كل خطوة .","أنموذج اخر لنول يدوي بسيط من الخشب يصنع هذا النول من أربع قطع خشبية اثنتين بطول ٥٢ سم للعرض واثنتين بطول ٠٤ سم للطول ويدق على طول خشبتي العرض ٢٢ مسماراً في كل جهة بطول متوسط ٥ ,١ سم ، وتستخدم مع هذا النول مكوك بسيط من الخشب كما في الشكل أدناه ، وتتم عملية النسيج كما مر سابقاً .","وهناك طريقة حياكة السجادة أو الشرشف وغيرها بطريقة الأبرة والقماش المخرم، ) أو الجنفاص ( وهذه تعتمد على رسم الأنموذج أو هناك تصاميم مطبوعة، تنفذ بوساطة الغرزة على القماش الأتمين وباستطاعة المدرسّة استخدام أبسط الوسائل المتيسرة في محيط الطالبة ) لأن هذه الفقرة خاصة بالطالبات ( المهم في هذه الفقرة الاشارة والتدريب على الحياكة والنسيج لغرض ممارسة هذه الهواية وهي مفضلة لدى البنات .","ونعرض صور من المشغولات ،يطلق على تسميتها) الكوبلان ( وهي طريقة تشبه تطريز الاتمين ولكن باتجاه واحد وباستخدام خيوط الصوف ."]}],"plates":["14_1.jpg"]},{"id":"15","grade":"الصف الثاني المتوسط","unitName":"الوحدة الرابعة","title":"الصف الثاني المتوسط - الوحدة الرابعة: التذوق الفني وتاريخ الفن","pages":"139–142","objectives":"تنمية معرفة الطالب بموضوع «الصف الثاني المتوسط - الوحدة الرابعة: التذوق الفني وتاريخ الفن» وفهم محاوره وممارساته الفنية كما عرضها دليل المعلم.","specific":["أن يتعرف الطالب إلى محور «اطلاع الطلبة على الاعمال الفنية في التاريخ العربي الاسلامي ، وعرض».","أن يتعرف الطالب إلى محور «زيارة المتاحف والأماكن التاريخية ) الآثار ( ، والإهتمام بما تتميز به تلك الآثار».","أن يتعرف الطالب إلى محور «كراهيته تصوير الكائنات الحية وتجسيمها ،واستخدام التجريد في الرسم»."],"tools":"الخامات والأدوات الواردة في الدليل: الخشب، المعادن.","intro":"تهيئة مقترحة: يعرض المعلم مثالاً من موضوع «الصف الثاني المتوسط - الوحدة الرابعة: التذوق الفني وتاريخ الفن»، ثم يطلب من الطلبة وصف ما يلاحظونه وتحديد الفكرة الفنية التي يعالجها الدرس.","summary":["اطلاع الطلبة على الاعمال الفنية في التاريخ العربي الاسلامي ، وعرض؛ مصورات لنماذج من هذه الأعمال أو ) السلايدات ( ، وتحفيز الطلبة على اقتناء ما يستطيعون من صور للفن الاسلامي ) العمارة والزخرفة والخط والفخار…","زيارة المتاحف والأماكن التاريخية ) الآثار ( ، والإهتمام بما تتميز به تلك الآثار؛ من النواحي الفنية والهندسية . زيارة المعارض والإطلاع على الحرف الشعبية ومصنوعاتها والإهتمام من أجل: تطويرها . -: وسنوضح في…","كراهيته تصوير الكائنات الحية وتجسيمها ،واستخدام التجريد في الرسم؛ وقد كان الدافع في ذلك الابتعاد عن تمثيل الكائنات الحية وتصويرها خوفاً من العودة الى الاوثان والمصورات التي تمثل الاله والتي نهى عنها الاسلام…","الابتعاد عن مظاهر الترف والمثل الدنيوية .؛ ابتعد الفنان المسلم عن استخدام مواد غالية الثمن يعد َّ الفخامة مظاهر زائلة ، فاستخدام المواد الرخيصة كالجص والخشب والصلصال الا انه اعطاها قيماً فنية رائعة من زخارف…","اشغال الفراغات بالزخارف .؛ من مميزات الفن الاسلامي الاهتمام بزخرفة السطوح من غير ان يترك فراغاً سواء كان ذلك في العمائر او الاواني او التحف او ابواب الجوامع وفضاءاته الداخلية وغيرها من السطوح . تطوير…"],"mcq":[{"n":1,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 1 في ترتيب الدرس؟","options":["اطلاع الطلبة على الاعمال الفنية في التاريخ العربي الاسلامي ، وعرض","زيارة المتاحف والأماكن التاريخية ) الآثار ( ، والإهتمام بما تتميز به تلك الآثار","كراهيته تصوير الكائنات الحية وتجسيمها ،واستخدام التجريد في الرسم"],"answer":"أ"},{"n":2,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 2 في ترتيب الدرس؟","options":["اطلاع الطلبة على الاعمال الفنية في التاريخ العربي الاسلامي ، وعرض","كراهيته تصوير الكائنات الحية وتجسيمها ،واستخدام التجريد في الرسم","زيارة المتاحف والأماكن التاريخية ) الآثار ( ، والإهتمام بما تتميز به تلك الآثار"],"answer":"ج"},{"n":3,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 3 في ترتيب الدرس؟","options":["زيارة المتاحف والأماكن التاريخية ) الآثار ( ، والإهتمام بما تتميز به تلك الآثار","كراهيته تصوير الكائنات الحية وتجسيمها ،واستخدام التجريد في الرسم","اطلاع الطلبة على الاعمال الفنية في التاريخ العربي الاسلامي ، وعرض"],"answer":"ب"}],"truefalse":[{"n":1,"q":"يتناول الدرس موضوع «اطلاع الطلبة على الاعمال الفنية في التاريخ العربي الاسلامي ، وعرض» ضمن محاوره. ( )","answer":"صح"},{"n":2,"q":"المحور الأول في ترتيب الدليل هو «زيارة المتاحف والأماكن التاريخية ) الآثار ( ، والإهتمام بما تتميز به تلك الآثار». ( )","answer":"خطأ"},{"n":3,"q":"يَرِد موضوع «ان زيارة المعارض او الاطلاع على الاماكن الشعبية وما تنتجه هذه الاماكن من» ضمن محتوى هذا الدرس. ( )","answer":"صح"}],"answerKey":" الاختيار من متعدد: 1 ـ أ، 2 ـ ج، 3 ـ ب | الصح والخطأ: 1 ـ صح، 2 ـ خطأ، 3 ـ صح","topics":["اطلاع الطلبة على الاعمال الفنية في التاريخ العربي الاسلامي ، وعرض","زيارة المتاحف والأماكن التاريخية ) الآثار ( ، والإهتمام بما تتميز به تلك الآثار","كراهيته تصوير الكائنات الحية وتجسيمها ،واستخدام التجريد في الرسم","الابتعاد عن مظاهر الترف والمثل الدنيوية","اشغال الفراغات بالزخارف"],"sections":[{"title":"اطلاع الطلبة على الاعمال الفنية في التاريخ العربي الاسلامي ، وعرض","paras":["مصورات لنماذج من هذه الأعمال أو ) السلايدات ( ، وتحفيز الطلبة على اقتناء ما يستطيعون من صور للفن الاسلامي ) العمارة والزخرفة والخط والفخار والرسوم( واطلاع الطلبة على مميزاتها وخصائصها ."]},{"title":"زيارة المتاحف والأماكن التاريخية ) الآثار ( ، والإهتمام بما تتميز به تلك الآثار","paras":["من النواحي الفنية والهندسية . زيارة المعارض والإطلاع على الحرف الشعبية ومصنوعاتها والإهتمام من أجل: تطويرها .","-: وسنوضح في هذه الفقرات التي جاءت في أعلاه وعلى الصفحات كما يأتي الغاية من هذه الوحدة تعريف الطلبة الاعمال الفنية في التاريخ العربي والاسلامي.: ومن اجل تحقيق هذه الغاية ، يقوم المدرس بجمع ما تيسر من صور لنماذج أو شرائح ) سلايدات ( لعرضها على الطلبة والإستمتاع بها ومعرفة جوانبها التاريخية او الاغراض الوظيفية التي أنتجت من اجلها .","وقد حفل التاريخ العربي الاسلامي بذكر الاعمال الفنية على مر العصور والتي شملت كل الرقعة العربية والأسلامية ، وقد يحصل المدرس على صور لمثل هذه الاعمال من الكتب او المراجع التأريخية التي تتضمن الحديث عن الفنون العربية واساليبها وطرزها وخصائصها ومميزاتها . سواء كانت في العمارة او الزخرفة او الخط او الفخار او الرسوم الحائطية ورسوم المخطوطات كرسوم مقامات الحريري وغيرها .","او قد يستعين المدرس بإستعارة الشرائح ) السلايدات ( او الافلام التي تتحدث عن هذا التراث العظيم والفني الرائع . ان الغرض كما ذكرنا أعلاه هو اطلاع الطلبة على اهم واشهر المباني في التأريخ العربي والاسلامي او الاساليب الزخرفية واصولها في العصور الاسلامية او سيرة الخط العربي واشكاله ، وكذلك ما يتمتع به الفخار والخزف العربي والاسلامي ، وايضاً التصوير العربي والاسلامي . وما تميز به هذا الفن .","مميزات الفن الإسلامي ارتبط الفن الاسلامي بفلسفة الاسلام الروحية الخاصة وعقيدته والتي تعدّ الانسان جزءاً من هذا الكون وليس محور هذا الوجود ، وقد عد الفنان المسلم الانسان والحيوان والنبات عناصر فنية في العمل الفني بعد تحويرها وتنسيقها كي تعبر عن احساسه وافكاره مبتعداً عن اشكالها الطبيعية وتعدّ هذه الظاهرة في الفن الاسلامي جزءاً من - : فلسفة الفن الشرقية وبصورة عامة لهذا الفن مظاهر ومميزات هي"]},{"title":"كراهيته تصوير الكائنات الحية وتجسيمها ،واستخدام التجريد في الرسم","paras":["وقد كان الدافع في ذلك الابتعاد عن تمثيل الكائنات الحية وتصويرها خوفاً من العودة الى الاوثان والمصورات التي تمثل الاله والتي نهى عنها الاسلام غير ان هذه الكراهية بدأت تتلاشى مع زيادة الوعي بحقائق العقيدة الاسلامية فظهرت الرسوم الادمية والحيوانية في الاعمال الفنية والتحف الا المصاحف والمساجد."]},{"title":"الابتعاد عن مظاهر الترف والمثل الدنيوية","paras":["ابتعد الفنان المسلم عن استخدام مواد غالية الثمن يعد َّ الفخامة مظاهر زائلة ، فاستخدام المواد الرخيصة كالجص والخشب والصلصال الا انه اعطاها قيماً فنية رائعة من زخارف دقيقة تؤكد مهارته العالية ."]},{"title":"اشغال الفراغات بالزخارف","paras":["من مميزات الفن الاسلامي الاهتمام بزخرفة السطوح من غير ان يترك فراغاً سواء كان ذلك في العمائر او الاواني او التحف او ابواب الجوامع وفضاءاته الداخلية وغيرها من السطوح .","تطوير الزخارف من اشكال طبيعية الى اشكال هندسية .: ان طابع التأمل الروحي والزهد والعبادة جعلت المسلم يبتعد عن المثل الدنيوية فبدأ بتطوير الاشكال الطبيعية الى هندسية زخرفية معمارية ثم تحولت تدريجياً الى زخارف ، سجاد وقماش وبسط ثم زخرفة الاثاث والاباريق والصحون والزجاج ومن هذه الزخارف التي استخدمها الفنان المسلم هي زخارف هندسية تجريدية وهندسةالحرف العربي ومنها الكوفية والاشكال النباتية بعد تحويرها وكذلك تحوير اشكال الطيور وزخرفة اشكال الحيوانات والانسان) المجردّة (.","ويعني تجريد الشكل أي حذف كل تفاصيله واعطاء رمز يعبر عنه . إن زيارة المتاحف أو الاماكن الأثارية ، يكسبُ الطلبة المعرفة في الجوانب التأريخية، وكذلك الاستمتاع والتمتع بما يشاهدونه من مبانِ أو قطع آثارية في المتاحف او الاماكن نفسها الموجودة فيها تلك الآثار .","إن مشاهدة مثل هذه الآثار تغرس لدى الطلبة من خلال تمتعهم في الجوانب الفنية والهندسية حب التراث واستلهامه ، وحين يطلب منهم رسم موضوعات في سبيل المثال من هذه الاعمال فإنهم يستذكرون التأريخ وقد يضفون عليه طابع المعاصرة . ان زيارة المعارض او الاطلاع على الاماكن الشعبية وما تنتجه هذه الاماكن من مصنوعات شعبية مثل معامل نسيج السجاد او البسط او المفارش وغيرها . وما ينتج من اعمال المعادن وزخرفتها ، وكذلك معامل الفخار او الخزف .","او الاعمال النجارية او اعمال الجلد وغيرها من المصنوعات الشعبية ) الفلكلورية ( هي مجالات أخرى يتعرفها الطالب وتكسبه خبرة ويدرسها عن قرب يستمتع بها ويحبها . وقد يسعى بعض منهم الى تطوير أو تجويد تلك الصناعات المتنوعة وكذلك يضفي عليها الجديد الحسن ."]}],"plates":["15_1.jpg"]},{"id":"16","grade":"الصف الثالث المتوسط","unitName":"الوحدة الأولى","title":"الصف الثالث المتوسط - الوحدة الأولى: التعبير الفني والهندسي","pages":"144–156","objectives":"تنمية معرفة الطالب بموضوع «الصف الثالث المتوسط - الوحدة الأولى: التعبير الفني والهندسي» وفهم محاوره وممارساته الفنية كما عرضها دليل المعلم.","specific":["أن يتعرف الطالب إلى محور «التعبير الفني - الوحدة الأولى».","أن يتعرف الطالب إلى محور «المنظور الهندسي».","أن يتعرف الطالب إلى محور «رسم المجسمات في حالة المنظور»."],"tools":"الخامات والأدوات الواردة في الدليل: الأصباغ، الألوان، الخشب، القماش.","intro":"تهيئة مقترحة: يعرض المعلم مثالاً من موضوع «الصف الثالث المتوسط - الوحدة الأولى: التعبير الفني والهندسي»، ثم يطلب من الطلبة وصف ما يلاحظونه وتحديد الفكرة الفنية التي يعالجها الدرس.","summary":["التعبير الفني - الوحدة الأولى؛ أهتم الفنان منذ أقدم العصور بالظواهر الطبيعية التي لازمت الانسان كالضوء والظل والنظر وغيرها من الأمور التي تخص المحيط الذي نعيش فيه ومشكلة الفضاء ووسائل التعبير عنه . ومن اهم…","المنظور الهندسي؛ هو تطوير رؤية الأشكال والمجسمات الموجودة في الطبيعة لطرق هندسية تحقق نقل تلك الأشكال والمجسمات من الطبيعة الى الصورة . سطح الأرض: المستوى الأفقي الموضوع عليه الشكل المراد رسمه في المنظور .…","رسم المجسمات في حالة المنظور؛ رسم المكعب يأتي المكعب بعد المربع في أهميته بالنسبة للمنظور لأحتوائه على ستة مربعات متساوية ، ولرسم مكعب تحت مستوى النظر يقع على يسار المشاهد ، ترسم المربع المتلاشي ) أ ب ج د (…","رسم الطبيعة الجامدة وتلوينها؛ من الموضوعات التي يمكن للطالب أن يقوم برسمها هي غير المناظر الطبيعية ، تسمى الطبيعية الصامتة . والطبيعة الصامتة هي الأشياء الجامدة التي لا حياةَ فيها . وإن التكوين المبدئي لأي…","يتوقفُ على بعض الخطوات مثل؛ إختيار الموضوع يحسن إختيار عناصر المجموعة التي يراد رسمها ليكون التآلف بينها متوافقاً وغير متناثر . وينبغي أن توضع الوحدة المهمة في الموضوع في مكان بارز من اللوحة أي في وسطها…"],"mcq":[{"n":1,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 1 في ترتيب الدرس؟","options":["التعبير الفني - الوحدة الأولى","المنظور الهندسي","رسم المجسمات في حالة المنظور"],"answer":"أ"},{"n":2,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 2 في ترتيب الدرس؟","options":["التعبير الفني - الوحدة الأولى","رسم المجسمات في حالة المنظور","المنظور الهندسي"],"answer":"ج"},{"n":3,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 3 في ترتيب الدرس؟","options":["المنظور الهندسي","رسم المجسمات في حالة المنظور","التعبير الفني - الوحدة الأولى"],"answer":"ب"}],"truefalse":[{"n":1,"q":"يتناول الدرس موضوع «التعبير الفني - الوحدة الأولى» ضمن محاوره. ( )","answer":"صح"},{"n":2,"q":"المحور الأول في ترتيب الدليل هو «المنظور الهندسي». ( )","answer":"خطأ"},{"n":3,"q":"يَرِد موضوع «توظيف الفن لخدمة المواد الدراسية الأخرى عن طريق إختيار الموضوعات» ضمن محتوى هذا الدرس. ( )","answer":"صح"}],"answerKey":" الاختيار من متعدد: 1 ـ أ، 2 ـ ج، 3 ـ ب | الصح والخطأ: 1 ـ صح، 2 ـ خطأ، 3 ـ صح","topics":["التعبير الفني - الوحدة الأولى","المنظور الهندسي","رسم المجسمات في حالة المنظور","رسم الطبيعة الجامدة وتلوينها","يتوقفُ على بعض الخطوات مثل"],"sections":[{"title":"التعبير الفني - الوحدة الأولى","paras":["أهتم الفنان منذ أقدم العصور بالظواهر الطبيعية التي لازمت الانسان كالضوء والظل والنظر وغيرها من الأمور التي تخص المحيط الذي نعيش فيه ومشكلة الفضاء ووسائل التعبير عنه .","ومن اهم النشاطات الفنية التي سعى اليها العلماء والفنانون وضع قواعد معينة تسهل عليه عملية التعبير الفني عن المحيط الخارجي والتي أطلق عليها فيما بعد » » المنظور « ، وهنا نذكر بعض التعاريف قبل الإجابة عن السؤال وهو كيفية التعبير عن الفضاء والمحافظة على ما فيه من أشكال والتعبير عن المسافات التي تفصل تلك الأشكال . ."]},{"title":"المنظور الهندسي","paras":["هو تطوير رؤية الأشكال والمجسمات الموجودة في الطبيعة لطرق هندسية تحقق نقل تلك الأشكال والمجسمات من الطبيعة الى الصورة . سطح الأرض: المستوى الأفقي الموضوع عليه الشكل المراد رسمه في المنظور .","رسم المستطيل بما ان المستطيل هو جزء من مربع وله الخواص نفسها تقريباً لذا نجد أن هناك عدة طرائق لرسمه في حالة المنظور ونختار أبسطها كما في الخطوات والأشكال الآتية : قائمة - خطوط متلاشية- ( نرسم الخطوط المتلاشية العمودية ) أ ن ( ، ) ب ن ثم نعين المسافة ) أ و ( مساوية الى ارتفاع المستطيل ) عمقه ( ) أ ج ( ومن النقطة ) و ( نرسم خطاً متلاشياً مقدار زاويته ) ٥٤ ̊ ( فمحل تقاطعه مع المستقيم ) أ ن ( في النقطة ) ج َ( يتحدد عمقه المتلاشي ، ثم نصل ) ج َ دَ ( لتحديد المستطيل المطلوب في حالة المنظور ، كما في الاشكال الاتية : ن ق َق ج َج دَ ب أ و د ن ج د ب و أ دَ َج"]},{"title":"رسم المجسمات في حالة المنظور","paras":["رسم المكعب يأتي المكعب بعد المربع في أهميته بالنسبة للمنظور لأحتوائه على ستة مربعات متساوية ، ولرسم مكعب تحت مستوى النظر يقع على يسار المشاهد ، ترسم المربع المتلاشي ) أ ب ج د ( يمثل قاعدة المكعب ثم نقيم الخط الشاقولي ) أ أَ ( والخط ) ب بَ ( اللذين يساويان ضلع المربع ) أ ب ( ، نرسم الخط ) أ بَ ( ، ثم نرسم الخطوط المتلاشية ) أ بَ ، بَ ن ( ثم نقيم الخطين الشاقوليين ) د دَ ، ج جَ ( ثم نكمل الشكل بعد ) أ ن ( نصل بين ) د ج ، دَ ج َ ( في هذا المكعب يشاهد ثلاثة من وجوهه وهي - : ) أ أَ ب بَ ( ، ) أ ج أ ج َ ( ، ) أ بَ ج َ دَ ( كما في الشكل الآتي ن ب أ د ج َج أَ دَ بَ ن ق تطبيقات عملية للمنظور تطبيقات عملية ن ق ن ق"]},{"title":"رسم الطبيعة الجامدة وتلوينها","paras":["من الموضوعات التي يمكن للطالب أن يقوم برسمها هي غير المناظر الطبيعية ، تسمى الطبيعية الصامتة . والطبيعة الصامتة هي الأشياء الجامدة التي لا حياةَ فيها . وإن التكوين المبدئي لأي موضوع له أثره الفعال في إظهار جمال اللوحة وهذا"]},{"title":"يتوقفُ على بعض الخطوات مثل","paras":["إختيار الموضوع يحسن إختيار عناصر المجموعة التي يراد رسمها ليكون التآلف بينها متوافقاً وغير متناثر . وينبغي أن توضع الوحدة المهمة في الموضوع في مكان بارز من اللوحة أي في وسطها تقريباً . الزاوية يجب أن يفضل الطالب إختيار الزاوية المناسبة كأن يرسم الموضوع على بعد معين وفي وضع مناسب .","توزيع الضوء إن لتوزيع الضوء أهمية كبرى في رسم الموضوع ومن مميزات الضوء في اللوحة أن يأتي من ناحية واحدة وأن يبرز تفاصيله ويزيد في جمال تكوينه . الإتزان الإتزان في اللوحة يعني الإستقرار فيها . وقد يسبب عدم إتزان موضوعها عدم ارتياح العين لرؤيتها . الإنسجام الإنسجام معناه أن الموضوع يوحي للناظر بفكرة معينة فيجب أن تتناسب أجزاوه وتنسجم مع بعضها .","ان أداء رسم لوحة يعني توزيع الأصباغ والألوان باختلافها على سطح مستو مثل ) القماش ، الخشب ، الجدار ، الورق ( وذلك من اجل انتاج لوحة تعبر عن قيم معينة فإن تلك القيم تتضمن الآتي : الحركة يجب أن نضع في حسابنا أن وظيفة الضوء خلق الأيهام بالحركة . فالضوء في اللوحة يعني الاحساس الجيد بالحياة فيها في عين المشاهد . العمق وهو محاولة محاكاة البعد الثالث باستخدام قواعد المنظور .","والغرض الأساس للمنظور هو اعطاء الأحساس بالحجوم في فراغ الصورة . ولهذا فإنه يستخدم ظاهرة تصغير العناصر البعيدة أو تخفيض وتدرج اللون في مقدمة الصورة أو وسطها أو خلفيتها . الشكل إن ما يقوم به ما يسمى ) النور والظل ( هو خلق الشكل خلال انتقال متدرج أو فجائي من الضوء الى الظل في اللوحة المرسومة .","الملمس الملمس يعني ارتفاعاً في سطح بعض المساحات في بعض الألوان عن سطح اللوحة لتضفي أحساساً عنيفاً أو خاصاً بالحركة من خلال الملمس الخشن ، يتفق مع الاحساس الذي يريد الطالب أن يعبر عنه . رسم الأشخاص عن الطبيعة ) الموديل ( ودراسة النسب لجسم الانسان يتردد كثير من طلبتنا الأعزاء في رسم الأشخاص لاعتقادهم انه من النوع الشاق ويتطلب جهداً ومهارة .","ولكن التمرين المستمر والتفكير والمران المتواصل يعزز الثقة بالنفس بالممارسة والتدريب كفيل بأن يحقق السبل وتنمية القدرة والموهبة ويصبح باستطاعة الانسان تجاوز هذه الصعوبات ان توافرت الرغبة الصادقة ويكون بمقدوره ان يرسم كل حركة لأي شخص امامه في كل فرصة وفي أي مكان ومراعاة )تمثيل الحركة والحياة بالاضافة للشكل التكويني الذي بنيته للحصول على أحسن نتيجة(.","الخطوط البنائية لهيكل الجسم ان من اهم الامور الرئيسة التي يبنى على أساسها هيكل الجسم انما هو خط الحياة الذي يعبر عن روح الجسم ويوحي بتحقيقه وهو الخط الذي يبدأ من اعلى الرأس وينتهي عند أسفل القدم ، وعليه تبنى الخطوط التحديدية الأخرى التي تمثل هيكل الجسم .","وعندما يتهيأ هذا الخط تهيئة صحيحة نبدأ بتعيين الخطوط التي تحتل مركز الكتفين ومنبت الذراعين ومنبت الساقين وبذلك يتكون لديك هيكل ابتدائي بسيط، وعليك ان تهتم بتخطيط الهيكل العام وان تعتني بالخطوط المعبرة عن تفاصيل النسب المختلفة للجسم . اما رسم الذراعين فيتطلب عناية كبيرة ليتفق توازنهما مع هيكل الجسم .","النسب العامة للجسم عرفت نظرية تقسيم الجسم البشري منذ أقدم العصور واول من وضع هذا التقسيم قدماء المصريين حين قسموه على ) ٩١ ( قسماً بعّد الأصبع الوسطى لليد وحدة للتقسيم . اما الاغريق فكانوا يعدون الرأس من علامات الجمال لذلك قَسموا الجسم على ثمانية أقسام كل قسم يعادل طول الرأس .","وقد سار على نهجهم اكثر الفنانين في العصور المختلفة أمثال ) جان كوزان وغيره ( وكانت اكثر التماثيل اليونانية ٨ ( رؤوس ولكن المدارس الفنية الحديثة ترى ان يكون - ٥ و ٧- تتراوح بين ) ٧ الجسم يعادل سبع مرات ونصف بالنسبة للرأس . وهذا هو الأساس الذي يقوم عليه الفن الحديث .","ويعود الفضل في ايجاد تفاصيل النسب الثمانية للجسم الكامل الخالي من العيوب والتشويهات للدكتور ) بول ريشير ( الذي وضع هذه النسب في دورته عن التشريح في مدرسة الفنون الجميلة بباريس مقياس ١ ٧ القسم الأول : من قمة الرأس الى أسفل الذقن . القسم الثاني : ينتهي عند اسفل عظام الصدر . القسم الثالث: ينتهي عند أول العجز أي عند أسفل المرفق بقليل . القسم الرابع : ينتهي عند أسفل الجذع اي عند خط يوازي رسغ اليد .","القسم الخامس: يمر من نقطة فوق الركبة بقليل . القسم السادس: يمر من زاوية بسطة الساق في أعرض اجزائها . القسم السابع : يصل عند رأس سطح القدم . أما النصف الاخير فيمثل الأنحدار بين كاحل الرجل وأسفل القدم . مقياس ثمانية رؤوس القسم الأول : من قمة الرأس الى أسفل الذقن . القسم الثاني : ينتهي عند منتصف الصدر ويمر بالعضد . القسم الثالث : ينتهي عند السرة ويمر بالخصر والمرفق .","القسم الرابع : ينتهي عند ملتقى الفخذين ويمر بالمعصم ) رسغ اليد ( وهذا الخط هو المنصف للجسم . القسم الخامس : يمر بمنتصف الفخذ ورأس الاصبع الوسطى لليد . القسم السادس : ينتهي عند أسفل الركبة . القسم السابع : ينتهي عند بسطة الساق . القسم الثامن : ينتهي عند أسفل القدمين .","اما نسب التقسيم لعرض الجسم فالمسافة ما بين الكتفين تعادل طول رأسين والبعد بين الوركين يعادل… امتداد الذراعين بمحاذاة الجسم يقع عند منتصف الفخذين أي في نهاية القسم الخامس وكثيراً ما يخطأ بعض المبتدئين فيرسموا الأيدي قصيرة لا يتجاوز طولها الوركين . اذا كان الذراع في الوضع المبين في الشكل فإن نهايته ) أي رؤوس الأصابع(: تصل الى أعلى الكتف اي ان الطولين متساويان تقريباً . طول القدم يعادل طول نصف الساق تقريباً .","أما ما يتعلق بمقياس المرأة فيختلف عن مقياس جسم الرجل لان بنية جسمها انحف . و يلاحظ في جسمها ان عظم الحرقفة والوركين اعرض . وساقيها اقصر وكتفيها أضيق . . التعبير عن المناسبات والأعياد والموضوعات الانسانية والأجتماعية: تحدثنا فيما سبق عن ممارسة الطلبة لرسم وتصوير المناسبات والاعياد والموضوعات الانسانية والأجتماعية . نذكر طلبتنا بما فيها من قيم وما أنطوت عليه من مضامين تغرز لديه القيم الأنسانية .","عند ممارسة تصويرها أو رسمها أو التفكير بها واستذكارها و استنباط معانيها . لذا ننصح طلبتنا متابعة المعارض وزيارة مراكز الفنون حيث يجدون فيها اللوحات المجسدة لحركة الحياة بتعبيرات ناطقة وجميلة . توظيف الفن لخدمة المواد الدراسية الأخرى عن طريق إختيار الموضوعات ذات العلاقة .","سبق وان تحدثنا عن أهمية توظيف الرسم خاصة في اظهار وتوضيح كثير من المفاهيم العلمية المبسطة عن طريق التصوير والشرح الوافي مع التخطيطات والرسومات الموضحة لتلك الفعاليات المعرفية . ولا نريد الخوض أكثر مما ذكرناه . فقد عدت مادة التربية الفنية في المفاهيم التربوية الحديثة جزءاً متمماً للمواد الدراسية الأخرى ."]}],"plates":["16_1.jpg"]},{"id":"17","grade":"الصف الثالث المتوسط","unitName":"الوحدة الثانية","title":"الصف الثالث المتوسط - الوحدة الثانية: التصميم والزخرفة","pages":"157–163","objectives":"تنمية معرفة الطالب بموضوع «الصف الثالث المتوسط - الوحدة الثانية: التصميم والزخرفة» وفهم محاوره وممارساته الفنية كما عرضها دليل المعلم.","specific":["أن يتعرف الطالب إلى محور «عمل تصاميم لأغلفة الكتب . ) يرجى الرجوع الى ما كتب عن هذه الفقرة».","أن يتعرف الطالب إلى محور «الرسالة : وهي مضمون العملية الأتصالية أو مجموعة الآراء والأفكار المطلوب».","أن يتعرف الطالب إلى محور «التوازن : وهو التنسيق المتكامل للملصق والتطبيق الفعلي لكل اسس»."],"tools":"الخامات والأدوات الواردة في الدليل: الألوان، الجبس، الخشب، الألوان المائية.","intro":"تهيئة مقترحة: يعرض المعلم مثالاً من موضوع «الصف الثالث المتوسط - الوحدة الثانية: التصميم والزخرفة»، ثم يطلب من الطلبة وصف ما يلاحظونه وتحديد الفكرة الفنية التي يعالجها الدرس.","summary":["عمل تصاميم لأغلفة الكتب . ) يرجى الرجوع الى ما كتب عن هذه الفقرة؛ سابقاً وفي الصف الأول ( . الملصق ) البوستر (: يعتمد الملصق أو ) البوستر ( اساساً على بساطة الشكل وقوة التعبير وسرعة التأثير واعتماده اللقطة…","الرسالة : وهي مضمون العملية الأتصالية أو مجموعة الآراء والأفكار المطلوب؛ توصيلها للجمهور ، ) الموضوع الفني ( . المستقبل : هو الفرد أو الجمهور الذي تستهدفه بالاتصال للحصول على نتيجة: معينة أو الوصول به الى…","التوازن : وهو التنسيق المتكامل للملصق والتطبيق الفعلي لكل اسس؛ التصميم. والتوازن معناه توزيع العناصر المختلفة على مساحة الملصق ، مع مراعاة أهمية كل عنصر وعلاقته مع العناصر الأخرى . التناسب : يقصد به العلاقة…","التباين : هو الإختلاف في عرض عناصر الملصق ومحتوياته بطريقة تجعل؛ الملصق لافتاً للنظر . الوحدة : وهي تآلف كل عنصر مع بقية العناصر المكونة للملصق وأتحادها: في خلق علاقة تجانس مع بعضها وتناسق فني يعطي الاحساس…","الحفر على الجبس أو الخشب أو السطوح المطاطية ) الليونوم ( وطبعها؛ بلون واحد أوأكثر إن هذه الفقرة تعني الطباعة وهذه الطريقة من الطباعة تتبع العديد من الخطوات . - : كما يأتي تحضير القالب ونعني بالقالب ] اما أن…"],"mcq":[{"n":1,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 1 في ترتيب الدرس؟","options":["عمل تصاميم لأغلفة الكتب . ) يرجى الرجوع الى ما كتب عن هذه الفقرة","الرسالة : وهي مضمون العملية الأتصالية أو مجموعة الآراء والأفكار المطلوب","التوازن : وهو التنسيق المتكامل للملصق والتطبيق الفعلي لكل اسس"],"answer":"أ"},{"n":2,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 2 في ترتيب الدرس؟","options":["عمل تصاميم لأغلفة الكتب . ) يرجى الرجوع الى ما كتب عن هذه الفقرة","التوازن : وهو التنسيق المتكامل للملصق والتطبيق الفعلي لكل اسس","الرسالة : وهي مضمون العملية الأتصالية أو مجموعة الآراء والأفكار المطلوب"],"answer":"ج"},{"n":3,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 3 في ترتيب الدرس؟","options":["الرسالة : وهي مضمون العملية الأتصالية أو مجموعة الآراء والأفكار المطلوب","التوازن : وهو التنسيق المتكامل للملصق والتطبيق الفعلي لكل اسس","عمل تصاميم لأغلفة الكتب . ) يرجى الرجوع الى ما كتب عن هذه الفقرة"],"answer":"ب"}],"truefalse":[{"n":1,"q":"يتناول الدرس موضوع «عمل تصاميم لأغلفة الكتب . ) يرجى الرجوع الى ما كتب عن هذه الفقرة» ضمن محاوره. ( )","answer":"صح"},{"n":2,"q":"المحور الأول في ترتيب الدليل هو «الرسالة : وهي مضمون العملية الأتصالية أو مجموعة الآراء والأفكار المطلوب». ( )","answer":"خطأ"},{"n":3,"q":"يَرِد موضوع «يوزعُ على الطلبة أنموذج ) ١ ( يقوم الطالب برسم هذه الحروف ومقاييسها» ضمن محتوى هذا الدرس. ( )","answer":"صح"}],"answerKey":" الاختيار من متعدد: 1 ـ أ، 2 ـ ج، 3 ـ ب | الصح والخطأ: 1 ـ صح، 2 ـ خطأ، 3 ـ صح","topics":["عمل تصاميم لأغلفة الكتب . ) يرجى الرجوع الى ما كتب عن هذه الفقرة","الرسالة : وهي مضمون العملية الأتصالية أو مجموعة الآراء والأفكار المطلوب","التوازن : وهو التنسيق المتكامل للملصق والتطبيق الفعلي لكل اسس","التباين : هو الإختلاف في عرض عناصر الملصق ومحتوياته بطريقة تجعل","الحفر على الجبس أو الخشب أو السطوح المطاطية ) الليونوم ( وطبعها"],"sections":[{"title":"عمل تصاميم لأغلفة الكتب . ) يرجى الرجوع الى ما كتب عن هذه الفقرة","paras":["سابقاً وفي الصف الأول ( . الملصق ) البوستر (: يعتمد الملصق أو ) البوستر ( اساساً على بساطة الشكل وقوة التعبير وسرعة التأثير واعتماده اللقطة السريعة في ترجمة المضمون ، للمُلصق عنصران مهمان وهما : الموضوع والكتابة .","ولغرض رسم ملصق ما ، يجب أن تكون البداية عبارة عن تخطيط سابق صغير يتم تلوينه بعد المناقشة مع الطلاب وصولاً الى أفضل الصيغ الفنية والوظيفية للملصق ، ثم يرسم بالحجم المطلوب ويلون بالألوان المائية المعتمة ) البوستر ( على شكل مساحات بسيطة تعتمد في أغلب الأحيان على التضاد اللوني كي يؤثر تأثيراً سريعاً في أعين المشاهدين .","ويمكن استعمال الوان البنتلايت بدلاً من ) البوستر ( ولا سيما عندما يراد عرض الملصقات ) البوسترات ( في الظروف الجوية الخارجية . والخامات التي يرسم عليها ) البوستر ( هي الورق والكارتون الأبيض أو الملون ، والخشب المعاكس والفايبر . وبالامكان استخدام بعض الصور ولصقها مع الرسم إذا تطلب الأمر ولإضفاء الجمالية .","فالملصق هو وسيلة اتصال مرئية تعبر عن فكرة أو موضوع معين بالصور والرسوم وكتابة الكلمات والعبارات المناسبة ، وهي وسائل فعالة للإتصال بالجماهير والتأثير فيها . أو هو مطبوع يصمم من اجل يفهم من نظرة سريعة ، وهو يجمع مؤثرات بصرية مباشرة ذات مقدرة على منافسة المحيط بصرياً ولكي يكون كذلك ينبغي ان يتسم بالوضوح والتمييز . عناصر عملية الإتصال تتكون عناصر العملية الإتصالية من"]},{"title":"الرسالة : وهي مضمون العملية الأتصالية أو مجموعة الآراء والأفكار المطلوب","paras":["توصيلها للجمهور ، ) الموضوع الفني ( . المستقبل : هو الفرد أو الجمهور الذي تستهدفه بالاتصال للحصول على نتيجة: معينة أو الوصول به الى موقف أو قرار معين ) الطالب ( . مواصفات الملصق الناجح: يشترط مواصفات فنية اساسية يجب توفرها في الملصق الناجح وهي :"]},{"title":"التوازن : وهو التنسيق المتكامل للملصق والتطبيق الفعلي لكل اسس","paras":["التصميم. والتوازن معناه توزيع العناصر المختلفة على مساحة الملصق ، مع مراعاة أهمية كل عنصر وعلاقته مع العناصر الأخرى . التناسب : يقصد به العلاقة بين الطول والعرض سواء بالنسبة لحجم الملصق أو: الاجزاء لكل عنصر من مكونات الملصق ."]},{"title":"التباين : هو الإختلاف في عرض عناصر الملصق ومحتوياته بطريقة تجعل","paras":["الملصق لافتاً للنظر . الوحدة : وهي تآلف كل عنصر مع بقية العناصر المكونة للملصق وأتحادها: في خلق علاقة تجانس مع بعضها وتناسق فني يعطي الاحساس بالتكامل في التصميم . التتابع : وهو قدرة المصمم على أن يجعل المشاهد والقارىء ينظر الى نقطة: بداية معينة في الملصق ، ثم ينتقل الى نقاط أخرى وهكذا ."]},{"title":"الحفر على الجبس أو الخشب أو السطوح المطاطية ) الليونوم ( وطبعها","paras":["بلون واحد أوأكثر إن هذه الفقرة تعني الطباعة وهذه الطريقة من الطباعة تتبع العديد من الخطوات . - : كما يأتي تحضير القالب ونعني بالقالب ] اما أن يكون من الجبس أو الخشب أو السطوح - أ المطاطية ) الليونوم (.[ عملية الطباعة بلون واحد . - ب وفيما يتعلق بتحضير القالب ، نهيء التصميم أو الرسوم أو الصور المراد طبعها - أ ونحضره على المواد الآنفة الذكر ، بحيث يكون الشكل محفوراً .","باستخدامنا ) الأدوات الحادة أو القاطعة أو القاشطة ( لغرض الحصول على الأنموذج المطلوب . الاستمرار في التمرين على رسم الزخارف الطبيعية ومنها النباتية مع تأكيد أساليب الإشتقاق والتحوير يفضل الاستمرار في التمرينات على رسم الزخارف الطبيعية ومنها النباتية مع تأكيدنا أساليب الإشتقاق والتحوير .","ونود أن نشير هنا الى العناصر والوحدات النباتية التي يمكن ملاحظة النماذج الآتية منها وكيف يمكن للطالب ان يضيف عناصر جديدة أو رسوماً جديدة بحيث يصبح الشكل الجديد شكلاً محوراً أو مشتقاً من رسومات موجودة . النماذج الموجودة تمثل زخارف على وفق قواعد الاشتقاق والتحوير بطريقة التقابل والتماثل والتناظر ) زخارف نباتية محورة ومتماثلة ( .","التمرين على الخط الكوفي البسيط ، وإعطاء الأسس التقنية لحروفه باستخدام الأدوات الهندسية أثبتت التجارب التي قام بها أساتذة الخط العربي .","ان الخط الكوفي لا يحتاج الى موهبة الا في ابتكار التصاميم واللوحات المركبة وحروف عبد القادر هي أفضل - : الحروف التي تمكن الطالب من تعلمها وتكون طريقة التدريس كالآتي يوزعُ على الطلبة أنموذج ) ١ ( يقوم الطالب برسم هذه الحروف ومقاييسها ويتخذ ربع سنتمتر أو نصف سنتمتراً واحداً عرضاً لهذه الحروف . والأفضل هو نصف سنتمتر ثم يقوم الطالب بتقليدها جميعاً . يبدأ بوصل هذه الحروف القابلة للاتصال .","وهنا توجد نقطة مهمة من ناحية: توزيع المسافات بين الحروف ، يفضل أن تكون المسافات متساوية بين الحروف المتصلة والمنفصلة ، وقد وجد أن الخط الكوفي يكون أكثر جمالاً إذا تركت وحدة واحدة بين الحروف المنفصلة ووحدتان بين الحروف المتصلة . . ( وهذه نماذج لمشاهير خطاطي هذا النوع من الخط العربي ) الكوفي"]}],"plates":["17_1.jpg","17_2.jpg"]},{"id":"18","grade":"الصف الثالث المتوسط","unitName":"الوحدة الثالثة","title":"الصف الثالث المتوسط - الوحدة الثالثة: التشكيل المجسم","pages":"164–184","objectives":"تنمية معرفة الطالب بموضوع «الصف الثالث المتوسط - الوحدة الثالثة: التشكيل المجسم» وفهم محاوره وممارساته الفنية كما عرضها دليل المعلم.","specific":["أن يتعرف الطالب إلى محور «الاستمرار في تنفيذ الموضوعات عن طريق النحت البارز والغائر مع عمل القوالب».","أن يتعرف الطالب إلى محور «يرجى الرجوع الى الوحدتين آنفتي الذكر في الصفين الأول والثاني وتطوير بعض».","أن يتعرف الطالب إلى محور «تنفيذ الموضوعات بطريقة كي ) حرق الخشب ( .»."],"tools":"الخامات والأدوات الواردة في الدليل: الطين، الجبس، الخشب، المعادن، الأسلاك، الورق المقوى، الخيوط، القماش.","intro":"تهيئة مقترحة: يعرض المعلم مثالاً من موضوع «الصف الثالث المتوسط - الوحدة الثالثة: التشكيل المجسم»، ثم يطلب من الطلبة وصف ما يلاحظونه وتحديد الفكرة الفنية التي يعالجها الدرس.","summary":["الاستمرار في تنفيذ الموضوعات عن طريق النحت البارز والغائر مع عمل القوالب؛ وصبها . شرح مبسط لعملية التزجيج ) تلوين الطين وفخره ( مع تطبيق عملي عليه: )ان أمكن ( . تحدثنا عن النحت والفخار في الوحدتين التي مرت…","يرجى الرجوع الى الوحدتين آنفتي الذكر في الصفين الأول والثاني وتطوير بعض؛ الطرائق التي أستخدمت في نحت الموضوعات البارزة والغائرة . وكذلك القيام بصب القوالب الجبسية لها . يرجى الرجوع الى الوحدتين آنفتي الذكر…","تنفيذ الموضوعات بطريقة كي ) حرق الخشب ( .؛ يرجى الرجوع الى ما وضح في مكان آخر من هذا الكتاب حيث لا نريد الإطالة. ونكتفي بالذي كتب سابقاً . تنفيذ بعض الموضوعات باستعمال صفائح المعدن بطريقة الضغط وكذلك عمل:…","اشغال الأسلاك المعدنية والإستفادة منها في التعبير عن بعض الموضوعات؛ التزينية. إن أشغال السلك من الأشغال المشوقة . وكثير من منتجاتها صالح للاستعمال في بعض حاجاتنا المنزلية . فالتدريب على استعمال الأدوات التي…","وهذا الأنموذج يتطلب الخطوات الآتية؛ نرسم دائرة على ورقة بوساطة الفرجال . - . نقص الأسلاك بالطول المطلوب: . ندخل الحلقات الى الدوائر التي عملناها أعلاه- نربط الدوائر بسلك يتناسب وشكلها . ويمكن الافادة منها…"],"mcq":[{"n":1,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 1 في ترتيب الدرس؟","options":["الاستمرار في تنفيذ الموضوعات عن طريق النحت البارز والغائر مع عمل القوالب","يرجى الرجوع الى الوحدتين آنفتي الذكر في الصفين الأول والثاني وتطوير بعض","تنفيذ الموضوعات بطريقة كي ) حرق الخشب ( ."],"answer":"أ"},{"n":2,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 2 في ترتيب الدرس؟","options":["الاستمرار في تنفيذ الموضوعات عن طريق النحت البارز والغائر مع عمل القوالب","تنفيذ الموضوعات بطريقة كي ) حرق الخشب ( .","يرجى الرجوع الى الوحدتين آنفتي الذكر في الصفين الأول والثاني وتطوير بعض"],"answer":"ج"},{"n":3,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 3 في ترتيب الدرس؟","options":["يرجى الرجوع الى الوحدتين آنفتي الذكر في الصفين الأول والثاني وتطوير بعض","تنفيذ الموضوعات بطريقة كي ) حرق الخشب ( .","الاستمرار في تنفيذ الموضوعات عن طريق النحت البارز والغائر مع عمل القوالب"],"answer":"ب"}],"truefalse":[{"n":1,"q":"يتناول الدرس موضوع «الاستمرار في تنفيذ الموضوعات عن طريق النحت البارز والغائر مع عمل القوالب» ضمن محاوره. ( )","answer":"صح"},{"n":2,"q":"المحور الأول في ترتيب الدليل هو «يرجى الرجوع الى الوحدتين آنفتي الذكر في الصفين الأول والثاني وتطوير بعض». ( )","answer":"خطأ"},{"n":3,"q":"يَرِد موضوع «تشد الأزهار على شكل باقات مع الاهتمام بطريقة تنسيق الزهور بأشكالها» ضمن محتوى هذا الدرس. ( )","answer":"صح"}],"answerKey":" الاختيار من متعدد: 1 ـ أ، 2 ـ ج، 3 ـ ب | الصح والخطأ: 1 ـ صح، 2 ـ خطأ، 3 ـ صح","topics":["الاستمرار في تنفيذ الموضوعات عن طريق النحت البارز والغائر مع عمل القوالب","يرجى الرجوع الى الوحدتين آنفتي الذكر في الصفين الأول والثاني وتطوير بعض","تنفيذ الموضوعات بطريقة كي ) حرق الخشب (","اشغال الأسلاك المعدنية والإستفادة منها في التعبير عن بعض الموضوعات","وهذا الأنموذج يتطلب الخطوات الآتية"],"sections":[{"title":"الاستمرار في تنفيذ الموضوعات عن طريق النحت البارز والغائر مع عمل القوالب","paras":["وصبها . شرح مبسط لعملية التزجيج ) تلوين الطين وفخره ( مع تطبيق عملي عليه: )ان أمكن ( . تحدثنا عن النحت والفخار في الوحدتين التي مرت بنا في الصفين الأول والثاني.: ووضحنا وشرحنا عمل التماثيل وأعطينا نماذج لطرائق إنتاجها وكذلك كيفية صب القوالب لها."]},{"title":"يرجى الرجوع الى الوحدتين آنفتي الذكر في الصفين الأول والثاني وتطوير بعض","paras":["الطرائق التي أستخدمت في نحت الموضوعات البارزة والغائرة . وكذلك القيام بصب القوالب الجبسية لها . يرجى الرجوع الى الوحدتين آنفتي الذكر في الصفين الأول والثاني للإفادة: منها. التزجيج: شرح مبسط لعملية التزجيج ) تلوين الطين وفخره ( . بعد الانتهاء من عمل الأواني والنماذج الطينية المختلفة والتأكد من جفافها التام نضعها في الاماكن المخصصة المعدة لهذا الغرض ثم ندخلها الفرن .","أي في الفراغ الكائن داخل الفرن حتى يمتلىء تماماً بحيث نترك مسافة مناسبة بين آنية وأخرى لتفادي التصاقها ببعضها وتعرضها للتلف . ثم نوقد النار ونستمر على امدادها بالوقود حوالي العشر ساعات مع تأكدنا من أن درجات الحرارة في الفرن عالية ، بحيث نؤمن حرق الموجود بصورة صحيحة .","وبعد ذلك نقف عن مد الفرن بالوقود ونتركه مغلفاً بضع ساعات حتى نتأكد من أن النار قد خمدت تماماً وبردت النماذج الموجودة بداخل الفرن كلها ، وعندما تبرد نخرجها مفخورة جاهزة . فالتزجيج يعني الطلاء الزجاجي الذي تطلى به الأواني الفخارية بعد الحرقة الأولى! وهذا الطلاء يعطي الاناء طبقة تمنع مرور المياه في القطع المصنوعة .","وعملية التزجيج عملية تتطلب دراسة للألوان دراسة كيمياوية من حيث الوانها ومقاديرها فضلاً عن درجات الحرارة فيها . وهناك عملية التزجيج البسيطة التي تتم على يدي الكواز أو الفخاري المحلي وذلك لإنتاج ) البستوكة مثلاً ( أو الكاشي الملون الذي يستعمل في المساجد . أما فيما يتعلق بالتزجيج العلمي فله قوانينه وأساتذته ، يمكن الرجوع لهم ."]},{"title":"تنفيذ الموضوعات بطريقة كي ) حرق الخشب (","paras":["يرجى الرجوع الى ما وضح في مكان آخر من هذا الكتاب حيث لا نريد الإطالة. ونكتفي بالذي كتب سابقاً . تنفيذ بعض الموضوعات باستعمال صفائح المعدن بطريقة الضغط وكذلك عمل: الحلي . نطلب من زملائنا المدرسين التوسع بهذه الطرائق ، واتمام موضوعات أخرى كأن: نعمل ما يشبه الحلي كالأسورة والأقراط والقلائد أو الخواتم وما يشابهها من هذه الأعمال .","ويستخدم كثير من العاملين في هذا الميدان ، الاوراق الفضية التي تستعمل في - : علب الحليب ، أو أوراق الالمنيوم التي تباع في الأسواق لأنها أولاً : رخيصة الثمن . ثانياً : متوافرة وسهلة التشكيل . وأحياناً يستخدم الخرز والسلك الرفيع لإنجاز تلك المشغولات زيادة في جمالية العمل ."]},{"title":"اشغال الأسلاك المعدنية والإستفادة منها في التعبير عن بعض الموضوعات","paras":["التزينية. إن أشغال السلك من الأشغال المشوقة . وكثير من منتجاتها صالح للاستعمال في بعض حاجاتنا المنزلية . فالتدريب على استعمال الأدوات التي نحتاجها في عمل مشغولات السلك فهي مواد بسيطة ومتيسرة في المدارس أو الأسواق . وأشغال السلك لا تتطلب المهارات الخاصة ، انما تحتاج الى تهيئة مستلزماتها والأماكن التي سيتم العمل فيها وربما تحتاج الى مواد اللحام .","ومن الأعمال التي يمكن انتاجها من السلك وأحياناً نستخدم الصفائح الرفيعة المعدنية بوصفها عنصراً متمماً لهذه الأعمال ومنها: تصاميم من الأسلاك لوضع أصص النباتات والورود في المنازل . - . حامل الهاتف ، أو رفوف لها- غطاء مصباح يضاف اليه- . القماش أشغال تزينية كالمربعات أو- . الدوائر وغيرها اشغال لحركات آدمية أو)ألعاب ( - . حيوانية أشغال نباتية . - . أشغال نماذج متعددة- إما تزينية أو ذات نفع خاص من ابتكار الطلبة .","ونعرض بعض الأعمال البسيطة الخاصة بالسلك مثل سلسلة من الحلقات المربعة،بأن نرسم مربعاً معلوماً ونبدأ بثني الأسلاك على وفق الأنموذج المرسوم ، ونعد الحلقات المطلوبة من المربعات ، بحيث تصبح كالسلسلة . - : • سلسلة من حلقات مستديرة"]},{"title":"وهذا الأنموذج يتطلب الخطوات الآتية","paras":["نرسم دائرة على ورقة بوساطة الفرجال . - . نقص الأسلاك بالطول المطلوب: . ندخل الحلقات الى الدوائر التي عملناها أعلاه- نربط الدوائر بسلك يتناسب وشكلها . ويمكن الافادة منها في عمل تشكيلات- . هندسية متنوعة سلسلة حلقات مربعة سلسلة حلقات مستديرة حفر النحاس ) السميك ( بالمطرقة والازميل الادوات : مطرقة ، ازميل حادة الرأس بعرض لا يزيد على ) ٥ملم ( اسفلت ) جير ( وعاء مجوف لوضع الاسفلت فيه .","طريقة العمل : يكون ميل الازميل على سطح النحاس بمقدار ) ٥٤ ْ( ، ونضرب عليه ١ ملم (. - بالمطرقة ضربات خفيفة فيحفر النحاس بعمق يتراوح بين ) ١/٢ و نستعمل الازميل العريض ) ٥ملم( في حفر المساحات العريضة . وبعد الانتهاء من العمل ترفع قطعة النحاس عن الاسفلت وتنظف وتلمع بمادة: ) البراسو ( لنحصل على الشكل النهائي المطلوب . .","التدريب على عقد المكرمية وتنفيذ بعض النماذج البسيطة جاءت تسمية المكرمية من استعمال الخيوط أو الحبال لربط شجرة العنب وأغصانها بعقد معروفة منذ القدم . حيث لشجرة العنب أسم آخر هو ما يدعى بالكروم ومن هنا جاء استخدام كلمة المكرمية التي أشتقت من الكرمة أو الكروم . وقيل ان أصل هذه العقدة من التراث العربي وفي شمال أفريقيا وعلى الأخص في مراكش ، ويذكر الكثير أن العديد من التصاميم للمكرمية لها صفات عربية مشتقة من أسمها .","وقد انتقل استعمال عقد المكرميات الى أنحاء مختلفة من العالم ودخلت هذه الصناعة في المنسوجات وأصبحت لها أغراض عدة كحمالات الأصص أو لوحات تزينية تعلق على الجدران أواستعمالها في نهايات المناشف والشراشف أو في أغطية الرأس كما أنها أستخدمت في تزيين الملابس وغيرها . ولقد شاع استعمالها هذه الايام بكثرة وقد يجدها المرء في مجالات متعددة ... وهناك هدف آخر هو تعرف الطالب بملامس الخيوط فمنها الناعم الى الخشن وهكذا .","وأشار كثير من المربين الى أهمية التعامل معها لهذا الغرض . و نعطي بعض التوضيحات وطرائق استخدام هذا الفن في بعض المشغولات التزينية التي يستطيع الطلبة تنفيذها . طريقة العمل - : إن عقدة المكرمية تتكون من نوعين من العقد وهي نصف عقدة وتسمى ) العقدة الحلزونية ( . وعند شروعنا بعمل أي نوع من المكرمية ، فإن ذلك يتطلب منا ضبط أطوال الخيوط التي تدخل في العمل ويراعى في ذلك أيضاً سمك الخيط ورفعه .","فأذا أردنا طول العمل مثلاً متراً واحداً ، يجب أن نأخذ طول الخيط بطول مترين أو أكثر ، حيث لف العقد يتطلب هذا الطول .","وللحصول على خيوط مرتبطة بحلقة معدنية او بلاستيكية لاحظ الاشكال الآتية : - : للحصول على أنواع من العقد فإننا نتابع هنا المراحل كما يأتي )١( العقدة المربعة المرحلة الأولى نترك الخيطين الوسطيين سائبين والعمل يكون بالخيطين الجانبيين فنضع الخيط الأيسر فوق الخيطين الوسطيين وتحت الخيط الجانبي الأيمن كما موضح في الشكل.","المرحلة الثانية نضع خيط الحياكة الأيمن تحت الخيطين الوسطيين ثم نخرجه من الحلقة الحاصلة بين الخيط الأيسر والخيطين الوسطيين كما في الشكل : المرحلة الثالثة نضع الخيط الأيمن فوق الخيطين الوسطيين وتحت الخيط الأيسر ، لاحظ الشكل. المرحلة الرابعة أخيراً نضع الخيط الأيسر تحت الخيطين الوسطيين ثم نخرجه من الحلقة الحاصلة بين الخيط الأيمن والخيطين الوسطيين . كما في الشكل .","نشد على الخيطين الجانبيين أفقياً والخيطين الوسطيين الى الأسفل فتحصل لدينا العقدة المربعة . ) ٢ ( العقدة نصف الملوية العمودية : : ( ) ٣( نصف عقدة ) العقدة الحلزونية نستعمل في هذه العقدة المرحلة الأولى )السابقة ( وعند تكرارها بدون فراغ بين العقد تكون العقدة الحلزونية كما هي موضحة في الشكل .","انواع مختلفة من الضفائر مستعملا العقد المربعة والنصفية : وقد نلاحظ عند الاستمرار بعمل العقدة الحلزونية ، أن الخيوط تبدأ مجتمعة بالإلتواءوهذه هي الميزة في شكل العقدة ، فيجب أن ندع الخيوط تلتوي بشكلها المطلوب، ونستمر بحياكة المرحلة الأولى والثانية ، ونستمر بالعمل حتى ننتهي من إنجاز التصميم المطلوب . وهذه نماذج من عقد المكرميات التي تستعمل عادة في حياكة الحقائب . وهذه نماذج من المكرميات.","تنسيق الزهور الأصطناعية تطورت صناعة الزهور وتنسيقها تطوراً ملموساً ، وأخذت باقات الزهور تقدم في الكثير من المناسبات منها زيارة المرضى وغيرها . ومرت صناعة تنسيق الزهور والورود منذ زمن غير بعيد ، حيث أستخدم في بادىء الأمر ورق مجعد يدعى ) ورق الكَريب ( ومن ثم دخلت في هذه الصناعة مادة البلاستيك ومادة الحرير الصناعي ، والأقمشة القطنية ، أو اللينو ، أو الستن ثم مادة الطحين كعجينة . وغيرها من المواد المختلفة .","وفي بلدنا العراق عمت استعمالات باقات الزهور كما أشرنا في العديد من المناسبات . ومن هذه الأهمية شاع استخدام مواد عديدة في صناعة الزهور أو الأوراد المختلفة منها القماش ، وكثرت المحلات… قوالب معدنية بأحجام مختلفة وأشكالها المتنوعة ، وكل نوع من هذه الأنواع يؤدي غرضاً معيناً في صناعة الزهرة .","قوالب خاصة بالأوراق ، وهي أيضاً مواد معدنية ، تصنع محلياً وهي تتألف من: قطعتين .كما موضح في الأشكال الآتية : بعض الحبوب أو المواد التي تستعمل في صنع المياسم .: طريقة تنشية القماش للحصول على قماش يكون ذا صلاحية مناسبة ، كي نتمكن من عمل الزهرة منه، - : تستخدم طرائق متعددة لهذا الغرض سنتعرض الى بعض منها التنشية بوساطة الغراء الأبيض . - : ً أولا نرفع القماش من الإناء ونضعه على الأطار الخشبي ، لكي يجف .","التنشية بوساطة مادة الجلاتين . - : ً ثانيا نضع المزيج في اناء كبير ونغمر فيه القماش ويفضل الغمر عندما يبرد: المزيج. أحياناً نضيف أصباغ الجوهر المناسبة الى اللون المطلوب . قبل أن نضع القماش: على الاطار في المزيج لحصولنا على لون أوراق الزهرة المراد صنعها . . اطار خشبي تكون أبعاده حسب عرض القماش أو طوله ندق في جوانبه المسامير وذلك لربط القماش بعد أن نقوم بوضع المادة الصمغية أو النشوية على القماش .","ويربط القماش أو يثبت من خلال المسامير حتى يجف ليأخذ القماش الشكل الجديد . طريقة صنع الوردة أو الزهرة - : بعد أن نحصل على قماش صلب بعد التنشية نصنع الزهرة كالآتي نقص القماش على وفق النماذج المعدة لعمل الزهرة ، وهناك » باترونات « مقصوصة خاصة بأنواع الزهور . أو نقوم بقصها من الورق المقوى .","نستخدم القوالب المعدنية في تصنيع الزهرة وذلك بوضعها في القالب والضغط: بوساطة الجزء الثاني من القالب ) بوساطة اليد الخشبية ( لتأخذ شكل القالب المطلوب . نضع الورقة من القماش الخاصة بكل زهرة على المخدة ، ونضع الكاوية ضاغطين عليها حتى نحصل على تكوير ورقة الزهرة بالشكل المطلوب .","نأخذ أسلاكاً رفيعة ، ونضع عليها أنواع الحبوب أو القطن أو أي مادة تشبه شكل: المياسم ، أذ أن لكل زهرة مياسم تختلف عن الأخرى ، ويكون الميسم هو قلب الزهرة . نضع الأوراق المقصوصة من القماش والتي جرى كيها من خلال القوالب ونرصفها الواحدة بعد الأخرى بوساطة الغراء الأبيض أو شدها بالخيط الرفيع ، حتى ننتهي من لف العدد المحدد للأوراق الخاصة بالزهرة . نلف السلك الذي حمل الزهرة ، أما بورق يدعى » الكَريب « أو القماش الأخضر: الخفيف .","تشد الأزهار على شكل باقات مع الاهتمام بطريقة تنسيق الزهور بأشكالها المختلفة. نعرض هذه الباقات في الأماكن المخصصة لها .: : عمل لوحات ورد ) زهور ( من رقائق النحاس وضحنا طريقة صنع الزهور من القماش وبالطريقة والخطوات نفسها يمكننا عمل زهور من رقائق النحاس ، وهذه لا تتطلب التنشية . وعند وضعها في القالب لتتطبع به يتغير لون القطعة النحاسية الى ألوان متعددة وذلك لتأثرها بالحرارة . فتصبح أكثر جمالاً .","وبعد إكمال عمل الزهور وتنظيمها بشكل أغصان يمكن لصقها على قطعة من قماش » القطيفة « وتؤطر لتهيئتها للعرض .","عمل تزيينات للمرايا بوساطة النقوش أو النمنم : يمكن تزيين المرايا باستخدام النقوش المرسومة بشكل إطار يحيط بها : نبدأ برسم الزخرفة أو النقوش من أزهار متنوعة أو غيرها كل حسب إختيار الطلبة، ثم نلصق بعض النمنم أو الخرز الصغيرة جداً بالالوان المختلفة وبشكل منتظم ، بوساطة المادة الصمغية القوية » السيكوتين « ، مع ملاحظة الدقة والنظافة في هذا العمل ، لتنتج نماذج جيدة يمكن استخدامها في تزيين المنزل أو الصف .","ويمكن إستخدام الاصباغ فقط بدلا من الخرز الصغيرة وذلك بوضع ضربات دقيقة وسميكة وهذه تتطلب الدقة والإتقان في العمل ."]}],"plates":["18_1.jpg","18_2.jpg"]},{"id":"19","grade":"الصف الثالث المتوسط","unitName":"الوحدة الرابعة","title":"الصف الثالث المتوسط - الوحدة الرابعة: التذوق وتاريخ الفن","pages":"185–189","objectives":"تنمية معرفة الطالب بموضوع «الصف الثالث المتوسط - الوحدة الرابعة: التذوق وتاريخ الفن» وفهم محاوره وممارساته الفنية كما عرضها دليل المعلم.","specific":["أن يتعرف الطالب إلى محور «زيارة المعارض الفنية والمتاحف واجراء المناقشات لتبادل المعلومات .»."],"tools":"الخامات والأدوات الواردة في الدليل: الألوان.","intro":"تهيئة مقترحة: يعرض المعلم مثالاً من موضوع «الصف الثالث المتوسط - الوحدة الرابعة: التذوق وتاريخ الفن»، ثم يطلب من الطلبة وصف ما يلاحظونه وتحديد الفكرة الفنية التي يعالجها الدرس.","summary":["زيارة المعارض الفنية والمتاحف واجراء المناقشات لتبادل المعلومات .؛ الحركة الفنية المعاصرة في العراق بدأت الحركة التشكيلية في العراق في أوائل هذا القرن . وعلى الرغم من حداثتها، فقد تخطى الفنان المعوقات وأثبت…"],"mcq":[{"n":1,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 1 في ترتيب الدرس؟","options":["زيارة المعارض الفنية والمتاحف واجراء المناقشات لتبادل المعلومات .","موضوع آخر غير وارد في هذا الدرس","موضوع آخر غير وارد في هذا الدرس"],"answer":"أ"}],"truefalse":[{"n":1,"q":"يتناول الدرس موضوع «زيارة المعارض الفنية والمتاحف واجراء المناقشات لتبادل المعلومات .» ضمن محاوره. ( )","answer":"صح"},{"n":2,"q":"يعرض الدليل موضوع «الصف الثالث المتوسط - الوحدة الرابعة: التذوق وتاريخ الفن» ضمن موضوعات التربية الفنية. ( )","answer":"صح"},{"n":3,"q":"يَرِد موضوع «زيارة المعارض الفنية والمتاحف واجراء المناقشات لتبادل المعلومات .» ضمن محتوى هذا الدرس. ( )","answer":"صح"}],"answerKey":" الاختيار من متعدد: 1 ـ أ | الصح والخطأ: 1 ـ صح، 2 ـ صح، 3 ـ صح","topics":["زيارة المعارض الفنية والمتاحف واجراء المناقشات لتبادل المعلومات"],"sections":[{"title":"شرح الدرس","paras":["زيارة المعارض الفنية والمتاحف واجراء المناقشات لتبادل المعلومات . الحركة الفنية المعاصرة في العراق بدأت الحركة التشكيلية في العراق في أوائل هذا القرن . وعلى الرغم من حداثتها، فقد تخطى الفنان المعوقات وأثبت أصالته وصدقه في اداء رسالته .","ويعود الفضل الى عدد من الرسامين الهواة ومن أشهرهم عبد القادر الرسام الذي كان ضابطاً في الجيش العثماني وزملاؤه الحاج محمد سليم ومحمد صالح زكي وعاصم حافظ وغيرهم ممن تعارف على تسميتهم بالأوائل . وقد أثار هؤلاء اهتمام الشباب في الرسم وتم ارسال بعض ذوي المواهب منهم الى اوربا لدراسة الفن ، واخذت سمات بداية الحركة الفنية الجديدة تتبين عند افتتاح فرع الرسم في معهد الفنون الجميلة عام ٩٣٩١ م وتأسيس فرع النحت بعده بمدة وجيزة .","وكان لمعهد الفنون الجميلة ، البداية الحقيقية للتجربة التي تمخضت عنها نهضة الفن العراقي المعاصر ، على الرغم مما عاناه الفنانون من صعوبات متعددة . وقد تشكلت جمعية أصدقاء الفن من عدد من الرسامين والخطاطين والمعماريين والنحاتين والهواة ، وأقامت معرضها الأول في تشرين من عام ١٤٩١ م ، وازداد عدد الرسامين من محترفين وهواة وجعلت معارضهم تدل على تجمعات فنية تتفاوت بأساليبها الفنية.","وأخذت المعارض تزداد وتكثر ، فكان بعضها لهواة الرسم من الكليات أو معارض فردية . وفي عام ٦٥٩١ م ظهرت جمعية الفنانين العراقيين ، وتتالت سنوياً المعارض الكبرى ، التي تمثل الفن العراقي على اختلاف أساليبه ، واستجاب الجمهور للحركة الفنية بحرارة طوال الخمسينات . وفي الستينيات ، تأسست أكاديمية الفنون الجميلة الى جانب معهد الفنون الجميلة.","والحقت بجامعة بغداد ، وتضاعف عدد الموفودين من الطلبة الى خارج العراق لدراسة الرسم والنحت وغيرها من الفنون ، وفي أقل من ربع قرن نمت الحركة الفنية بسرعة على نحو أكسبها شخصية فارقة تمتاز على تعدد أوجهها بالفتوة والجرأة وقوة التعبير. - : ولقد ظهرت في العراق عدة جماعات منها التي ارادت فناً أقرب الى البدائية في وضع الخطوط والألوان ملتفة، - جماعة الرواد حول فائق حسن ، عام ٠٥٩١ م .","لوحة للفنان حافظ الدروبي التي أرادت تصوير واقع الناس بشكل- وظهرت جماعة بغداد للفن الحديث جديد ، ملتفة حول الفنان جواد سليم ، عام ١٥٩١ م . التي أرادت فناً مستقر من الطبيعة والهواء - كما ظهرت جماعة الأنطباعيين الطلق ، ملتفة حول الفنان حافظ الدروبي ، عام ٢٥٩١ م . وقد كان للجماعات الفنية ، بما تقيم من معارض سنوية يتمثل فيها نمو الحركة واتساعها في العراق الفضل في هذا التطور السريع .","وإن المتتبع لمسيرة الحركة الفنية ، يجد أن الهدف الأول كان دائماً الانتاج المستمر، والتجربة المستمرة ، والتطور . ونشطت المؤسسات الفنية ،…"]}],"plates":["19_1.jpg","19_2.jpg"]},{"id":"20","grade":"المرحلة المتوسطة","unitName":"وحدة عامة","title":"مفردات الأنشطة المسرحية","pages":"190–190","objectives":"تنمية معرفة الطالب بموضوع «مفردات الأنشطة المسرحية للمرحلة المتوسطة» وفهم محاوره وممارساته الفنية كما عرضها دليل المعلم.","specific":["أن يتعرف الطالب إلى محور «تمارين في الصوت والإلقاء )مع التأكيد على استرخاء أجهزة النطق ومخارج».","أن يتعرف الطالب إلى محور «التدريب على مسرحة بعض مفردات المناهج وتقديمها )اللغة العربية، العلوم،».","أن يتعرف الطالب إلى محور «( تعليمية عن المهارات الادائية للصوت والجسم واية CD) عرض افلام»."],"tools":"الخامات والأدوات الواردة في الدليل: الصور والنماذج والأمثلة الواردة في صفحات الدليل الخاصة بالموضوع..","intro":"تهيئة مقترحة: يعرض المعلم مثالاً من موضوع «مفردات الأنشطة المسرحية للمرحلة المتوسطة»، ثم يطلب من الطلبة وصف ما يلاحظونه وتحديد الفكرة الفنية التي يعالجها الدرس.","summary":["تمارين في الصوت والإلقاء )مع التأكيد على استرخاء أجهزة النطق ومخارج؛ الحروف(. تمارين مشاهد مسرحية حياتية، مثل: أ. لقاء شخص بعد طول غياب. ب. حوار بين شخصين مختلفين في الرأي )تقبل الرأي الاخر( . ج. الأعمال…","التدريب على مسرحة بعض مفردات المناهج وتقديمها )اللغة العربية، العلوم،؛ التاريخ،...(. عرض مسرحي قصير )نص موجه مناسب للمرحلة العمرية( يتناول: موضوع حقوق الإنسان والحريات والقيم الإنسانية النبيلة )الوفاء،…","( تعليمية عن المهارات الادائية للصوت والجسم واية CD) عرض افلام؛ فعاليات تفيد التمارين المسرحية ."],"mcq":[{"n":1,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 1 في ترتيب الدرس؟","options":["تمارين في الصوت والإلقاء )مع التأكيد على استرخاء أجهزة النطق ومخارج","التدريب على مسرحة بعض مفردات المناهج وتقديمها )اللغة العربية، العلوم","( تعليمية عن المهارات الادائية للصوت والجسم واية CD) عرض افلام"],"answer":"أ"},{"n":2,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 2 في ترتيب الدرس؟","options":["تمارين في الصوت والإلقاء )مع التأكيد على استرخاء أجهزة النطق ومخارج","( تعليمية عن المهارات الادائية للصوت والجسم واية CD) عرض افلام","التدريب على مسرحة بعض مفردات المناهج وتقديمها )اللغة العربية، العلوم"],"answer":"ج"},{"n":3,"q":"أيّ الموضوعات الآتية يمثل المحور رقم 3 في ترتيب الدرس؟","options":["التدريب على مسرحة بعض مفردات المناهج وتقديمها )اللغة العربية، العلوم","( تعليمية عن المهارات الادائية للصوت والجسم واية CD) عرض افلام","تمارين في الصوت والإلقاء )مع التأكيد على استرخاء أجهزة النطق ومخارج"],"answer":"ب"}],"truefalse":[{"n":1,"q":"يتناول الدرس موضوع «تمارين في الصوت والإلقاء )مع التأكيد على استرخاء أجهزة النطق ومخارج» ضمن محاوره. ( )","answer":"صح"},{"n":2,"q":"المحور الأول في ترتيب الدليل هو «التدريب على مسرحة بعض مفردات المناهج وتقديمها )اللغة العربية، العلوم،». ( )","answer":"خطأ"},{"n":3,"q":"يَرِد موضوع «( تعليمية عن المهارات الادائية للصوت والجسم واية CD) عرض افلام» ضمن محتوى هذا الدرس. ( )","answer":"صح"}],"answerKey":" الاختيار من متعدد: 1 ـ أ، 2 ـ ج، 3 ـ ب | الصح والخطأ: 1 ـ صح، 2 ـ خطأ، 3 ـ صح","topics":["تمارين في الصوت والإلقاء )مع التأكيد على استرخاء أجهزة النطق ومخارج","التدريب على مسرحة بعض مفردات المناهج وتقديمها )اللغة العربية، العلوم،","( تعليمية عن المهارات الادائية للصوت والجسم واية CD) عرض افلام"],"sections":[{"title":"تمارين في الصوت والإلقاء )مع التأكيد على استرخاء أجهزة النطق ومخارج","paras":["الحروف(. تمارين مشاهد مسرحية حياتية، مثل: أ. لقاء شخص بعد طول غياب. ب. حوار بين شخصين مختلفين في الرأي )تقبل الرأي الاخر( . ج. الأعمال الواجب القيام بها بعد النهوض من النوم والتهيؤ ليوم مدرسي. د. الخروج من البيت الى المدرسة في صباح يوم ممطر. ه . حضور حفلة ميلاد صديق ... وغيرها."]},{"title":"التدريب على مسرحة بعض مفردات المناهج وتقديمها )اللغة العربية، العلوم،","paras":["التاريخ،...(. عرض مسرحي قصير )نص موجه مناسب للمرحلة العمرية( يتناول: موضوع حقوق الإنسان والحريات والقيم الإنسانية النبيلة )الوفاء، الصدق، الأمانة،التآخي، التسامح, تقبل الرأي الاخر(. ("]},{"title":"( تعليمية عن المهارات الادائية للصوت والجسم واية CD) عرض افلام","paras":["تعليمية عن المهارات الادائية للصوت والجسم واية CD) عرض افلام فعاليات تفيد التمارين المسرحية ."]}],"plates":["20_1.jpg"]}],"plans":[{"name":"التعرف على الطلاب","grade":"الأول المتوسط","kind":"تهيئة","title":"التعرف على الطلاب","objectives":"اعداد الطلاب لمادة التربية الفنية","specific":["معرفة الوعي الادراكي للطلبة باستثمار ميولهم الفطرية"],"tools":["السبورة"],"intro":"التعرف على الطلاب .. والترحيب بهم"},{"name":"المنظور","grade":"الأول المتوسط","kind":"نظري","title":"المنظـــــور","objectives":"أن يفهم الطالب معنى \"المنظور\" و هو طريقة الرسم التي تجعل اللوحة تبدو حقيقية وفيها عمق (كأنها ثلاثية الأبعاد) على ورقة مسطحة.","specific":["يشرح كيف يتغير حجم ووضوح الأشياء عندما تكون بعيدة أو قريبة.","يعرف الطالب ما هو: خط الأفق ونقطة التلاشي."],"tools":["السبورة","وسائل توضيحية","صور فوتوغرافية"],"intro":"استذكار معلومات الدرس السابق وربط الدرس السابق بالدرس الحالي نسأل الطلاب: \"كيف نرسم لوحة على ورقة، ونجعلها تبدو حقيقية؟ كيف نجعل الأشياء القريبة تبدو قريبة والبعيدة تبدو بعيدة؟\" الجواب هو \"المنظور\"، وهذا هو درسنا اليوم.","present":"القاعدة الأولى: كيف نرى الأشياء (الحجم والوضوح) الأشياء القريبة: - تكون كبيرة في الرسمة - تكون واضحة وتفاصيلها دقيقة. - ألوانها قوية وغامقة. الأشياء البعيدة: - تكون صغيرة -تكون غير واضحة مثل الضباب تختفي تفاصيلها - ألوانها تكون باهتة وفاتحة. القاعدة الثانية: أدوات الرسم خط الأفق: - هو خط بالعرض نتخيله، يمثل مستوى نظرنا. - هو الخط الذي نرى فيه السماء تلتقي بالأرض. نقطة التلاشي: - هي نقطة موجودة على خط الأفق. - كل الخطوط المستقيمة (مثل خط سكة القطار أو الشارع) تنتهي عندها وتختفي. واجب بيتي بسيط رسم طريق له نقطة تلاشي وأشجار قريبة وبعيدة مع الطريق"},{"name":"المنظور العملي","grade":"الأول المتوسط","kind":"عملي","title":"درس عملي في المنظور","objectives":"أن يتعرف الطالب على أهمية المنظور كعنصر أساسي في الفن","specific":["تطوير مهارات الرسم لدى الطلبة"],"tools":["السبورة","وسائل توضيحية","صور فوتوغرافية","مصباح"],"intro":"استذكار معلومات الدرس السابق وتوضيح اساسيات يجب الاهتمام بها عند الرسم كنقطة التلاشي وخط الأفق والاجسام القريبة والبعيدة","present":"درس عملي في الرسم وإظهار المنظور في الرسم"},{"name":"الظل والضوء","grade":"الأول المتوسط","kind":"نظري","title":"الظل والضوء","objectives":"أن يتعرف الطالب على أهمية الظل والضوء كعنصر أساسي في الفن التشكيلي وإدراك العلاقة بينهما.","specific":["أن يُعرّف مفهومي الظل والضوء.","أن يُميّز بين مصادر الضوء الطبيعية (الشمس، القمر) والمصادر الصناعية (المصباح، النار).","أن يشرح كيف يتكون الظل الذاتي والظل الساقط لجسم (مثل شجرة)."],"tools":["السبورة","وسائل توضيحية","صور فوتوغرافية","مصباح"],"intro":"استذكار معلومات الدرس السابق وربط الدرس السابق بالدرس الحالي سؤال الطلاب: \"ماذا تلاحظون على المجسم؟ وماذا تلاحظون على الطاولة خلفه؟\" لقيادتهم لمفهوم الظل والضوء.","present":"شرح بسيط عن الظل والضوء: شرح مختصر يوضح وجود الظل والضوء في حياتنا (مثال: ظل الإنسان في الشارع، الظل داخل الغرفة بسبب المصباح). لا يوجد ظل بدون ضوء. المصادر الضوئية (طبيعية وصناعية): * الطبيعية: الشمس، القمر، النجوم. * الصناعية: المصباح، النار، الفانوس، وأي مصدر صناعي باعث للضوء. تحديد الظل على شكل حي (مثال: شجرة): عند سقوط الضوء على شجرة، يتكون الآتي: * منطقة الضوء:الجانب المواجه للمصدر * منطقة الظل: الجانب الآخر من الشجرة حيث يختفي الضوء تدريجياً وصولاً إلى منطقة معتمة * النتيجة: الظل الساقط على الأرض. واجب بيتي رسم منظر طبيعي بسيط وتحديد مناطق الظل والضوء"},{"name":"الظل والضوء العملي","grade":"الأول المتوسط","kind":"عملي","title":"رسم منظر طبيعي مع الظل والضوء","objectives":"أن يتعرف الطالب على أهمية الظل والضوء كعنصر أساسي في الفن","specific":["تطوير مهارات الرسم لدى الطلبة"],"tools":["السبورة","وسائل توضيحية","صور فوتوغرافية","مصباح"],"intro":"استذكار معلومات الدرس السابق وتوضيح اساسيات يجب الاهتمام بها عند الرسم (اتجاه الضوء) وتكوين الظل والضوء كنتيجة للاتجاه.","present":"درس عملي في الرسم وإظهار الظل والضوء في الرسم."},{"name":"الرخرفة","grade":"الأول المتوسط","kind":"نظري","title":"الزخرفة (نظري + عملي)","objectives":"تنمية الذائقة الفنية - تعزيز الهوية الثقافية - تطوير مهارات الإبداع والابتكار -","specific":["أن يُعرّف الطالب \"الزخرفة\" بأسلوبه الخاص أن يعدد الأنواع الرئيسية للزخرفة (هندسية، نباتية، خطية).","أن يلاحظ الأنماط الزخرفية في بيئته المحيطة (مثل المسجد، الأقمشة، أو المباني القديمة)."],"tools":["السبورة","وسائل توضيحية","نماذج مصورة"],"intro":"توجيه الطالب حول أهمية الزخارف واستخدامها","present":"أنواع الزخارف: الزخارف النباتيّة تُستخدم في نقش الجدران والملابس والبرديات . الزخارف الحيوانية وكان يكثر استخدام الزخارف الحيوانية والإنسانية أيضًا في الحضارة الفرعونية الزخارف الكتابية العديد من أنواع الخط العربي مُستخدمة في عصرنا الحالي من أجل الزخرفة فقط مثل الخط الكوفي والفارسي وغيره ، في كتابة الآيات القرآنية والأحاديث النبوية الشريفة وتُستخدم على جدران المساجد وفي المصاحف الزخارف الهندسية يعتمد بشكل أساسي على استخدام الأشكال الهندسية مثل الدوائر والخطوط وغيرها ."},{"name":"الزخرفة عملي","grade":"الأول المتوسط","kind":"عملي","title":"الزخرفة (عملي)","objectives":"تنمية الذائقة الفنية - تعزيز الهوية الثقافية - تطوير مهارات الإبداع والابتكار -","specific":["تطوير مهارات التصميم والرسم لدى الطلبة"],"tools":["السبورة","وسائل توضيحية","نماذج مصورة"],"intro":"استذكار معلومات الدرس السابق وتوضيح اساسيات يجب الاهتمام بها عند عمل الزخارف","present":"درس عملي في الرسم بتصميم زخارف نباتية او حيوانية او هندسية او خطية ."},{"name":"تصميم غلاف كتاب","grade":"الأول المتوسط","kind":"نظري","title":"تصميم غلاف كتـــــــــــاب","objectives":"أن يدرك كيف يمكن للتصميم الجيد أن يجعل الكتاب مميزاً. أن يفهم أن الغلاف \"وسيلة تواصل\" سريعة تخبرنا بموضوع الكتاب. تنمية الذائقة: تقدير أهمية التناسق بين الألوان والأشكال والخطوط.","specific":["ان يعدد العناصر الأربعة الأساسية للغلاف (العنوان، الصورة/الرسم، اسم المؤلف، الألوان) أن يحلل غلاف كتاب بسيط ويحدد عناصره الأربعة أن يُقدر أهمية الغلاف \"كوجه\" للكتاب"],"tools":["السبورة","وسائل توضيحية","نماذج مصورة"],"intro":"سؤال تحفيزي: \"عندما تذهب إلى ( )، ما هو أول شيء يجعلك تختار كتاباً معيناً لتقرأه؟\"","present":"تعريف بسيط: غلاف الكتاب هو \"وجه\" الكتاب. إنه أول شيء نراه ويعطينا الانطباع الأول. مهمة الغلاف هي أن \"ينادينا\" ويخبرنا فوراً عن موضوع الكتاب (هل هو كتاب علوم؟ مغامرات؟). شرح العناصر الأربعة الأساسية (المكونات): - العنوان: يجب أن يكون \"واضحاً \" ومقروءاً. (هو بطل الغلاف). - الصورة / الرسم: يجب أن تكون \"مرتبطة مباشرة\" بالموضوع. (صورة واحدة قوية أفضل من 10 مزدحمة). - اسم المؤلف: يُكتب بخط \"أصغر\" من العنوان. - الألوان : تنقل \"المشاعر\" (ألوان زاهية للحماس، باردة للهدوء). يجب أن تكون متناسقة (لونين أو ثلاثة كافية) وأن يكون لون الخط واضحاً فوق الخلفية. الخلاصة للنجاح: البساطة + الوضوح + فكرة واحدة مباشرة."},{"name":"تصميم غلاف كتاب عملي","grade":"الأول المتوسط","kind":"عملي","title":"تصميم غلاف كتاب","objectives":"تنمية الذائقة الفنية - تطوير مهارات الإبداع والابتكار -","specific":["تطوير مهارات التصميم والرسم لدى الطلبة"],"tools":["السبورة","وسائل توضيحية","نماذج مصورة"],"intro":"استذكار معلومات الدرس السابق وتوضيح اساسيات يجب الاهتمام بها عند عمل التصميم","present":"درس عملي في الرسم بتصميم غلاف كتاب من ابتكار الطالب"}]};
